SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for ai_chat
-- ----------------------------
DROP TABLE IF EXISTS `ai_chat`;
CREATE TABLE `ai_chat` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `user_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户姓名',
  `customer_id` bigint DEFAULT NULL COMMENT '关联客户ID',
  `customer_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联客户姓名',
  `message_type` tinyint NOT NULL COMMENT '消息类型(1:用户消息,2:AI回复,3:系统消息)',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '消息内容',
  `reply_content` text COLLATE utf8mb4_unicode_ci COMMENT 'AI回复内容',
  `reply_time` datetime DEFAULT NULL COMMENT '回复时间',
  `session_id` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会话ID',
  `context` text COLLATE utf8mb4_unicode_ci COMMENT '对话上下文',
  `intent` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '意图识别结果',
  `confidence` decimal(5,2) DEFAULT NULL COMMENT '置信度',
  `sentiment` tinyint DEFAULT NULL COMMENT '情感分析结果(1:积极,2:中性,3:消极)',
  `keywords` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关键词',
  `is_satisfied` tinyint DEFAULT NULL COMMENT '是否满意(0:否,1:是)',
  `satisfaction_score` tinyint DEFAULT NULL COMMENT '满意度评分',
  `feedback` text COLLATE utf8mb4_unicode_ci COMMENT '用户反馈',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志(0:未删除,1:已删除)',
  `version` int NOT NULL DEFAULT '1' COMMENT '版本号',
  PRIMARY KEY (`id`),
  KEY `idx_session_id` (`session_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_message_type` (`message_type`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=175 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI聊天记录表';

-- ----------------------------
-- Records of ai_chat
-- ----------------------------
BEGIN;
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (1, 0, '系统访客', NULL, NULL, 1, '你好', NULL, '2025-11-20 16:42:48', 'session_1763628167558_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-20 16:42:48', '2025-12-31 10:10:04', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (2, 0, '系统访客', NULL, NULL, 2, '您好呀！有任何关于客户管理、业务分析、产品推荐、市场趋势等种业客户管理系统相关的问题，都可以问我哦。 ', '您好呀！有任何关于客户管理、业务分析、产品推荐、市场趋势等种业客户管理系统相关的问题，都可以问我哦。 ', '2025-11-20 16:42:48', 'session_1763628167558_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-20 16:42:48', '2025-12-31 10:10:04', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (3, 0, '系统访客', NULL, NULL, 1, '大豆可以申报植物新品种权吗', NULL, '2025-11-21 14:44:19', 'session_1763628167558_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-21 14:44:19', '2025-12-31 10:10:04', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (4, 0, '系统访客', NULL, NULL, 2, '大豆可以申报植物新品种权。\n\n根据《中华人民共和国植物新品种保护条例》，符合相关条件的植物新品种可以获得植物新品种权，受到法律保护。大豆属于农业植物的范畴，只要满足以下条件就能够申请：\n- **属于国家保护名录范围**：农业部负责制定和公布植物新品种保护名录。大豆是在农业植物新品种保护名录范围内的，所以具备申请的基本前提。 \n- **具有新颖性**：申请品种权的植物新品种在申请日前该品种繁殖材料未被销售，或者经育种者许可，在中国境内销售该品种繁殖材料未超过1年；在中国境外销售藤本植物、林木、果树和观赏树木品种繁殖材料未超过6年，销售其他植物品种繁殖材料未超过4年。\n- **具备特异性**：申请品种权的植物新品种应当明显区别于在递交申请以前已知的植物品种。\n- **具备一致性**：申请品种权的植物新品种经过繁殖，除可以预见的变异外，其相关的特征或者特性一致。\n- **具备稳定性**：申请品种权的植物新品种经过反复繁殖后或者在特定繁殖周期结束时，其相关的特征或者特性保持不变。\n- **有适当命名**：授予品种权的植物新品种应当具备适当的名称，并与相同或者相近的植物属或者种中已知品种的名称相区别。\n\n如果要为大豆申请植物新品种权，需要向国家相关部门提交请求书、说明书和该品种的照片等材料，经过受理、审查等一系列流程，最终由审批机关决定是否授予品种权。 ', '大豆可以申报植物新品种权。\n\n根据《中华人民共和国植物新品种保护条例》，符合相关条件的植物新品种可以获得植物新品种权，受到法律保护。大豆属于农业植物的范畴，只要满足以下条件就能够申请：\n- **属于国家保护名录范围**：农业部负责制定和公布植物新品种保护名录。大豆是在农业植物新品种保护名录范围内的，所以具备申请的基本前提。 \n- **具有新颖性**：申请品种权的植物新品种在申请日前该品种繁殖材料未被销售，或者经育种者许可，在中国境内销售该品种繁殖材料未超过1年；在中国境外销售藤本植物、林木、果树和观赏树木品种繁殖材料未超过6年，销售其他植物品种繁殖材料未超过4年。\n- **具备特异性**：申请品种权的植物新品种应当明显区别于在递交申请以前已知的植物品种。\n- **具备一致性**：申请品种权的植物新品种经过繁殖，除可以预见的变异外，其相关的特征或者特性一致。\n- **具备稳定性**：申请品种权的植物新品种经过反复繁殖后或者在特定繁殖周期结束时，其相关的特征或者特性保持不变。\n- **有适当命名**：授予品种权的植物新品种应当具备适当的名称，并与相同或者相近的植物属或者种中已知品种的名称相区别。\n\n如果要为大豆申请植物新品种权，需要向国家相关部门提交请求书、说明书和该品种的照片等材料，经过受理、审查等一系列流程，最终由审批机关决定是否授予品种权。 ', '2025-11-21 14:44:19', 'session_1763628167558_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-21 14:44:19', '2025-12-31 10:10:04', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (5, 0, '系统访客', NULL, NULL, 1, '鳄梨可以吗', NULL, '2025-11-21 14:45:16', 'session_1763628167558_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-21 14:45:16', '2025-12-31 10:10:04', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (6, 0, '系统访客', NULL, NULL, 2, '鳄梨可以申报植物新品种权，前提是该鳄梨新品种需满足我国关于植物新品种权授予的相关条件：\n\n### 列入保护名录\n根据《中华人民共和国植物新品种保护条例》，申请品种权的植物新品种应当属于国家植物品种保护名录中列举的植物的属或者种。截至2024年7月，鳄梨（又称牛油果）已被列入《农业植物新品种保护名录（第十一批）》，所以在属种方面具备了申请资格。\n\n### 满足授权条件\n- **新颖性**：申请品种权的植物新品种在申请日前该品种繁殖材料未被销售，或者经育种者许可，在中国境内销售该品种繁殖材料未超过1年；在中国境外销售藤本植物、林木、果树和观赏树木品种繁殖材料未超过6年，销售其他植物品种繁殖材料未超过4年。鳄梨属于果树，所以要符合相应的境外销售时间限制。\n - **特异性**：申请品种权的植物新品种应当明显区别于在递交申请以前已知的植物品种。比如在果实大小、形状、颜色、口感、营养成分含量、抗病性等方面与已知鳄梨品种存在显著差异。\n - **一致性**：申请品种权的植物新品种经过繁殖，除可以预见的变异外，其相关的特征或者特性一致。也就是说，通过特定繁殖方式得到的一批鳄梨植株，其在树形、叶片形态、果实特征等方面表现出相对稳定且一致的特征。\n - **稳定性**：申请品种权的植物新品种经过反复繁殖后或者在特定繁殖周期结束时，其相关的特征或者特性保持不变。例如经过多代繁殖，鳄梨的果实品质、产量等关键特征不会发生明显变化。\n - **适当命名**：授予品种权的植物新品种应当具备适当的名称，并与相同或者相近的植物属或者种中已知品种的名称相区别。不能使用仅以数字组成、违反社会公德或者对植物新品种的特征、特性或者育种者的身份等容易引起误解的名称。 \n\n如果满足上述条件，育种者可以准备好请求书、说明书、照片等相关申请文件，向国家农业农村部植物新品种保护办公室提出申请。 ', '鳄梨可以申报植物新品种权，前提是该鳄梨新品种需满足我国关于植物新品种权授予的相关条件：\n\n### 列入保护名录\n根据《中华人民共和国植物新品种保护条例》，申请品种权的植物新品种应当属于国家植物品种保护名录中列举的植物的属或者种。截至2024年7月，鳄梨（又称牛油果）已被列入《农业植物新品种保护名录（第十一批）》，所以在属种方面具备了申请资格。\n\n### 满足授权条件\n- **新颖性**：申请品种权的植物新品种在申请日前该品种繁殖材料未被销售，或者经育种者许可，在中国境内销售该品种繁殖材料未超过1年；在中国境外销售藤本植物、林木、果树和观赏树木品种繁殖材料未超过6年，销售其他植物品种繁殖材料未超过4年。鳄梨属于果树，所以要符合相应的境外销售时间限制。\n - **特异性**：申请品种权的植物新品种应当明显区别于在递交申请以前已知的植物品种。比如在果实大小、形状、颜色、口感、营养成分含量、抗病性等方面与已知鳄梨品种存在显著差异。\n - **一致性**：申请品种权的植物新品种经过繁殖，除可以预见的变异外，其相关的特征或者特性一致。也就是说，通过特定繁殖方式得到的一批鳄梨植株，其在树形、叶片形态、果实特征等方面表现出相对稳定且一致的特征。\n - **稳定性**：申请品种权的植物新品种经过反复繁殖后或者在特定繁殖周期结束时，其相关的特征或者特性保持不变。例如经过多代繁殖，鳄梨的果实品质、产量等关键特征不会发生明显变化。\n - **适当命名**：授予品种权的植物新品种应当具备适当的名称，并与相同或者相近的植物属或者种中已知品种的名称相区别。不能使用仅以数字组成、违反社会公德或者对植物新品种的特征、特性或者育种者的身份等容易引起误解的名称。 \n\n如果满足上述条件，育种者可以准备好请求书、说明书、照片等相关申请文件，向国家农业农村部植物新品种保护办公室提出申请。 ', '2025-11-21 14:45:16', 'session_1763628167558_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-21 14:45:16', '2025-12-31 10:10:04', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (7, 0, '系统访客', NULL, NULL, 1, '给我讲个植物新品种消化', NULL, '2025-11-23 12:48:59', 'session_1763628167558_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-23 12:48:59', '2025-12-31 10:10:04', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (8, 0, '系统访客', NULL, NULL, 2, '我猜你想问的是“植物新品种笑话”，下面给你讲一个轻松有趣的：\n\n### 玫瑰与郁金香的“身高讨论”\n在一个美丽的花园里，住着一朵骄傲的红玫瑰和一株优雅的郁金香。有一天，玫瑰看着旁边的郁金香，轻蔑地说：“你看看我，我可是经过精心培育的新品种玫瑰，我这艳丽的颜色和迷人的香气，谁能比得过？再瞧瞧你，普普通通的。”\n\n郁金香不紧不慢地回答：“是呀是呀，你确实厉害。不过呢，不知道为啥每次园丁来花园，都要弯腰给你修剪，累得直不起腰，估计是你太矮啦，我都不用他费这劲。”\n\n玫瑰听了，气得花瓣都抖了起来，却一时无言以对。 \n\n希望这个小笑话能让你开心！如果你还有其他需求，欢迎随时跟我说。 ', '我猜你想问的是“植物新品种笑话”，下面给你讲一个轻松有趣的：\n\n### 玫瑰与郁金香的“身高讨论”\n在一个美丽的花园里，住着一朵骄傲的红玫瑰和一株优雅的郁金香。有一天，玫瑰看着旁边的郁金香，轻蔑地说：“你看看我，我可是经过精心培育的新品种玫瑰，我这艳丽的颜色和迷人的香气，谁能比得过？再瞧瞧你，普普通通的。”\n\n郁金香不紧不慢地回答：“是呀是呀，你确实厉害。不过呢，不知道为啥每次园丁来花园，都要弯腰给你修剪，累得直不起腰，估计是你太矮啦，我都不用他费这劲。”\n\n玫瑰听了，气得花瓣都抖了起来，却一时无言以对。 \n\n希望这个小笑话能让你开心！如果你还有其他需求，欢迎随时跟我说。 ', '2025-11-23 12:48:59', 'session_1763628167558_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-23 12:48:59', '2025-12-31 10:10:04', '系统访客', '系统访客', 1, 1);
