INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (10, 0, '系统访客', NULL, NULL, 2, '你好呀！要是你还有植物新品种相关的问题，或者想了解其他方面的信息，都能随时问我。 ', '你好呀！要是你还有植物新品种相关的问题，或者想了解其他方面的信息，都能随时问我。 ', '2025-11-24 07:15:37', 'session_1763628167558_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-24 07:15:37', '2025-12-31 10:10:04', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (11, 0, '系统访客', NULL, NULL, 1, '你好，请介绍一下AI客户管理系统', NULL, '2025-11-25 15:02:39', 'session_1764054152960_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-25 15:02:39', '2025-12-31 10:10:06', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (12, 0, '系统访客', NULL, NULL, 2, 'AI客户管理系统是结合人工智能技术的种业客户管理系统。\n\n在客户信息管理上，它能智能收集、整合和分析客户的各类信息，比如购买历史、偏好等，快速精准地构建全面的客户画像。\n\n业务跟进方面，可实现自动化提醒，像提醒销售人员及时跟进潜在客户、处理订单等，还能预测客户需求，助力提前规划业务。\n\n在业务分析上，能对销售数据、市场反馈等进行深度挖掘，生成多维度报表，辅助管理者清晰把握业务状况，制定科学决策。\n\n产品推荐时，依据客户画像和历史数据，为不同客户精准推荐合适的种子产品，提高销售转化率。\n\n市场趋势方面，它可以实时监测市场动态，利用算法分析市场走向，让企业提前布局，增强竞争力。 ', 'AI客户管理系统是结合人工智能技术的种业客户管理系统。\n\n在客户信息管理上，它能智能收集、整合和分析客户的各类信息，比如购买历史、偏好等，快速精准地构建全面的客户画像。\n\n业务跟进方面，可实现自动化提醒，像提醒销售人员及时跟进潜在客户、处理订单等，还能预测客户需求，助力提前规划业务。\n\n在业务分析上，能对销售数据、市场反馈等进行深度挖掘，生成多维度报表，辅助管理者清晰把握业务状况，制定科学决策。\n\n产品推荐时，依据客户画像和历史数据，为不同客户精准推荐合适的种子产品，提高销售转化率。\n\n市场趋势方面，它可以实时监测市场动态，利用算法分析市场走向，让企业提前布局，增强竞争力。 ', '2025-11-25 15:02:39', 'session_1764054152960_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-25 15:02:39', '2025-12-31 10:10:06', '系统访客', '系统访客', 1, 1);
