INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (14, 0, '系统访客', NULL, NULL, 2, '我主要是为种业客户管理系统提供服务呢，没办法直接测试DeepSeek API是否正常工作。你若有关于种业客户管理、业务分析、产品推荐、市场趋势等方面的问题，我会很乐意帮你解答。要是你想测试DeepSeek API，建议你联系人工客服获取更专业的协助。 ', '我主要是为种业客户管理系统提供服务呢，没办法直接测试DeepSeek API是否正常工作。你若有关于种业客户管理、业务分析、产品推荐、市场趋势等方面的问题，我会很乐意帮你解答。要是你想测试DeepSeek API，建议你联系人工客服获取更专业的协助。 ', '2025-11-25 15:03:40', 'session_1764054152960_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-25 15:03:40', '2025-12-31 10:10:06', '系统访客', '系统访客', 1, 1);
