INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (19, 0, '系统访客', NULL, NULL, 1, '你好，你是王志勇？', NULL, '2025-11-30 22:29:18', 'session_1764054152960_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-30 22:29:18', '2025-12-31 10:10:06', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (20, 0, '系统访客', NULL, NULL, 2, '我不是王志勇哦，我是豆包，能为你提供各种信息和帮助。如果你有关于AI客户管理系统、种业相关业务等方面的问题，都可以随时问我。 ', '我不是王志勇哦，我是豆包，能为你提供各种信息和帮助。如果你有关于AI客户管理系统、种业相关业务等方面的问题，都可以随时问我。 ', '2025-11-30 22:29:18', 'session_1764054152960_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-30 22:29:18', '2025-12-31 10:10:06', '系统访客', '系统访客', 1, 1);
