INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (22, 0, '系统访客', NULL, NULL, 2, '你好呀！要是你还有关于植物新品种权申报，像鳄梨、大豆这类植物更多细节的疑问，或者有其他新鲜想法，都能跟我说说。 ', '你好呀！要是你还有关于植物新品种权申报，像鳄梨、大豆这类植物更多细节的疑问，或者有其他新鲜想法，都能跟我说说。 ', '2025-12-03 16:06:07', 'session_1763628167558_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-03 16:06:07', '2025-12-31 10:10:04', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (23, 0, '系统访客', NULL, NULL, 1, '能给我介绍下如何申报知识植物新品种知识产权吗', NULL, '2025-12-03 16:06:39', 'session_1763628167558_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-03 16:06:39', '2025-12-31 10:10:04', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (24, 0, '系统访客', NULL, NULL, 2, '申报植物新品种知识产权，即申请植物新品种权，一般需要经过以下步骤：\n\n### 申请前的准备\n#### 确认品种符合授权条件\n- **新颖性**：申请品种权的植物新品种在申请日前该品种繁殖材料未被销售，或经育种者许可，在中国境内销售该品种繁殖材料未超过1年；在中国境外销售藤本植物、林木、果树和观赏树木品种繁殖材料未超过6年，销售其他植物品种繁殖材料未超过4年。\n- **特异性**：明显区别于递交申请以前已知的植物品种。\n- **一致性**：经过繁殖，除可以预见的变异外，其相关的特征或者特性一致。\n- **稳定性**：经过反复繁殖后或者在特定繁殖周期结束时，其相关的特征或者特性保持不变。\n- **适当命名**：授予品种权的植物新品种应当具备适当的名称，并与相同或者相近的植物属或者种中已知品种的名称相区别。\n\n#### 查询是否属于保护名录范围\n确认申请的植物品种属于国家公布的植物新品种保护名录中列举的植物属或种。农业植物新品种保护由农业农村部负责，林业植物新品种保护由国家林业和草原局负责。\n\n### 申请材料准备\n#### 申请文件\n- **请求书**：应包括品种暂定名称、品种所属的属或者种的中文名称和拉丁文名称、培育人姓名、申请人姓名或者名称、地址、邮政编码、联系人、联系电话、传真、国籍、申请人的身份（个人或单位）等信息。\n- **说明书**：包括对新品种的详细描述，如该品种与已知品种的特征对比、繁殖方式、栽培技术要点等。\n- **照片**：提供该植物新品种的整体植株、花、果实等具有代表性部位的清晰照片，照片要能体现该品种的特异性特征。\n\n### 提交申请\n#### 选择申请途径\n- **自行申请**：申请人可以直接向农业农村部植物新品种保护办公室（针对农业植物）或国家林业和草原局植物新品种保护办公室（针对林业植物）提交申请材料。\n- **委托代理机构**：如果申请人对申请流程不熟悉，可以委托有资质的植物新品种代理机构办理申请事宜。\n\n#### 缴纳申请费\n在提交申请的同时，需要按照规定缴纳申请费。费用标准根据不同的植物类别有所不同。\n\n### 审查阶段\n#### 形式审查\n- 审批机关收到申请后，首先对申请材料进行形式审查，主要检查申请文件是否齐全、格式是否符合要求、是否缴纳申请费等。\n- 如果申请文件存在缺陷，审批机关会通知申请人在规定的期限内补正。\n\n#### 实质审查\n- 形式审查合格后，进入实质审查阶段。审批机关会对该品种的新颖性、特异性、一致性和稳定性进行审查。\n- 可能需要进行田间测试，以验证品种的特征特性。田间测试通常需要一定的时间和周期，以确保品种的稳定性和一致性。\n\n### 授权与公告\n- **授予品种权**：经过审查，符合授权条件的，审批机关将作出授予品种权的决定，颁发品种权证书，并予以登记和公告。\n- **缴纳相关费用**：申请人在收到授予品种权的通知后，需要按照规定缴纳证书费和第一年年费。\n\n### 维护品种权\n获得品种权后，权利人需要按照规定每年缴纳年费，以维持品种权的有效性。同时，要注意保护自己的品种权，防止他人未经许可的生产、销售等侵权行为。 ', '申报植物新品种知识产权，即申请植物新品种权，一般需要经过以下步骤：\n\n### 申请前的准备\n#### 确认品种符合授权条件\n- **新颖性**：申请品种权的植物新品种在申请日前该品种繁殖材料未被销售，或经育种者许可，在中国境内销售该品种繁殖材料未超过1年；在中国境外销售藤本植物、林木、果树和观赏树木品种繁殖材料未超过6年，销售其他植物品种繁殖材料未超过4年。\n- **特异性**：明显区别于递交申请以前已知的植物品种。\n- **一致性**：经过繁殖，除可以预见的变异外，其相关的特征或者特性一致。\n- **稳定性**：经过反复繁殖后或者在特定繁殖周期结束时，其相关的特征或者特性保持不变。\n- **适当命名**：授予品种权的植物新品种应当具备适当的名称，并与相同或者相近的植物属或者种中已知品种的名称相区别。\n\n#### 查询是否属于保护名录范围\n确认申请的植物品种属于国家公布的植物新品种保护名录中列举的植物属或种。农业植物新品种保护由农业农村部负责，林业植物新品种保护由国家林业和草原局负责。\n\n### 申请材料准备\n#### 申请文件\n- **请求书**：应包括品种暂定名称、品种所属的属或者种的中文名称和拉丁文名称、培育人姓名、申请人姓名或者名称、地址、邮政编码、联系人、联系电话、传真、国籍、申请人的身份（个人或单位）等信息。\n- **说明书**：包括对新品种的详细描述，如该品种与已知品种的特征对比、繁殖方式、栽培技术要点等。\n- **照片**：提供该植物新品种的整体植株、花、果实等具有代表性部位的清晰照片，照片要能体现该品种的特异性特征。\n\n### 提交申请\n#### 选择申请途径\n- **自行申请**：申请人可以直接向农业农村部植物新品种保护办公室（针对农业植物）或国家林业和草原局植物新品种保护办公室（针对林业植物）提交申请材料。\n- **委托代理机构**：如果申请人对申请流程不熟悉，可以委托有资质的植物新品种代理机构办理申请事宜。\n\n#### 缴纳申请费\n在提交申请的同时，需要按照规定缴纳申请费。费用标准根据不同的植物类别有所不同。\n\n### 审查阶段\n#### 形式审查\n- 审批机关收到申请后，首先对申请材料进行形式审查，主要检查申请文件是否齐全、格式是否符合要求、是否缴纳申请费等。\n- 如果申请文件存在缺陷，审批机关会通知申请人在规定的期限内补正。\n\n#### 实质审查\n- 形式审查合格后，进入实质审查阶段。审批机关会对该品种的新颖性、特异性、一致性和稳定性进行审查。\n- 可能需要进行田间测试，以验证品种的特征特性。田间测试通常需要一定的时间和周期，以确保品种的稳定性和一致性。\n\n### 授权与公告\n- **授予品种权**：经过审查，符合授权条件的，审批机关将作出授予品种权的决定，颁发品种权证书，并予以登记和公告。\n- **缴纳相关费用**：申请人在收到授予品种权的通知后，需要按照规定缴纳证书费和第一年年费。\n\n### 维护品种权\n获得品种权后，权利人需要按照规定每年缴纳年费，以维持品种权的有效性。同时，要注意保护自己的品种权，防止他人未经许可的生产、销售等侵权行为。 ', '2025-12-03 16:06:39', 'session_1763628167558_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-03 16:06:39', '2025-12-31 10:10:04', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (25, 0, '系统访客', NULL, NULL, 1, '如何申请植物新品种保护', NULL, '2025-12-03 16:42:28', 'session_1764751332921_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-03 16:42:28', '2025-12-31 10:09:57', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (26, 0, '系统访客', NULL, NULL, 2, '申请植物新品种保护一般有以下步骤：\n1. 确认品种具备新颖性、特异性、一致性和稳定性，拥有适当命名。\n2. 准备申请文件，包括请求书、说明书、照片等。\n3. 向国家林业和草原局或农业农村部植物新品种保护办公室提交申请。\n4. 相关部门会对申请进行形式审查，若不符合要求会通知补正。\n5. 形式审查合格后，进入实质审查阶段，可能需要进行田间测试等。\n6. 经审查通过，将授予植物新品种权并公告。\n\n具体要求和流程可能因品种类型等因素有差异，你也可联系人工客服获取更精准详细的指导。 ', '申请植物新品种保护一般有以下步骤：\n1. 确认品种具备新颖性、特异性、一致性和稳定性，拥有适当命名。\n2. 准备申请文件，包括请求书、说明书、照片等。\n3. 向国家林业和草原局或农业农村部植物新品种保护办公室提交申请。\n4. 相关部门会对申请进行形式审查，若不符合要求会通知补正。\n5. 形式审查合格后，进入实质审查阶段，可能需要进行田间测试等。\n6. 经审查通过，将授予植物新品种权并公告。\n\n具体要求和流程可能因品种类型等因素有差异，你也可联系人工客服获取更精准详细的指导。 ', '2025-12-03 16:42:28', 'session_1764751332921_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-03 16:42:28', '2025-12-31 10:09:57', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (27, 0, '系统访客', NULL, NULL, 1, '植物新品种保护知识产权申请过程需要哪些材料', NULL, '2025-12-03 16:42:55', 'session_1764751332921_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-03 16:42:55', '2025-12-31 10:09:57', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (28, 0, '系统访客', NULL, NULL, 2, '在我国，不同类型植物（农业植物、林业植物）新品种保护知识产权的申请过程所需材料大致相同，但主管部门有所差异，农业植物新品种向农业农村部植物新品种保护办公室申请，林业植物新品种向国家林业和草原局植物新品种保护办公室申请。以下为你介绍申请所需的主要材料：\n\n### 申请书\n需要填写植物新品种权请求书，内容涵盖新品种的名称、所属属或者种的中文名称和拉丁文名称、培育人姓名、申请人姓名或者名称、地址、国籍，以及新品种的培育起止日期和主要培育地等信息。\n\n### 说明书\n- **新品种的详细信息**：包括新品种所属的属或者种的中文名称和拉丁文名称、新品种的亲本以及其他繁殖材料来源与名称等。\n- **育种过程和方法**：详细描述培育该新品种的过程，包括采取的育种方法，如杂交育种、诱变育种等，以及各阶段的时间节点和操作步骤。\n- **特异性描述**：说明该新品种区别于同一属或者种的已知品种的特征特性，要突出其独特之处。\n- **繁殖方式**：明确该新品种是通过有性繁殖还是无性繁殖，以及具体的繁殖方法，如种子繁殖、扦插繁殖、嫁接繁殖等。\n- **栽培技术要点**：提供适合该新品种生长的栽培技术，包括土壤条件、施肥要求、灌溉方法、病虫害防治等方面的内容。\n\n### 照片\n- **数量和要求**：提供该植物新品种的照片，照片数量一般为4 - 10张，要清晰、完整地反映新品种的特异性。\n- **内容要求**：照片应包括植株的整体形态、叶片、花朵、果实等具有代表性的部位，能够充分展示新品种的特征特性。同时，照片上要标注拍摄的时间、地点、拍摄人等信息。\n\n### 证明材料\n- **身份信息**：申请人为个人的，需提供身份证明文件复印件；申请人为单位的，需提供营业执照副本复印件等相关证明材料。\n- **培育人资格证明**：培育人的姓名、地址、国籍等信息，以及培育人对该新品种的培育贡献证明。\n- **代理委托书**：如果委托代理机构办理申请手续，需要提交代理委托书，明确委托事项和权限。\n- **新颖性证明材料**：对于在申请日前该品种未曾销售的证明材料，如销售记录、生产记录等，以证明其符合新颖性要求。 ', '在我国，不同类型植物（农业植物、林业植物）新品种保护知识产权的申请过程所需材料大致相同，但主管部门有所差异，农业植物新品种向农业农村部植物新品种保护办公室申请，林业植物新品种向国家林业和草原局植物新品种保护办公室申请。以下为你介绍申请所需的主要材料：\n\n### 申请书\n需要填写植物新品种权请求书，内容涵盖新品种的名称、所属属或者种的中文名称和拉丁文名称、培育人姓名、申请人姓名或者名称、地址、国籍，以及新品种的培育起止日期和主要培育地等信息。\n\n### 说明书\n- **新品种的详细信息**：包括新品种所属的属或者种的中文名称和拉丁文名称、新品种的亲本以及其他繁殖材料来源与名称等。\n- **育种过程和方法**：详细描述培育该新品种的过程，包括采取的育种方法，如杂交育种、诱变育种等，以及各阶段的时间节点和操作步骤。\n- **特异性描述**：说明该新品种区别于同一属或者种的已知品种的特征特性，要突出其独特之处。\n- **繁殖方式**：明确该新品种是通过有性繁殖还是无性繁殖，以及具体的繁殖方法，如种子繁殖、扦插繁殖、嫁接繁殖等。\n- **栽培技术要点**：提供适合该新品种生长的栽培技术，包括土壤条件、施肥要求、灌溉方法、病虫害防治等方面的内容。\n\n### 照片\n- **数量和要求**：提供该植物新品种的照片，照片数量一般为4 - 10张，要清晰、完整地反映新品种的特异性。\n- **内容要求**：照片应包括植株的整体形态、叶片、花朵、果实等具有代表性的部位，能够充分展示新品种的特征特性。同时，照片上要标注拍摄的时间、地点、拍摄人等信息。\n\n### 证明材料\n- **身份信息**：申请人为个人的，需提供身份证明文件复印件；申请人为单位的，需提供营业执照副本复印件等相关证明材料。\n- **培育人资格证明**：培育人的姓名、地址、国籍等信息，以及培育人对该新品种的培育贡献证明。\n- **代理委托书**：如果委托代理机构办理申请手续，需要提交代理委托书，明确委托事项和权限。\n- **新颖性证明材料**：对于在申请日前该品种未曾销售的证明材料，如销售记录、生产记录等，以证明其符合新颖性要求。 ', '2025-12-03 16:42:55', 'session_1764751332921_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-03 16:42:55', '2025-12-31 10:09:57', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (29, 0, '系统访客', NULL, NULL, 1, '植物新品种保护 如何实现一致性', NULL, '2025-12-03 16:58:00', 'session_1764751332921_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-03 16:58:00', '2025-12-31 10:09:57', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (30, 0, '系统访客', NULL, NULL, 2, '在植物新品种保护中，实现一致性对于确保品种的稳定性和可识别性至关重要，可从育种环节、繁殖过程、质量控制、检测与评估等方面入手，以下为你详细介绍：\n\n### 育种环节\n- **亲本选择**：挑选具有优良且稳定遗传特性的亲本材料。这些亲本自身的性状一致性要好，能够将相对稳定的基因传递给子代，从而为新品种的一致性奠定基础。例如在小麦育种中，选择株高、穗型、粒型等性状稳定的亲本进行杂交，有助于子代保持相对一致的特征。\n- **育种方法**：采用合适的育种技术，如系谱法、混合选择法等。系谱法在育种过程中对每一代的植株进行详细记录和选择，保留具有目标性状且表现一致的单株继续繁殖，经过多代选育，使品种的遗传组成逐渐纯合，从而实现性状的一致性。\n\n### 繁殖过程\n- **繁殖方式**：根据品种的特点选择适宜的繁殖方式，无性繁殖（如扦插、嫁接、组培等）能够最大程度地保持母本的遗传特性，从而保证后代植株在性状上的高度一致。例如，通过扦插繁殖的月季，其后代能够很好地保持母本的花型、花色等特征。\n- **繁殖条件控制**：在繁殖过程中，要严格控制环境条件，包括温度、湿度、光照、土壤肥力等。保持这些环境因素的相对稳定，有助于减少因环境差异导致的植株生长不一致。例如，在组培育苗时，精确控制培养室的温度和光照时间，能够使组培苗生长整齐一致。\n\n### 质量控制\n- **种子或繁殖材料质量**：确保用于繁殖的种子或其他繁殖材料具有较高的质量和纯度。对种子进行严格的筛选、检验和分级，去除杂质、瘪粒和带病种子，保证每一粒种子都具有良好的发芽能力和遗传一致性。\n- **生产过程监控**：在新品种的生产过程中，建立完善的质量监控体系。定期对田间植株的生长情况进行检查，及时发现并处理生长异常的植株，保证整个群体的一致性。例如，在果树种植中，定期检查果树的树形、挂果情况等，对不符合要求的植株进行修剪或调整管理措施。\n\n### 检测与评估\n- **田间测试**：按照相关规定和标准，进行田间小区种植测试。设置多个重复小区，在相同的栽培条件下种植新品种，观察和测量植株的各种性状，如株高、叶长、花期、产量等，通过统计分析来评估品种的一致性。一般需要连续种植多代，以确保品种在不同世代间的一致性表现稳定。\n- **实验室检测**：运用分子生物学技术，如DNA指纹图谱分析等，对新品种的遗传物质进行检测。通过比较不同植株的DNA指纹图谱，可以准确判断它们在遗传水平上的一致性。这种方法具有快速、准确的特点，能够在早期对品种的一致性进行评估。 ', '在植物新品种保护中，实现一致性对于确保品种的稳定性和可识别性至关重要，可从育种环节、繁殖过程、质量控制、检测与评估等方面入手，以下为你详细介绍：\n\n### 育种环节\n- **亲本选择**：挑选具有优良且稳定遗传特性的亲本材料。这些亲本自身的性状一致性要好，能够将相对稳定的基因传递给子代，从而为新品种的一致性奠定基础。例如在小麦育种中，选择株高、穗型、粒型等性状稳定的亲本进行杂交，有助于子代保持相对一致的特征。\n- **育种方法**：采用合适的育种技术，如系谱法、混合选择法等。系谱法在育种过程中对每一代的植株进行详细记录和选择，保留具有目标性状且表现一致的单株继续繁殖，经过多代选育，使品种的遗传组成逐渐纯合，从而实现性状的一致性。\n\n### 繁殖过程\n- **繁殖方式**：根据品种的特点选择适宜的繁殖方式，无性繁殖（如扦插、嫁接、组培等）能够最大程度地保持母本的遗传特性，从而保证后代植株在性状上的高度一致。例如，通过扦插繁殖的月季，其后代能够很好地保持母本的花型、花色等特征。\n- **繁殖条件控制**：在繁殖过程中，要严格控制环境条件，包括温度、湿度、光照、土壤肥力等。保持这些环境因素的相对稳定，有助于减少因环境差异导致的植株生长不一致。例如，在组培育苗时，精确控制培养室的温度和光照时间，能够使组培苗生长整齐一致。\n\n### 质量控制\n- **种子或繁殖材料质量**：确保用于繁殖的种子或其他繁殖材料具有较高的质量和纯度。对种子进行严格的筛选、检验和分级，去除杂质、瘪粒和带病种子，保证每一粒种子都具有良好的发芽能力和遗传一致性。\n- **生产过程监控**：在新品种的生产过程中，建立完善的质量监控体系。定期对田间植株的生长情况进行检查，及时发现并处理生长异常的植株，保证整个群体的一致性。例如，在果树种植中，定期检查果树的树形、挂果情况等，对不符合要求的植株进行修剪或调整管理措施。\n\n### 检测与评估\n- **田间测试**：按照相关规定和标准，进行田间小区种植测试。设置多个重复小区，在相同的栽培条件下种植新品种，观察和测量植株的各种性状，如株高、叶长、花期、产量等，通过统计分析来评估品种的一致性。一般需要连续种植多代，以确保品种在不同世代间的一致性表现稳定。\n- **实验室检测**：运用分子生物学技术，如DNA指纹图谱分析等，对新品种的遗传物质进行检测。通过比较不同植株的DNA指纹图谱，可以准确判断它们在遗传水平上的一致性。这种方法具有快速、准确的特点，能够在早期对品种的一致性进行评估。 ', '2025-12-03 16:58:00', 'session_1764751332921_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-03 16:58:00', '2025-12-31 10:09:57', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (31, 0, '系统访客', NULL, NULL, 1, '新品种多少种', NULL, '2025-12-04 23:44:46', 'session_1764751332921_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-04 23:44:46', '2025-12-31 10:09:57', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (32, 0, '系统访客', NULL, NULL, 2, '目前全球范围内植物新品种数量众多且不断动态变化，并没有一个确切的统计数字。以下从我国农业、林业两方面介绍新品种情况：\n\n### 农业领域\n根据农业农村部发布的数据，截至2024年7月，我国累计授权农业植物新品种达4.5万余个。涉及的种类丰富，包括粮食作物如水稻、小麦、玉米；经济作物如棉花、大豆、油菜；以及蔬菜如黄瓜、番茄、辣椒等众多品类。\n\n### 林业领域\n截至2023年底，国家林业和草原局累计授权植物新品种2361件。涵盖了多种林木、花卉等，比如杨树、杉木等用材树种，以及牡丹、月季等观赏花卉。 ', '目前全球范围内植物新品种数量众多且不断动态变化，并没有一个确切的统计数字。以下从我国农业、林业两方面介绍新品种情况：\n\n### 农业领域\n根据农业农村部发布的数据，截至2024年7月，我国累计授权农业植物新品种达4.5万余个。涉及的种类丰富，包括粮食作物如水稻、小麦、玉米；经济作物如棉花、大豆、油菜；以及蔬菜如黄瓜、番茄、辣椒等众多品类。\n\n### 林业领域\n截至2023年底，国家林业和草原局累计授权植物新品种2361件。涵盖了多种林木、花卉等，比如杨树、杉木等用材树种，以及牡丹、月季等观赏花卉。 ', '2025-12-04 23:44:46', 'session_1764751332921_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-04 23:44:46', '2025-12-31 10:09:57', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (33, 0, '系统访客', NULL, NULL, 1, '新品种多少种', NULL, '2025-12-04 23:47:03', 'session_1764751332921_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-04 23:47:03', '2025-12-31 10:09:57', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (34, 0, '系统访客', NULL, NULL, 2, '由于植物新品种在持续不断地培育和增加，且统计数据实时变动，很难给出一个精确的全球植物新品种总数。以下为你列举不同主体公布的部分数据：\n### 全球层面\n国际植物新品种保护联盟（UPOV）并没有直接公布具体的新品种数量，但截至2024年7月，UPOV有78个成员国，各成员国依据相关法规对植物新品种进行保护和授权，每年都会有大量新的品种被培育和申请保护。\n### 中国层面\n- **农业植物新品种**：截至2024年7月，农业农村部累计授权农业植物新品种达4.5万余个，涵盖粮食、蔬菜、水果、花卉等众多类别。例如玉米、水稻、小麦等主要粮食作物，以及黄瓜、番茄、辣椒等常见蔬菜品种。\n- **林业植物新品种**：截至2023年底，国家林业和草原局累计授权植物新品种2361件，包含杨树、杉木等用材树种，以及牡丹、月季、兰花等观赏植物。 ', '由于植物新品种在持续不断地培育和增加，且统计数据实时变动，很难给出一个精确的全球植物新品种总数。以下为你列举不同主体公布的部分数据：\n### 全球层面\n国际植物新品种保护联盟（UPOV）并没有直接公布具体的新品种数量，但截至2024年7月，UPOV有78个成员国，各成员国依据相关法规对植物新品种进行保护和授权，每年都会有大量新的品种被培育和申请保护。\n### 中国层面\n- **农业植物新品种**：截至2024年7月，农业农村部累计授权农业植物新品种达4.5万余个，涵盖粮食、蔬菜、水果、花卉等众多类别。例如玉米、水稻、小麦等主要粮食作物，以及黄瓜、番茄、辣椒等常见蔬菜品种。\n- **林业植物新品种**：截至2023年底，国家林业和草原局累计授权植物新品种2361件，包含杨树、杉木等用材树种，以及牡丹、月季、兰花等观赏植物。 ', '2025-12-04 23:47:03', 'session_1764751332921_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-04 23:47:03', '2025-12-31 10:09:57', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (35, 0, '系统访客', NULL, NULL, 1, '新品种多少种', NULL, '2025-12-04 23:50:17', 'session_1764751332921_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-04 23:50:17', '2025-12-31 10:09:57', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (36, 0, '系统访客', NULL, NULL, 2, '由于植物新品种持续诞生且不同统计渠道和时间的统计结果有差异，很难给出一个精准的全球植物新品种确切数量。以下从不同角度为你介绍相关情况：\n\n### 国际情况\n国际植物新品种保护联盟（UPOV ）涵盖了众多成员国，各成员国每年都会有大量新的植物品种申请保护和获得授权。但 UPOV 并未公布全球植物新品种的具体数量。随着育种技术的发展，全球每年新培育的植物品种数量众多且不断增长。\n\n### 中国情况\n - **农业植物新品种**：截至2024年7月，农业农村部已受理植物新品种权申请突破8万件，累计授权4.5万余件。涉及粮食作物（如小麦、水稻、玉米）、经济作物（如棉花、大豆）、蔬菜（如白菜、萝卜）、果树（如苹果、梨）、花卉（如玫瑰、百合）等多种类型。\n - **林业植物新品种**：截至2023年底，国家林业和草原局累计受理植物新品种权申请5411件，授权2361件。包括银杏、杨树等用材树种，以及牡丹、杜鹃、兰花等观赏植物品种。 ', '由于植物新品种持续诞生且不同统计渠道和时间的统计结果有差异，很难给出一个精准的全球植物新品种确切数量。以下从不同角度为你介绍相关情况：\n\n### 国际情况\n国际植物新品种保护联盟（UPOV ）涵盖了众多成员国，各成员国每年都会有大量新的植物品种申请保护和获得授权。但 UPOV 并未公布全球植物新品种的具体数量。随着育种技术的发展，全球每年新培育的植物品种数量众多且不断增长。\n\n### 中国情况\n - **农业植物新品种**：截至2024年7月，农业农村部已受理植物新品种权申请突破8万件，累计授权4.5万余件。涉及粮食作物（如小麦、水稻、玉米）、经济作物（如棉花、大豆）、蔬菜（如白菜、萝卜）、果树（如苹果、梨）、花卉（如玫瑰、百合）等多种类型。\n - **林业植物新品种**：截至2023年底，国家林业和草原局累计受理植物新品种权申请5411件，授权2361件。包括银杏、杨树等用材树种，以及牡丹、杜鹃、兰花等观赏植物品种。 ', '2025-12-04 23:50:17', 'session_1764751332921_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-04 23:50:17', '2025-12-31 10:09:57', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (37, 0, '系统访客', NULL, NULL, 1, '什么是非主要农作物？', NULL, '2025-12-05 15:07:51', 'session_1764751332921_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-05 15:07:51', '2025-12-31 10:09:57', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (38, 0, '系统访客', NULL, NULL, 2, '非主要农作物是指稻、小麦、玉米、棉花、大豆这五种主要农作物之外的其他农作物。\n\n(来源: 常见问题库)', '非主要农作物是指稻、小麦、玉米、棉花、大豆这五种主要农作物之外的其他农作物。\n\n(来源: 常见问题库)', '2025-12-05 15:07:51', 'session_1764751332921_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-05 15:07:51', '2025-12-31 10:09:57', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (39, 0, '系统访客', NULL, NULL, 1, '什么是植物新品种权？', NULL, '2025-12-05 15:08:23', 'session_1764751332921_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-05 15:08:23', '2025-12-31 10:09:57', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (40, 0, '系统访客', NULL, NULL, 2, '植物新品种权（Plant Variety Rights）简称品种权，也称植物育种者权利（Plant Breeder Rights，PBR），是指完成育种的单位和个人对其获得授权的品种，享有排他的独占权，未经许可，任何人不得以商业目的生产、销售或重复使用该授权品种的繁殖材料。\n\n(来源: 常见问题库)', '植物新品种权（Plant Variety Rights）简称品种权，也称植物育种者权利（Plant Breeder Rights，PBR），是指完成育种的单位和个人对其获得授权的品种，享有排他的独占权，未经许可，任何人不得以商业目的生产、销售或重复使用该授权品种的繁殖材料。\n\n(来源: 常见问题库)', '2025-12-05 15:08:23', 'session_1764751332921_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-05 15:08:23', '2025-12-31 10:09:57', '系统访客', '系统访客', 1, 1);
