INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (42, 0, '系统访客', NULL, NULL, 2, '你好！如果你还有关于植物新品种权、植物新品种申请保护，或者其他方面的问题，都可以随时跟我说。 ', '你好！如果你还有关于植物新品种权、植物新品种申请保护，或者其他方面的问题，都可以随时跟我说。 ', '2025-12-05 15:08:31', 'session_1764751332921_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-05 15:08:31', '2025-12-31 10:09:57', '系统访客', '系统访客', 1, 1);
