INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (44, 0, '系统访客', NULL, NULL, 2, '植物新品种权（Plant Variety Rights）简称品种权，也称植物育种者权利（Plant Breeder Rights，PBR），是指完成育种的单位和个人对其获得授权的品种，享有排他的独占权，未经许可，任何人不得以商业目的生产、销售或重复使用该授权品种的繁殖材料。\n\n(来源: 常见问题库)', '植物新品种权（Plant Variety Rights）简称品种权，也称植物育种者权利（Plant Breeder Rights，PBR），是指完成育种的单位和个人对其获得授权的品种，享有排他的独占权，未经许可，任何人不得以商业目的生产、销售或重复使用该授权品种的繁殖材料。\n\n(来源: 常见问题库)', '2025-12-05 15:10:49', 'session_1764751332921_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-05 15:10:49', '2025-12-31 10:09:57', '系统访客', '系统访客', 1, 1);
