INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (124, 0, '系统访客', NULL, NULL, 2, 'MBA高校篮球自由积分赛的相关内容如下：\n### 比赛性质\n这是一个完全自由的MBA篮球积分赛，不设固定赛程，不用赛前报备，不限定比赛时间，打就有积分。参赛队伍可以随时和别的队约球，打完只需上传结果，系统自动累计积分，每3个月统一排名，半年进行一次颁奖。\n\n### 参赛人员\n本校在读学生或已毕业校友自由组队，每队5 - 12人，赛季内一队固定，不可重复报名。\n\n### 比赛进行方式\n各队自行约战，比赛形式以5v5为主，场地、时间双方自行协商，不设统一裁判，双方认可结果即可有效。\n\n### 成绩上传\n这是唯一必须做的事。比赛结束后，提交双方队名、最终比分、现场合影这3项即可计分。审核通过后自动加分，未提交成绩则该场不计分。\n\n### 积分规则\n - 赢：+3分\n - 输：+1分\n - 无效成绩：0分\n\n核心原则是只要参赛就一定有分。\n\n### 防刷分规则\n每队每天最多记1场，同一对手一周最多记1场，其余时间完全自由。\n\n### 赛季与排名\n一个赛季为3个月，按总积分从高到低排名。若积分相同，先看胜场，再看参赛场次。半年积分前三名和挑战者队伍一名，四队进行冠亚军季军争夺。\n\n### 奖项设置（每赛季一次）\n - 冠军\n - 亚军\n - 季军\n - 最活跃球队（比赛场次最多）\n\n### 违规说明\n - 造假比分：本场0分+警告\n - 打架斗殴：直接取消本赛季资格 ', 'MBA高校篮球自由积分赛的相关内容如下：\n### 比赛性质\n这是一个完全自由的MBA篮球积分赛，不设固定赛程，不用赛前报备，不限定比赛时间，打就有积分。参赛队伍可以随时和别的队约球，打完只需上传结果，系统自动累计积分，每3个月统一排名，半年进行一次颁奖。\n\n### 参赛人员\n本校在读学生或已毕业校友自由组队，每队5 - 12人，赛季内一队固定，不可重复报名。\n\n### 比赛进行方式\n各队自行约战，比赛形式以5v5为主，场地、时间双方自行协商，不设统一裁判，双方认可结果即可有效。\n\n### 成绩上传\n这是唯一必须做的事。比赛结束后，提交双方队名、最终比分、现场合影这3项即可计分。审核通过后自动加分，未提交成绩则该场不计分。\n\n### 积分规则\n - 赢：+3分\n - 输：+1分\n - 无效成绩：0分\n\n核心原则是只要参赛就一定有分。\n\n### 防刷分规则\n每队每天最多记1场，同一对手一周最多记1场，其余时间完全自由。\n\n### 赛季与排名\n一个赛季为3个月，按总积分从高到低排名。若积分相同，先看胜场，再看参赛场次。半年积分前三名和挑战者队伍一名，四队进行冠亚军季军争夺。\n\n### 奖项设置（每赛季一次）\n - 冠军\n - 亚军\n - 季军\n - 最活跃球队（比赛场次最多）\n\n### 违规说明\n - 造假比分：本场0分+警告\n - 打架斗殴：直接取消本赛季资格 ', '2025-12-24 10:49:20', 'faq-test', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 10:49:20', '2025-12-31 10:09:47', '系统访客', '系统访客', 1, 1);
