INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (136, 0, '系统访客', NULL, NULL, 2, '关于“什么是植物新品种”，在《植物新品种保护条例（2024版）》中有详细解释，但提供的内容仅表明这是条例全文内容，未包含具体关于“植物新品种”的定义。你可以让我查看《植物新品种保护条例（2024版）》文件内容，我将为你找出具体定义。\n{\n  \"tool\": \"query_knowledge_detail\",\n  \"parameters\": { \"fileName\": \"植物新品种保护条例（2024版）\" }\n}\n\n(来源: 知识库检索 - doubao)', '关于“什么是植物新品种”，在《植物新品种保护条例（2024版）》中有详细解释，但提供的内容仅表明这是条例全文内容，未包含具体关于“植物新品种”的定义。你可以让我查看《植物新品种保护条例（2024版）》文件内容，我将为你找出具体定义。\n{\n  \"tool\": \"query_knowledge_detail\",\n  \"parameters\": { \"fileName\": \"植物新品种保护条例（2024版）\" }\n}\n\n(来源: 知识库检索 - doubao)', '2025-12-24 11:25:53', 'faq-test', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 11:25:53', '2025-12-31 10:09:47', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (137, 0, '系统访客', NULL, NULL, 1, '什么是新颖性？', NULL, '2025-12-24 11:39:30', 'faq-test', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 11:39:30', '2025-12-31 10:09:47', '系统访客', '系统访客', 1, 1);
INSERT INTO `ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (138, 0, '系统访客', NULL, NULL, 2, '新颖性，是指申请品种权的植物新品种在申请日前该品种繁殖材料、收获材料未被销售、推广，或者经申请权人自行或者同意销售、推广该品种繁殖材料、收获材料，在中国境内未超过1年；在境外，木本、藤本植物品种未超过6年，其他植物品种未超过4年。\n\n来源：《植物新品种保护条例》\n\n(来源: 常见问题库)', '新颖性，是指申请品种权的植物新品种在申请日前该品种繁殖材料、收获材料未被销售、推广，或者经申请权人自行或者同意销售、推广该品种繁殖材料、收获材料，在中国境内未超过1年；在境外，木本、藤本植物品种未超过6年，其他植物品种未超过4年。\n\n来源：《植物新品种保护条例》\n\n(来源: 常见问题库)', '2025-12-24 11:39:30', 'faq-test', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 11:39:30', '2025-12-31 10:09:47', '系统访客', '系统访客', 1, 1);
