-- ----------------------------
-- Table structure for communication_record
-- ----------------------------
DROP TABLE IF EXISTS `communication_record`;
CREATE TABLE `communication_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `customer_id` bigint NOT NULL COMMENT '客户ID',
  `customer_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户姓名',
  `communication_type` tinyint NOT NULL COMMENT '沟通类型(1:微信,2:电话,3:邮件,4:会面,5:其他)',
  `communication_time` datetime NOT NULL COMMENT '沟通时间',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '沟通内容',
  `summary` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '沟通摘要',
  `importance` tinyint DEFAULT '1' COMMENT '重要程度(1:一般,2:重要,3:非常重要)',
  `sentiment` tinyint DEFAULT NULL COMMENT '情感分析结果(1:积极,2:中性,3:消极)',
  `satisfaction_score` tinyint DEFAULT NULL COMMENT '满意度评分(1-5分)',
  `keywords` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关键词(多个关键词用逗号分隔)',
  `important_info` text COLLATE utf8mb4_unicode_ci COMMENT '重要信息标记',
  `follow_up_task` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '后续任务',
  `task_deadline` datetime DEFAULT NULL COMMENT '任务截止时间',
  `task_status` tinyint DEFAULT '1' COMMENT '任务状态(1:待处理,2:进行中,3:已完成,4:已取消)',
  `communicator_id` bigint DEFAULT NULL COMMENT '沟通人员ID',
  `communicator_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '沟通人员姓名',
  `attachment_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '附件路径',
  `channel_detail` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '沟通渠道详情',
  `duration` int DEFAULT NULL COMMENT '沟通时长(分钟)',
  `response_time` int DEFAULT NULL COMMENT '客户响应时间(分钟)',
  `is_read` tinyint DEFAULT '0' COMMENT '是否已读(0:未读,1:已读)',
  `is_processed` tinyint DEFAULT '0' COMMENT '是否已处理(0:未处理,1:已处理)',
  `process_result` text COLLATE utf8mb4_unicode_ci COMMENT '处理结果',
  `process_time` datetime DEFAULT NULL COMMENT '处理时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志(0:未删除,1:已删除)',
  `version` int NOT NULL DEFAULT '1' COMMENT '版本号',
  PRIMARY KEY (`id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_communication_type` (`communication_type`),
  KEY `idx_communication_time` (`communication_time`),
  KEY `idx_importance` (`importance`),
  KEY `idx_communicator_id` (`communicator_id`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_deleted` (`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='沟通记录表';

-- ----------------------------
-- Records of communication_record
-- ----------------------------
BEGIN;
INSERT INTO `communication_record` (`id`, `customer_id`, `customer_name`, `communication_type`, `communication_time`, `content`, `summary`, `importance`, `sentiment`, `satisfaction_score`, `keywords`, `important_info`, `follow_up_task`, `task_deadline`, `task_status`, `communicator_id`, `communicator_name`, `attachment_path`, `channel_detail`, `duration`, `response_time`, `is_read`, `is_processed`, `process_result`, `process_time`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (1, 11, '士大夫公司', 2, '2025-11-22 09:14:00', '阿斯顿发', '撒东方饭店', 1, NULL, NULL, NULL, NULL, '放大', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-22 09:14:53', '2025-11-22 09:14:53', NULL, NULL, 0, 1);
COMMIT;

-- ----------------------------
-- Table structure for customer
-- ----------------------------
DROP TABLE IF EXISTS `customer`;
CREATE TABLE `customer` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `customer_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户编号',
  `customer_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户姓名/企业名称',
  `contact_person` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系人',
  `customer_type` tinyint NOT NULL DEFAULT '1' COMMENT '客户类型(1:个人客户,2:企业客户)',
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '手机号码',
  `email` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮箱',
  `address` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '地址',
  `postal_code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮政编码',
  `fax` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '传真',
  `organization_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '机构代码或身份证号码',
  `nationality` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '国籍或所在国（地区）',
  `position` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职务',
  `qq_weixin` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'QQ/微信',
  `cooperation_content` text COLLATE utf8mb4_unicode_ci COMMENT '合作内容',
  `region` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '地区',
  `agency_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '代理机构名称',
  `agency_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '代理机构组织机构代码',
  `agency_address` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '代理机构地址',
  `agency_postal_code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '代理机构邮政编码',
  `agent_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '代理人姓名',
  `agent_phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '代理人电话',
  `agent_fax` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '代理人传真',
  `agent_mobile` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '代理人手机',
  `agent_email` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '代理人邮箱',
  `is_sensitive` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否为敏感数据',
  `protection_password` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '保护密码(加密后存储)',
  `customer_level` tinyint NOT NULL DEFAULT '1' COMMENT '客户等级(1:普通,2:VIP,3:钻石)',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '客户状态(1:正常,2:冻结,3:注销)',
  `source` tinyint NOT NULL DEFAULT '1' COMMENT '客户来源(1:线上,2:线下,3:推荐)',
  `assigned_user_id` bigint DEFAULT NULL COMMENT '负责业务员ID',
  `assigned_user_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '负责业务员姓名',
  `last_contact_time` datetime DEFAULT NULL COMMENT '最后联系时间',
  `remark` text COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `progress` tinyint DEFAULT '0' COMMENT '进度(0:未开始,1:进行中,2:暂停中,3:已成功,4:放弃)',
  `variety` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '品种信息',
  `business_type` tinyint DEFAULT '1' COMMENT '具体业务类型(1:品种权申请客户,2:品种权转化推广客户,3:知识产权互补协作客户,4:科普教育合作客户,5:景观设计服务客户,6:图书出版客户)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志(0:未删除,1:已删除)',
  `version` int NOT NULL DEFAULT '1' COMMENT '版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `customer_code` (`customer_code`),
  KEY `idx_customer_code` (`customer_code`),
  KEY `idx_customer_name` (`customer_name`),
  KEY `idx_contact_person` (`contact_person`),
  KEY `idx_phone` (`phone`),
  KEY `idx_customer_type` (`customer_type`),
  KEY `idx_agency_name` (`agency_name`),
  KEY `idx_agent_name` (`agent_name`),
  KEY `idx_position` (`position`),
  KEY `idx_region` (`region`),
  KEY `idx_customer_level` (`customer_level`),
  KEY `idx_status` (`status`),
  KEY `idx_source` (`source`),
  KEY `idx_assigned_user_id` (`assigned_user_id`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_deleted` (`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='客户基本信息表';

