-- ----------------------------
-- Table structure for customer_detail
-- ----------------------------
DROP TABLE IF EXISTS `customer_detail`;
CREATE TABLE `customer_detail` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `customer_id` bigint NOT NULL COMMENT '客户ID',
  `customer_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户编号',
  `industry_category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '行业分类',
  `business_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务类型',
  `importance` tinyint DEFAULT '1' COMMENT '重要程度(1:一般,2:重要,3:非常重要)',
  `value_score` int DEFAULT '0' COMMENT '客户价值评分(0-100分)',
  `lifecycle_stage` tinyint DEFAULT '1' COMMENT '生命周期阶段(1:潜在,2:接触,3:合作,4:维护,5:流失)',
  `total_amount` decimal(15,2) DEFAULT '0.00' COMMENT '累计消费金额',
  `cooperation_count` int DEFAULT '0' COMMENT '合作次数',
  `credit_level` tinyint DEFAULT '1' COMMENT '信用评估等级(1:A,2:B,3:C,4:D)',
  `satisfaction_score` tinyint DEFAULT '0' COMMENT '客户满意度评分(1-5分)',
  `completeness` int DEFAULT '0' COMMENT '信息完整度(0-100%)',
  `customer_create_time` datetime DEFAULT NULL COMMENT '客户创建时间',
  `first_cooperation_time` datetime DEFAULT NULL COMMENT '首次合作时间',
  `last_cooperation_time` datetime DEFAULT NULL COMMENT '最后合作时间',
  `churn_time` datetime DEFAULT NULL COMMENT '客户流失时间',
  `churn_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流失原因',
  `company_size` tinyint DEFAULT NULL COMMENT '公司规模(1:微型,2:小型,3:中型,4:大型)',
  `annual_revenue` decimal(15,2) DEFAULT NULL COMMENT '年营业额',
  `employee_count` int DEFAULT NULL COMMENT '员工数量',
  `primary_contact` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主要联系人',
  `decision_maker` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '决策人',
  `purchase_cycle` tinyint DEFAULT NULL COMMENT '采购周期(1:月度,2:季度,3:半年度,4:年度)',
  `budget_range` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预算范围',
  `competitors` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '竞争对手',
  `special_requirements` text COLLATE utf8mb4_unicode_ci COMMENT '特殊要求',
  `preferences` text COLLATE utf8mb4_unicode_ci COMMENT '客户偏好',
  `risk_level` tinyint DEFAULT '1' COMMENT '风险等级(1:低,2:中,3:高)',
  `risk_description` text COLLATE utf8mb4_unicode_ci COMMENT '风险描述',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志(0:未删除,1:已删除)',
  `version` int NOT NULL DEFAULT '1' COMMENT '版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_customer_id` (`customer_id`),
  KEY `idx_customer_code` (`customer_code`),
  KEY `idx_importance` (`importance`),
  KEY `idx_value_score` (`value_score`),
  KEY `idx_lifecycle_stage` (`lifecycle_stage`),
  KEY `idx_credit_level` (`credit_level`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_deleted` (`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='客户详细信息表';

-- ----------------------------
-- Records of customer_detail
-- ----------------------------
