-- ----------------------------
-- Table structure for faq_qa
-- ----------------------------
DROP TABLE IF EXISTS `faq_qa`;
CREATE TABLE `faq_qa` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `question` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题',
  `answer` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '答案',
  `keywords` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关键词(逗号分隔)',
  `category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类',
  `priority` int DEFAULT '0' COMMENT '优先级(数字越大优先级越高)',
  `hit_count` int DEFAULT '0' COMMENT '命中次数',
  `status` tinyint DEFAULT '1' COMMENT '状态(1:启用 0:禁用)',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`id`),
  KEY `idx_category` (`category`),
  KEY `idx_priority` (`priority`),
  KEY `idx_status` (`status`),
  KEY `idx_deleted` (`deleted`),
  FULLTEXT KEY `ft_question` (`question`,`keywords`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='FAQ问答表';

-- ----------------------------
-- Records of faq_qa
-- ----------------------------
BEGIN;
INSERT INTO `faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (1, '什么是植物新品种？', '植物新品种指经过人工培育或对发现的野生植物加以开发，具备新颖性、特异性、一致性、稳定性，并有适当命名的植物品种。', '植物新品种,新品种', '名词解释', 0, 0, 1, '2025-12-31 10:06:30', '2025-12-31 10:06:30', NULL, NULL, 0);
INSERT INTO `faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (2, '什么是DUS测试？', 'DUS测试是授予植物新品种权的实质性条件，指对申请品种的特异性(D)、一致性(U)、稳定性(S)进行的栽培鉴定试验。', 'DUS测试,特异性', '名词解释', 0, 0, 1, '2025-12-31 10:06:30', '2025-12-31 10:06:30', NULL, NULL, 0);
INSERT INTO `faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (3, '保护期限是多久？', '品种权的保护期限，自授权公告之日起，木本、藤本植物为25年，其他植物为20年。', '保护期限,25年,20年', '名词解释', 0, 0, 1, '2025-12-31 10:06:30', '2025-12-31 10:06:30', NULL, NULL, 0);
COMMIT;

