-- ----------------------------
-- Table structure for kb_document
-- ----------------------------
DROP TABLE IF EXISTS `kb_document`;
CREATE TABLE `kb_document` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文档标题',
  `content` longtext COLLATE utf8mb4_unicode_ci COMMENT '文档内容(文本提取后)',
  `original_content` longtext COLLATE utf8mb4_unicode_ci COMMENT '原始内容(HTML格式)',
  `file_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件存储路径',
  `file_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原始文件名',
  `file_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'text' COMMENT '文件类型: text,pdf,word,excel,image',
  `file_mime` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MIME类型',
  `file_size` bigint DEFAULT '0' COMMENT '文件大小(字节)',
  `category_id` bigint DEFAULT NULL COMMENT '分类ID',
  `tags` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标签，逗号分隔',
  `auto_tags` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'AI自动生成的标签',
  `keywords` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '提取的关键词',
  `summary` text COLLATE utf8mb4_unicode_ci COMMENT '自动摘要',
  `priority` int DEFAULT '0' COMMENT '优先级，数值越大越重要',
  `view_count` int DEFAULT '0' COMMENT '查看次数',
  `download_count` int DEFAULT '0' COMMENT '下载次数',
  `like_count` int DEFAULT '0' COMMENT '点赞次数',
  `is_active` tinyint(1) DEFAULT '1' COMMENT '是否启用',
  `is_public` tinyint(1) DEFAULT '1' COMMENT '是否公开',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint DEFAULT '0' COMMENT '是否删除',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `version` int DEFAULT '1' COMMENT '版本号',
  PRIMARY KEY (`id`),
  KEY `idx_category_id` (`category_id`),
  KEY `idx_priority` (`priority`),
  KEY `idx_is_active` (`is_active`),
  KEY `idx_is_public` (`is_public`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_file_type` (`file_type`),
  FULLTEXT KEY `idx_title_content` (`title`,`content`,`keywords`),
  FULLTEXT KEY `idx_tags` (`tags`),
  FULLTEXT KEY `idx_auto_tags` (`auto_tags`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='知识库文档表';

