-- ----------------------------
-- Table structure for kb_qa_record
-- ----------------------------
DROP TABLE IF EXISTS `kb_qa_record`;
CREATE TABLE `kb_qa_record` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_question` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户问题',
  `matched_chunks` json DEFAULT NULL COMMENT '匹配的分块ID列表',
  `matched_documents` json DEFAULT NULL COMMENT '匹配的文档ID列表',
  `context_content` longtext COLLATE utf8mb4_unicode_ci COMMENT '检索到的上下文内容',
  `ai_answer` longtext COLLATE utf8mb4_unicode_ci COMMENT 'AI生成的回答',
  `session_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '会话ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `customer_id` bigint DEFAULT NULL COMMENT '客户ID',
  `response_time` int DEFAULT NULL COMMENT '响应时间(毫秒)',
  `satisfaction_score` int DEFAULT NULL COMMENT '满意度评分(1-5分)',
  `is_helpful` tinyint(1) DEFAULT NULL COMMENT '是否有帮助',
  `feedback` text COLLATE utf8mb4_unicode_ci COMMENT '用户反馈',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_session_id` (`session_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_create_time` (`create_time`),
  FULLTEXT KEY `idx_user_question` (`user_question`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='知识库问答记录表';

