-- Records of kb_qa_record
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for kb_tag
-- ----------------------------
DROP TABLE IF EXISTS `kb_tag`;
CREATE TABLE `kb_tag` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标签名称',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '标签描述',
  `color` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '#6c757d' COMMENT '标签颜色',
  `usage_count` int DEFAULT '0' COMMENT '使用次数',
  `category` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'general' COMMENT '标签分类: general,product,tech,business',
  `is_active` tinyint(1) DEFAULT '1' COMMENT '是否启用',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint DEFAULT '0' COMMENT '是否删除',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '更新人',
  `version` int DEFAULT '1' COMMENT '版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
  KEY `idx_category` (`category`),
  KEY `idx_usage_count` (`usage_count`),
  KEY `idx_is_active` (`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='标签管理表';

