-- ----------------------------
-- Table structure for knowledge_document
-- ----------------------------
DROP TABLE IF EXISTS `knowledge_document`;
CREATE TABLE `knowledge_document` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文档标题',
  `content` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文档内容',
  `file_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件名',
  `file_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件类型(pdf/word/excel/txt)',
  `file_size` bigint DEFAULT NULL COMMENT '文件大小(字节)',
  `file_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件路径',
  `document_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文档类型',
  `tags` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标签(逗号分隔)',
  `category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类',
  `summary` text COLLATE utf8mb4_unicode_ci COMMENT '摘要',
  `keywords` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关键词',
  `view_count` int DEFAULT '0' COMMENT '查看次数',
  `download_count` int DEFAULT '0' COMMENT '下载次数',
  `status` tinyint DEFAULT '1' COMMENT '状态(1:启用 0:禁用)',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`id`),
  KEY `idx_title` (`title`),
  KEY `idx_document_type` (`document_type`),
  KEY `idx_category` (`category`),
  KEY `idx_status` (`status`),
  KEY `idx_deleted` (`deleted`),
  FULLTEXT KEY `ft_content` (`content`,`title`,`summary`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='知识库文档表';

-- ----------------------------
-- Records of knowledge_document
-- ----------------------------
BEGIN;
INSERT INTO `knowledge_document` (`id`, `title`, `content`, `file_name`, `file_type`, `file_size`, `file_path`, `document_type`, `tags`, `category`, `summary`, `keywords`, `view_count`, `download_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (1, '植物新品种保护条例（2024版）', '这是条例的全文内容...', '12b744af-e439-4576-aa5b-f412f50502e4.docx', 'docx', NULL, 'uploads/knowledge/12b744af-e439-4576-aa5b-f412f50502e4.docx', NULL, NULL, '法律法规', NULL, NULL, 0, 0, 1, '2025-12-31 10:06:30', '2025-12-31 10:06:30', NULL, NULL, 0);
INSERT INTO `knowledge_document` (`id`, `title`, `content`, `file_name`, `file_type`, `file_size`, `file_path`, `document_type`, `tags`, `category`, `summary`, `keywords`, `view_count`, `download_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (2, 'DUS测试技术指南 - 蔷薇属', '这是DUS测试的详细指南...', '52c32190-605c-4672-8685-5fd978c48189.docx', 'docx', NULL, 'uploads/knowledge/52c32190-605c-4672-8685-5fd978c48189.docx', NULL, NULL, '技术规范', NULL, NULL, 0, 0, 1, '2025-12-31 10:06:30', '2025-12-31 10:06:30', NULL, NULL, 0);
