-- ----------------------------
-- Table structure for message
-- ----------------------------
DROP TABLE IF EXISTS `message`;
CREATE TABLE `message` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息标题',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '消息内容',
  `message_type` tinyint NOT NULL COMMENT '消息类型(1:系统通知,2:业务提醒,3:任务通知,4:客户消息)',
  `importance` tinyint DEFAULT '1' COMMENT '消息重要性(1:普通,2:重要,3:紧急)',
  `business_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联业务类型(customer,communication,task,ai_analysis,team_task,system)',
  `business_id` bigint DEFAULT NULL COMMENT '关联业务ID',
  `business_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联业务名称',
  `receiver_id` bigint NOT NULL COMMENT '接收用户ID',
  `receiver_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '接收用户姓名',
  `sender_id` bigint DEFAULT NULL COMMENT '发送用户ID(系统消息为null)',
  `sender_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发送用户姓名',
  `is_read` tinyint DEFAULT '0' COMMENT '是否已读(0:未读,1:已读)',
  `read_time` datetime DEFAULT NULL COMMENT '已读时间',
  `is_processed` tinyint DEFAULT '0' COMMENT '是否已处理(0:未处理,1:已处理)',
  `processed_time` datetime DEFAULT NULL COMMENT '处理时间',
  `process_result` text COLLATE utf8mb4_unicode_ci COMMENT '处理结果',
  `link_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '跳转链接',
  `link_params` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '跳转参数(JSON格式)',
  `expire_time` datetime DEFAULT NULL COMMENT '过期时间',
  `icon` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '消息图标',
  `color` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '消息颜色',
  `extra_info` text COLLATE utf8mb4_unicode_ci COMMENT '扩展信息(JSON格式)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志(0:未删除,1:已删除)',
  `version` int NOT NULL DEFAULT '1' COMMENT '版本号',
  PRIMARY KEY (`id`),
  KEY `idx_receiver_id` (`receiver_id`),
  KEY `idx_message_type` (`message_type`),
  KEY `idx_importance` (`importance`),
  KEY `idx_is_read` (`is_read`),
  KEY `idx_business_type` (`business_type`),
  KEY `idx_business_id` (`business_id`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_deleted` (`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='消息表';

-- ----------------------------
-- Records of message
-- ----------------------------
BEGIN;
COMMIT;

