-- ----------------------------
-- Table structure for task_progress_report
-- ----------------------------
DROP TABLE IF EXISTS `task_progress_report`;
CREATE TABLE `task_progress_report` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `task_id` bigint DEFAULT NULL COMMENT '任务ID',
  `task_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任务名称',
  `employee_id` bigint DEFAULT NULL COMMENT '员工ID',
  `employee_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '员工姓名',
  `report_type` tinyint DEFAULT NULL COMMENT '汇报类型(1:日报, 2:周报, 3:月报, 4:项目汇报, 5:紧急汇报)',
  `report_title` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '汇报标题',
  `report_content` text COLLATE utf8mb4_unicode_ci COMMENT '汇报内容',
  `progress` int DEFAULT '0' COMMENT '完成进度(0-100%)',
  `work_duration` int DEFAULT NULL COMMENT '工作时长(分钟)',
  `work_results` text COLLATE utf8mb4_unicode_ci COMMENT '工作成果',
  `problems` text COLLATE utf8mb4_unicode_ci COMMENT '遇到的问题',
  `solutions` text COLLATE utf8mb4_unicode_ci COMMENT '解决方案',
  `next_plan` text COLLATE utf8mb4_unicode_ci COMMENT '下一步计划',
  `support_needed` text COLLATE utf8mb4_unicode_ci COMMENT '需要支持',
  `work_location` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工作地点',
  `work_mode` tinyint DEFAULT NULL COMMENT '工作模式(1:办公室, 2:远程, 3:混合)',
  `attachments` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '附件文件',
  `report_status` tinyint DEFAULT '1' COMMENT '汇报状态(1:待审核, 2:已通过, 3:需修改, 4:已驳回)',
  `reviewer_id` bigint DEFAULT NULL COMMENT '审核人ID',
  `reviewer_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核人姓名',
  `review_time` datetime DEFAULT NULL COMMENT '审核时间',
  `review_comment` text COLLATE utf8mb4_unicode_ci COMMENT '审核意见',
  `quality_score` tinyint DEFAULT NULL COMMENT '质量评分(1-5分)',
  `efficiency_score` tinyint DEFAULT NULL COMMENT '效率评分(1-5分)',
  `attitude_score` tinyint DEFAULT NULL COMMENT '态度评分(1-5分)',
  `overall_score` decimal(3,1) DEFAULT NULL COMMENT '综合评分',
  `is_abnormal` tinyint DEFAULT '0' COMMENT '是否异常(0:否, 1:是)',
  `abnormal_reason` text COLLATE utf8mb4_unicode_ci COMMENT '异常原因',
  `supervision_note` text COLLATE utf8mb4_unicode_ci COMMENT '监督备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志(0:未删除,1:已删除)',
  `version` int NOT NULL DEFAULT '1' COMMENT '版本号',
  PRIMARY KEY (`id`),
  KEY `idx_task_id` (`task_id`),
  KEY `idx_employee_id` (`employee_id`),
  KEY `idx_report_type` (`report_type`),
  KEY `idx_report_status` (`report_status`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_deleted` (`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='任务进度汇报表';

-- ----------------------------
-- Records of task_progress_report
-- ----------------------------
BEGIN;
INSERT INTO `task_progress_report` (`id`, `task_id`, `task_name`, `employee_id`, `employee_name`, `report_type`, `report_title`, `report_content`, `progress`, `work_duration`, `work_results`, `problems`, `solutions`, `next_plan`, `support_needed`, `work_location`, `work_mode`, `attachments`, `report_status`, `reviewer_id`, `reviewer_name`, `review_time`, `review_comment`, `quality_score`, `efficiency_score`, `attitude_score`, `overall_score`, `is_abnormal`, `abnormal_reason`, `supervision_note`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (1, 2, '系统性能优化', NULL, '系统管理员', 3, '电风扇', '事发地点ll', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, '2025-11-24 14:20:45', '2025-11-24 14:29:17', NULL, NULL, 0, 2);
COMMIT;

-- ----------------------------
-- Table structure for task_reminder
-- ----------------------------
DROP TABLE IF EXISTS `task_reminder`;
CREATE TABLE `task_reminder` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '提醒标题',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '提醒内容',
  `reminder_type` tinyint NOT NULL COMMENT '提醒类型(1:关键日期,2:跟进提醒,3:机会提醒,4:风险预警)',
  `customer_id` bigint DEFAULT NULL COMMENT '关联客户ID',
  `customer_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联客户姓名',
  `reminder_time` datetime NOT NULL COMMENT '提醒时间',
  `deadline` datetime DEFAULT NULL COMMENT '截止时间',
  `priority` tinyint DEFAULT '2' COMMENT '优先级(1:低,2:中,3:高,4:紧急)',
  `status` tinyint DEFAULT '1' COMMENT '提醒状态(1:待提醒,2:已提醒,3:已完成,4:已取消,5:已过期)',
  `assigned_user_id` bigint DEFAULT NULL COMMENT '负责人员ID',
  `assigned_user_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '负责人员姓名',
  `reminder_method` tinyint DEFAULT '1' COMMENT '提醒方式(1:系统内,2:邮件,3:短信,4:微信,5:全部)',
  `frequency` tinyint DEFAULT '1' COMMENT '提醒频率(1:一次性,2:每日,3:每周,4:每月)',
  `repeat_count` int DEFAULT '0' COMMENT '重复次数',
  `repeated_count` int DEFAULT '0' COMMENT '已重复次数',
  `next_reminder_time` datetime DEFAULT NULL COMMENT '下次提醒时间',
  `completed_time` datetime DEFAULT NULL COMMENT '完成时间',
  `completion_result` text COLLATE utf8mb4_unicode_ci COMMENT '完成结果',
  `customer_response_time` datetime DEFAULT NULL COMMENT '客户响应时间',
  `customer_response` text COLLATE utf8mb4_unicode_ci COMMENT '客户响应内容',
  `effectiveness_score` tinyint DEFAULT NULL COMMENT '提醒效果评分(1-5分)',
  `business_id` bigint DEFAULT NULL COMMENT '关联业务ID',
  `business_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联业务类型',
  `rule_id` bigint DEFAULT NULL COMMENT '提醒规则ID',
  `is_auto_generated` tinyint DEFAULT '0' COMMENT '是否自动生成(0:否,1:是)',
  `generated_from` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '生成来源',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志(0:未删除,1:已删除)',
  `version` int NOT NULL DEFAULT '1' COMMENT '版本号',
  PRIMARY KEY (`id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_reminder_type` (`reminder_type`),
  KEY `idx_reminder_time` (`reminder_time`),
  KEY `idx_priority` (`priority`),
  KEY `idx_status` (`status`),
  KEY `idx_assigned_user_id` (`assigned_user_id`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_deleted` (`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='任务提醒表';

-- ----------------------------
-- Records of task_reminder
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for team_task
-- ----------------------------
DROP TABLE IF EXISTS `team_task`;
CREATE TABLE `team_task` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务标题',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '任务描述',
  `task_type` tinyint NOT NULL COMMENT '任务类型(1:客户跟进,2:项目推进,3:问题处理,4:会议安排,5:其他)',
  `status` tinyint DEFAULT '1' COMMENT '任务状态(1:待分配,2:进行中,3:待审核,4:已完成,5:已取消)',
  `priority` tinyint DEFAULT '2' COMMENT '优先级(1:低,2:中,3:高,4:紧急)',
  `customer_id` bigint DEFAULT NULL COMMENT '关联客户ID',
  `customer_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联客户姓名',
  `creator_id` bigint NOT NULL COMMENT '创建人ID',
  `creator_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人姓名',
  `assignee_id` bigint DEFAULT NULL COMMENT '负责人ID',
  `assignee_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '负责人姓名',
  `start_time` datetime DEFAULT NULL COMMENT '开始时间',
  `deadline` datetime DEFAULT NULL COMMENT '截止时间',
  `completed_time` datetime DEFAULT NULL COMMENT '完成时间',
  `estimated_hours` int DEFAULT NULL COMMENT '预计工时(小时)',
  `actual_hours` int DEFAULT NULL COMMENT '实际工时(小时)',
  `progress` int DEFAULT '0' COMMENT '任务进度(0-100%)',
  `result` text COLLATE utf8mb4_unicode_ci COMMENT '完成结果',
  `remark` text COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `parent_task_id` bigint DEFAULT NULL COMMENT '父任务ID',
  `level` int DEFAULT '1' COMMENT '任务层级',
  `need_approval` tinyint DEFAULT '0' COMMENT '是否需要审批(0:否,1:是)',
  `approver_id` bigint DEFAULT NULL COMMENT '审批人ID',
  `approver_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批人姓名',
  `approval_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approval_result` tinyint DEFAULT NULL COMMENT '审批结果(1:通过,2:拒绝,3:待审批)',
  `approval_comment` text COLLATE utf8mb4_unicode_ci COMMENT '审批意见',
  `tags` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任务标签',
  `attachment_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联文件路径',
  `is_public` tinyint DEFAULT '1' COMMENT '是否公开(0:否,1:是)',
  `visible_user_ids` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '可见用户ID列表',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志(0:未删除,1:已删除)',
  `version` int NOT NULL DEFAULT '1' COMMENT '版本号',
  PRIMARY KEY (`id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_task_type` (`task_type`),
  KEY `idx_status` (`status`),
  KEY `idx_priority` (`priority`),
  KEY `idx_creator_id` (`creator_id`),
  KEY `idx_assignee_id` (`assignee_id`),
  KEY `idx_deadline` (`deadline`),
  KEY `idx_parent_task_id` (`parent_task_id`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_deleted` (`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='团队任务表';

