-- ----------------------------
-- Table structure for z_ai_analysis_rules
-- ----------------------------
DROP TABLE IF EXISTS `z_ai_analysis_rules`;
CREATE TABLE `z_ai_analysis_rules` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `rule_name` varchar(100) NOT NULL COMMENT '规则名称',
  `rule_type` varchar(50) NOT NULL COMMENT '规则类型',
  `rule_content` text NOT NULL COMMENT '规则内容',
  `priority` int DEFAULT '0' COMMENT '优先级',
  `is_active` tinyint(1) DEFAULT '1' COMMENT '是否启用',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_analysis_rules_type` (`rule_type`),
  KEY `idx_analysis_rules_active` (`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI分析规则表';

-- ----------------------------
-- Records of z_ai_analysis_rules
-- ----------------------------
BEGIN;
INSERT INTO `z_ai_analysis_rules` (`id`, `rule_name`, `rule_type`, `rule_content`, `priority`, `is_active`, `created_at`, `updated_at`) VALUES (1, '植物新品种识别', 'patent_type', '包含\"植物\"、\"品种\"、\"育种\"等关键词时，识别为植物新品种权申请', 100, 1, '2025-12-08 12:32:22', '2025-12-08 12:32:22');
INSERT INTO `z_ai_analysis_rules` (`id`, `rule_name`, `rule_type`, `rule_content`, `priority`, `is_active`, `created_at`, `updated_at`) VALUES (2, '技术方案分析', 'technical_analysis', '包含\"技术\"、\"方法\"、\"工艺\"等关键词时，进行技术方案分析', 90, 1, '2025-12-08 12:32:22', '2025-12-08 12:32:22');
INSERT INTO `z_ai_analysis_rules` (`id`, `rule_name`, `rule_type`, `rule_content`, `priority`, `is_active`, `created_at`, `updated_at`) VALUES (3, '紧急程度判断', 'urgency', '包含\"紧急\"、\"加急\"、\"尽快\"等关键词时，标记为高优先级', 80, 1, '2025-12-08 12:32:22', '2025-12-08 12:32:22');
COMMIT;

-- ----------------------------
-- Table structure for z_ai_chat
-- ----------------------------
DROP TABLE IF EXISTS `z_ai_chat`;
CREATE TABLE `z_ai_chat` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `user_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户姓名',
  `customer_id` bigint DEFAULT NULL COMMENT '关联客户ID',
  `customer_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联客户姓名',
  `message_type` tinyint NOT NULL COMMENT '消息类型(1:用户消息,2:AI回复,3:系统消息)',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '消息内容',
  `reply_content` text COLLATE utf8mb4_unicode_ci COMMENT 'AI回复内容',
  `reply_time` datetime DEFAULT NULL COMMENT '回复时间',
  `session_id` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会话ID',
  `context` text COLLATE utf8mb4_unicode_ci COMMENT '对话上下文',
  `intent` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '意图识别结果',
  `confidence` decimal(5,2) DEFAULT NULL COMMENT '置信度',
  `sentiment` tinyint DEFAULT NULL COMMENT '情感分析结果(1:积极,2:中性,3:消极)',
  `keywords` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关键词',
  `is_satisfied` tinyint DEFAULT NULL COMMENT '是否满意(0:否,1:是)',
  `satisfaction_score` tinyint DEFAULT NULL COMMENT '满意度评分',
  `feedback` text COLLATE utf8mb4_unicode_ci COMMENT '用户反馈',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志(0:未删除,1:已删除)',
  `version` int NOT NULL DEFAULT '1' COMMENT '版本号',
  PRIMARY KEY (`id`),
  KEY `idx_session_id` (`session_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_message_type` (`message_type`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=273 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI聊天记录表';

-- ----------------------------
-- Records of z_ai_chat
-- ----------------------------
