INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (26, 0, '系统访客', NULL, NULL, 2, '葵花籽是向日葵的果实，它不仅美味可口，还具有丰富的营养价值和广泛的用途，以下为你详细介绍：\n\n### 基本信息\n- **植物来源**：葵花籽是菊科向日葵属一年生草本植物向日葵的种子。向日葵植株高大，茎直立粗壮，叶片呈心形，互生。头状花序极大，单生于茎顶，花盘会随着太阳转动，这也是它被称为“向日葵”的原因。\n- **主要分类**：根据用途可分为食用型、油用型和中间型三类。食用型的葵花籽较大，皮壳厚，出仁率低，口感好，适合炒食；油用型的葵花籽较小，皮壳薄，含油率高，主要用于榨油；中间型则兼具两者的特点。\n\n### 营养价值\n- **不饱和脂肪酸**：葵花籽中富含不饱和脂肪酸，如亚油酸、油酸等，有助于降低胆固醇水平，保护心血管健康。\n- **蛋白质**：是优质的植物蛋白来源，能为人体提供必要的氨基酸，维持身体正常的生理功能。\n- **维生素**：含有丰富的维生素E，它是一种抗氧化剂，能延缓衰老、保护皮肤健康；还含有一定量的维生素B族，参与人体的新陈代谢。\n- **矿物质**：包含钾、镁、钙、铁、锌等多种矿物质。其中钾元素有助于维持心脏正常功能和血压稳定；镁元素对骨骼健康和神经系统正常运作至关重要。 \n\n### 食用方法\n- **直接食用**：将葵花籽炒熟或煮熟后，可直接嗑食，是人们休闲时光常见的零食。不同地区还会制作出各具风味的口味，如五香、奶油、焦糖等。\n- **制作糕点**：可以将葵花籽仁添加到面包、蛋糕、饼干等糕点中，增加糕点的口感和营养价值。\n- **榨油**：油用型葵花籽可以通过压榨的方式提取葵花籽油。葵花籽油是一种营养丰富的食用油，富含不饱和脂肪酸，易于人体吸收，适合用于烹饪和烘焙。\n\n### 种植要点\n- **播种时间**：一般在春季或夏季播种，当土壤温度稳定在10℃以上时即可进行。\n- **土壤要求**：向日葵对土壤的适应性较强，但以疏松、肥沃、排水良好的土壤为宜。\n- **光照和水分**：向日葵是喜光植物，需要充足的阳光照射。在生长期间，要保证充足的水分供应，但避免积水。\n- **收获**：当向日葵花盘背面变成黄色，茎秆变黄，中上部叶片枯黄脱落，种子外壳坚硬时，即可进行收获。 ', '葵花籽是向日葵的果实，它不仅美味可口，还具有丰富的营养价值和广泛的用途，以下为你详细介绍：\n\n### 基本信息\n- **植物来源**：葵花籽是菊科向日葵属一年生草本植物向日葵的种子。向日葵植株高大，茎直立粗壮，叶片呈心形，互生。头状花序极大，单生于茎顶，花盘会随着太阳转动，这也是它被称为“向日葵”的原因。\n- **主要分类**：根据用途可分为食用型、油用型和中间型三类。食用型的葵花籽较大，皮壳厚，出仁率低，口感好，适合炒食；油用型的葵花籽较小，皮壳薄，含油率高，主要用于榨油；中间型则兼具两者的特点。\n\n### 营养价值\n- **不饱和脂肪酸**：葵花籽中富含不饱和脂肪酸，如亚油酸、油酸等，有助于降低胆固醇水平，保护心血管健康。\n- **蛋白质**：是优质的植物蛋白来源，能为人体提供必要的氨基酸，维持身体正常的生理功能。\n- **维生素**：含有丰富的维生素E，它是一种抗氧化剂，能延缓衰老、保护皮肤健康；还含有一定量的维生素B族，参与人体的新陈代谢。\n- **矿物质**：包含钾、镁、钙、铁、锌等多种矿物质。其中钾元素有助于维持心脏正常功能和血压稳定；镁元素对骨骼健康和神经系统正常运作至关重要。 \n\n### 食用方法\n- **直接食用**：将葵花籽炒熟或煮熟后，可直接嗑食，是人们休闲时光常见的零食。不同地区还会制作出各具风味的口味，如五香、奶油、焦糖等。\n- **制作糕点**：可以将葵花籽仁添加到面包、蛋糕、饼干等糕点中，增加糕点的口感和营养价值。\n- **榨油**：油用型葵花籽可以通过压榨的方式提取葵花籽油。葵花籽油是一种营养丰富的食用油，富含不饱和脂肪酸，易于人体吸收，适合用于烹饪和烘焙。\n\n### 种植要点\n- **播种时间**：一般在春季或夏季播种，当土壤温度稳定在10℃以上时即可进行。\n- **土壤要求**：向日葵对土壤的适应性较强，但以疏松、肥沃、排水良好的土壤为宜。\n- **光照和水分**：向日葵是喜光植物，需要充足的阳光照射。在生长期间，要保证充足的水分供应，但避免积水。\n- **收获**：当向日葵花盘背面变成黄色，茎秆变黄，中上部叶片枯黄脱落，种子外壳坚硬时，即可进行收获。 ', '2025-12-13 19:36:49', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-13 19:36:49', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
