INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (44, 0, '系统访客', NULL, NULL, 2, '“射门”在不同语境下有不同含义，以下为你详细介绍：\n\n### 体育领域\n在众多球类运动中，“射门”是一个关键动作，主要出现在足球和曲棍球等项目里。\n- **足球**\n    - **定义**：是指球员用特定的技术动作，将足球踢向对方球门，以图得分的行为。它是足球比赛中得分的唯一手段，也是比赛的核心环节之一。\n    - **常见方式**：脚内侧射门精准度高，常用于近距离射门；正脚背射门力量大、速度快，适合远射和大力抽射；外脚背射门可以打出弧线，让球的运行轨迹更具迷惑性。\n- **曲棍球**\n    - **定义**：球员运用球棍将球击向对方球门，争取得分。曲棍球的球门较小，防守也更为严密，因此射门需要更高的技巧和准确性。\n    - **常见方式**：有推射，动作较为柔和，适合近距离将球推入门内；还有抽射，借助手臂和身体的力量，快速挥动球棍，使球以较高的速度射向球门。\n\n### 游戏或其他情境\n在一些电子游戏、模拟体育游戏或者儿童玩耍场景中，也会使用“射门”这个概念。比如在足球游戏里，玩家通过操作手柄或键盘来控制虚拟球员进行射门；孩子们在玩耍时，用玩具球和简易球门进行模拟射门游戏，同样也会用到“射门”这个说法。 ', '“射门”在不同语境下有不同含义，以下为你详细介绍：\n\n### 体育领域\n在众多球类运动中，“射门”是一个关键动作，主要出现在足球和曲棍球等项目里。\n- **足球**\n    - **定义**：是指球员用特定的技术动作，将足球踢向对方球门，以图得分的行为。它是足球比赛中得分的唯一手段，也是比赛的核心环节之一。\n    - **常见方式**：脚内侧射门精准度高，常用于近距离射门；正脚背射门力量大、速度快，适合远射和大力抽射；外脚背射门可以打出弧线，让球的运行轨迹更具迷惑性。\n- **曲棍球**\n    - **定义**：球员运用球棍将球击向对方球门，争取得分。曲棍球的球门较小，防守也更为严密，因此射门需要更高的技巧和准确性。\n    - **常见方式**：有推射，动作较为柔和，适合近距离将球推入门内；还有抽射，借助手臂和身体的力量，快速挥动球棍，使球以较高的速度射向球门。\n\n### 游戏或其他情境\n在一些电子游戏、模拟体育游戏或者儿童玩耍场景中，也会使用“射门”这个概念。比如在足球游戏里，玩家通过操作手柄或键盘来控制虚拟球员进行射门；孩子们在玩耍时，用玩具球和简易球门进行模拟射门游戏，同样也会用到“射门”这个说法。 ', '2025-12-13 19:54:19', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-13 19:54:19', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
