INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (46, 0, '系统访客', NULL, NULL, 2, '植物新品种权申请费用包括：\n\n**官方费用**：\n1. 申请费：1000元\n2. 审查费：2500元\n3. 年费：第1-6年每年300元，第7-15年每年450元，第16-20年每年900元\n\n**服务费用**（我方）：\n1. 基础代理费：5000-8000元\n2. 预审服务费：3000-5000元\n3. 材料撰写费：2000-4000元\n4. 加急服务费：另议\n\n**优惠政策**：\n- 批量申请享受折扣\n- 长期合作客户优惠\n- 特定品种补贴政策\n\n**付款方式**：\n- 分期付款\n- 一次性付款优惠\n\n**注**：具体费用根据品种类型和服务内容确定，详情请咨询客服。\n\n(来源: 常见问题库)', '植物新品种权申请费用包括：\n\n**官方费用**：\n1. 申请费：1000元\n2. 审查费：2500元\n3. 年费：第1-6年每年300元，第7-15年每年450元，第16-20年每年900元\n\n**服务费用**（我方）：\n1. 基础代理费：5000-8000元\n2. 预审服务费：3000-5000元\n3. 材料撰写费：2000-4000元\n4. 加急服务费：另议\n\n**优惠政策**：\n- 批量申请享受折扣\n- 长期合作客户优惠\n- 特定品种补贴政策\n\n**付款方式**：\n- 分期付款\n- 一次性付款优惠\n\n**注**：具体费用根据品种类型和服务内容确定，详情请咨询客服。\n\n(来源: 常见问题库)', '2025-12-13 20:29:20', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-13 20:29:20', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (47, 0, '系统访客', NULL, NULL, 1, '周期多长', NULL, '2025-12-13 20:29:28', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-13 20:29:28', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (48, 0, '系统访客', NULL, NULL, 2, '植物新品种权申请的时间周期如下：\n\n**正常流程**：\n- 材料准备：1-2个月\n- 初步审查：3-6个月\n- 实质审查：12-18个月\n- 授权公告：1-2个月\n- **总计**：约18-28个月\n\n**加急通道**（符合条件）：\n- 可缩短至12-15个月\n\n**影响因素**：\n1. 材料完整性和规范性\n2. 品种测试周期\n3. 审查机关工作量\n4. 补正材料的及时性\n\n**建议**：选择我们的预审服务可以有效缩短整体周期。\n\n(来源: 常见问题库)', '植物新品种权申请的时间周期如下：\n\n**正常流程**：\n- 材料准备：1-2个月\n- 初步审查：3-6个月\n- 实质审查：12-18个月\n- 授权公告：1-2个月\n- **总计**：约18-28个月\n\n**加急通道**（符合条件）：\n- 可缩短至12-15个月\n\n**影响因素**：\n1. 材料完整性和规范性\n2. 品种测试周期\n3. 审查机关工作量\n4. 补正材料的及时性\n\n**建议**：选择我们的预审服务可以有效缩短整体周期。\n\n(来源: 常见问题库)', '2025-12-13 20:29:28', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-13 20:29:28', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (49, 0, '系统访客', NULL, NULL, 1, '效果怎么样', NULL, '2025-12-13 20:29:37', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-13 20:29:37', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (50, 0, '系统访客', NULL, NULL, 2, '不太明确你所说的“效果”具体是指什么方面的效果。如果是接着前面聊的植物新品种权申请，其可能在以下方面呈现出不同效果：\n\n### 对育种者的效果\n1. **法律保护**\n植物新品种权获得授权后，育种者对该品种享有排他的独占权。其他单位或个人未经许可，不得为商业目的生产、繁殖、销售该授权品种的繁殖材料等。这为育种者的智力成果提供了强有力的法律保障，防止他人随意盗用其品种，维护了育种者的合法权益。\n2. **经济回报**\n拥有新品种权可以让育种者通过多种方式获得经济收益。一方面，可以自己组织生产和销售授权品种的繁殖材料，获取利润；另一方面，还能将品种权转让或许可给其他企业或个人，从而收取转让费或许可费。比如一些优质的农作物新品种，能为育种者带来可观的经济回报。\n3. **提升声誉**\n成功获得植物新品种权是对育种者科研能力和创新水平的高度认可，有助于提升育种者在行业内的知名度和声誉，为其后续开展科研合作、争取更多科研资源等创造有利条件。\n\n### 对农业生产的效果\n1. **推动品种更新换代**\n鼓励育种者不断投入研发，培育出更多高产、优质、抗逆性强的新品种。这些新品种的推广应用，能够提高农作物的产量和质量，增强农业生产对各种自然灾害和病虫害的抵御能力，促进农业的可持续发展。\n2. **优化农业产业结构**\n不同的植物新品种适应不同的种植区域和市场需求。新品种的出现可以引导农民调整种植结构，发展特色农业，提高农业生产的经济效益和市场竞争力。\n\n### 可能存在的挑战\n1. **审查不通过**\n如果申请的品种不符合新颖性、特异性、一致性和稳定性等授权条件，可能无法获得植物新品种权，导致育种者前期投入的时间和精力白费。\n2. **维权难度**\n尽管有法律保护，但在实际中，品种权的侵权行为仍然可能存在，而且维权过程可能面临取证困难、成本较高等问题，这在一定程度上会影响品种权保护的效果。 ', '不太明确你所说的“效果”具体是指什么方面的效果。如果是接着前面聊的植物新品种权申请，其可能在以下方面呈现出不同效果：\n\n### 对育种者的效果\n1. **法律保护**\n植物新品种权获得授权后，育种者对该品种享有排他的独占权。其他单位或个人未经许可，不得为商业目的生产、繁殖、销售该授权品种的繁殖材料等。这为育种者的智力成果提供了强有力的法律保障，防止他人随意盗用其品种，维护了育种者的合法权益。\n2. **经济回报**\n拥有新品种权可以让育种者通过多种方式获得经济收益。一方面，可以自己组织生产和销售授权品种的繁殖材料，获取利润；另一方面，还能将品种权转让或许可给其他企业或个人，从而收取转让费或许可费。比如一些优质的农作物新品种，能为育种者带来可观的经济回报。\n3. **提升声誉**\n成功获得植物新品种权是对育种者科研能力和创新水平的高度认可，有助于提升育种者在行业内的知名度和声誉，为其后续开展科研合作、争取更多科研资源等创造有利条件。\n\n### 对农业生产的效果\n1. **推动品种更新换代**\n鼓励育种者不断投入研发，培育出更多高产、优质、抗逆性强的新品种。这些新品种的推广应用，能够提高农作物的产量和质量，增强农业生产对各种自然灾害和病虫害的抵御能力，促进农业的可持续发展。\n2. **优化农业产业结构**\n不同的植物新品种适应不同的种植区域和市场需求。新品种的出现可以引导农民调整种植结构，发展特色农业，提高农业生产的经济效益和市场竞争力。\n\n### 可能存在的挑战\n1. **审查不通过**\n如果申请的品种不符合新颖性、特异性、一致性和稳定性等授权条件，可能无法获得植物新品种权，导致育种者前期投入的时间和精力白费。\n2. **维权难度**\n尽管有法律保护，但在实际中，品种权的侵权行为仍然可能存在，而且维权过程可能面临取证困难、成本较高等问题，这在一定程度上会影响品种权保护的效果。 ', '2025-12-13 20:29:37', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-13 20:29:37', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (51, 0, '系统访客', NULL, NULL, 1, '品种权', NULL, '2025-12-13 20:30:16', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-13 20:30:16', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (52, 0, '系统访客', NULL, NULL, 2, '植物新品种权（Plant Variety Rights）简称品种权，也称植物育种者权利（Plant Breeder Rights，PBR），是指完成育种的单位和个人对其获得授权的品种，享有排他的独占权，未经许可，任何人不得以商业目的生产、销售或重复使用该授权品种的繁殖材料。\n\n(来源: 常见问题库)', '植物新品种权（Plant Variety Rights）简称品种权，也称植物育种者权利（Plant Breeder Rights，PBR），是指完成育种的单位和个人对其获得授权的品种，享有排他的独占权，未经许可，任何人不得以商业目的生产、销售或重复使用该授权品种的繁殖材料。\n\n(来源: 常见问题库)', '2025-12-13 20:30:16', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-13 20:30:16', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
