INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (56, 0, '系统访客', NULL, NULL, 2, '不太明确你具体处于什么情境呢。如果你是想申请植物新品种权，接下来可以这么做：\n1. **材料准备**：依据要求准备好申请书、说明书、照片等相关申请材料，保证材料的完整性和规范性，要是不确定材料撰写规范，也可以寻求专业服务机构协助。\n2. **提交申请**：把准备齐全的申请材料提交给相关的审查机关。\n3. **配合审查**：在初步审查和实质审查阶段，按照审查机关的要求，可能需要对材料进行补正或者进一步提供相关信息，要及时配合，确保审查工作顺利进行。\n\n要是你说的不是植物新品种权申请这件事，可以给我更多背景信息，这样我就能精准地告诉你该做什么啦。 ', '不太明确你具体处于什么情境呢。如果你是想申请植物新品种权，接下来可以这么做：\n1. **材料准备**：依据要求准备好申请书、说明书、照片等相关申请材料，保证材料的完整性和规范性，要是不确定材料撰写规范，也可以寻求专业服务机构协助。\n2. **提交申请**：把准备齐全的申请材料提交给相关的审查机关。\n3. **配合审查**：在初步审查和实质审查阶段，按照审查机关的要求，可能需要对材料进行补正或者进一步提供相关信息，要及时配合，确保审查工作顺利进行。\n\n要是你说的不是植物新品种权申请这件事，可以给我更多背景信息，这样我就能精准地告诉你该做什么啦。 ', '2025-12-13 20:56:17', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-13 20:56:17', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
