INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (68, 0, '系统访客', NULL, NULL, 2, '**美国植物新品种保护制度分析 (1).pdf**\n\n·262· 2015年5月 市场论坛 中文科技期刊数据库 (文摘版 )经济管理 \n美国植物新品种保护制度分析 \n徐大明 \n北京大北农科技集团股份有限公司，北京 100080 \n摘 要 ：美国是最早对植物品种提供知识产权保护的国家，经过半个世纪的发展，建立了世界上独具特色的植物品种保护 \n制度。本文重点简述了美国植物品种保护制度发展历程，介绍了当时的立法背景及利益考量，分析美国植物品种保护制度的优 \n点与弊端，以期为完善我 国植物新品种保护制度提供借鉴。 \n关键词 ：植物新品种 ；保护制度 ；分析 \n中图分类号 ：D971．2 文献标识码 ：A 文章编号 ：1671。5616(2015)05．0262．01 \n美国是鼓励创新的国家，提倡对“创造力给予慷慨的激励”。 \n美国之所以成为种业强国，与其建立的植物品种保护制度密切 \n相关。该国植物品种保护制度具有悠久的历史和独特的发展历 \n程，从 1930年 《植物专利法》保护无性繁殖的植物 (块茎植 \n物除外)，到 1970《植物品种保护法》保护有性繁殖和块茎繁 \n殖的植物、1985年美国专利商标局对植物品种给予发明专利 \n保护，走了一条与其它国家不甚相同的保护之路。美国植物品 \n种保护制度，对鼓励其国内植物育种创新、提升其种子产业的 \n国际竞争力发挥了重要的作用。 \n1专利框架内的植物专利法 \n美国是世界上最早对植物品种提供知识产权保护的国家， \n他们的 《植物专利法》(简称’PPA)是世界上第一部专门保护 \n有生命发明的知识产权法律 [1】，该法规中的四个条款，后被并 \n入美国专利法第 l61—164条。 \n1．1立法背景 \n但长期以来，植物品种一直排斥在专利保护之外。美国专 \n利商标局拒绝为植物授予专利权。主要原因是植物品种被认为 \n是 自然产物，自然产物不应当授予专利。而且植物品种也无法 \n满足美国专利法 ll2条规定的书面描述要求。根据该法书面描 \n述要求，发明说明书应对发明做全面、清楚的说明，使得相关 \n领域中的技术人员能够实施该发明。而植物品种说明书即便公 \n开品种系谱以及选育过程，其他人也无法遵循其选育过程而选 \n育出相同的品种即无法实施该发明。 \n1．2认识突破 \n随着育种技术的发展，美国社会逐步认识到人工培育的植 \n物品种并非是自然产物，而是人与 自然共同作用的产物。育种 \n者和育种技术的介入成为主导、决定因素。人工培育的植物品 \n种不是自然产物，而是人类智力成果 也应当得到与工业发明 \n相似的待遇和激励。 \n1930年国会制定 《植物专利法》。《植物专利法》对植物 \n品种的书面描述要求做了特殊的规定，“如果对发明的说明是 \n尽可能的完整，则不能因为不符合本法 l12规定而宣布任何植 \n物专利无效”(35U．S．C．162)。 \n1．3利益考量 \n由于大部分有性繁殖和块茎繁殖的植物属于粮食作物，考 \n虑到给予有性繁殖和块茎繁殖的植物专利权，可 能会提高农业 \n种植成本而遭受有关组织和农民群体的强烈反对，故 《植物专 \n利法》并未将有性繁殖和块茎繁殖的植物纳入植物专利的客体 \n范围。 \n《植物专利法》仅适用于无性繁殖的植物 (块茎植物除 \n外)，是各方利益权衡和博弈的结果。“议会的最后方案即考虑 \n了以无性繁殖方式为主的园艺业和果树行业的利益，又考虑了 \n以有性繁殖方式为主的从事农作物种植和生产的农民群体的利 \n益”【”。 \n1．4重要意义 \n尽管 《植物专利法》保护范围有限，但已是巨大的突破。 \n植物品种首次登堂入室，成为可专利的客体，开启植物品种知 \n识产权保护的历史。该法对美国和其他国家植物品种保护制度 \n的未来发展产生了深远的影响。 \n2专门 (特别)法一 《植物品种保护法》 \n1970年美国国会通过 《植物品种保护法》(简称 PVPA)。 \n该法赋予植物品种育种者不同于专利的特别权利，并受到起源 \n于欧洲的 《国际植物新品种保护联盟公约》(UPOV公约)的 \n影响。 \n2．1立法背景 \n美国种子行业组织 ．种子贸易协会 (ASTA)曾经尝试推 \n动将有性繁殖植物纳入 《植物专利法》的保护范围，但此举没 \n有获得美国农业部、农民等团体的支持。之后转而借鉴欧洲专 \n门的植物品种保护法律制度，提出 “植物品种保护法案”。 \n2．2利益考量 \n以植物专利方式保护有性繁殖植物的方案之所以遭到反 \n对，主要是担心对有性繁殖植物提供专利保护会阻碍种质资源 \n的自由交流、会阻碍育种创新以及种子价格的上涨。为此，《植 \n物品种保护法》特别规定 “研究豁免”、“农民特权”等品种权 \n的限制于例外，最终该法案得以通过。 \n2．3 《植物品种法》具有特色的几项内容 \n2．3．1保护范围 \n仅适用有性繁殖和块茎繁殖的植物。 \n2．3．2新颖性 \n“品种生产的杂交种的销售和处理，视为该...\n\n*（内容较长，已截取）*\n\n(来源: 知识库向量搜索，相似度: 0.86)', '**美国植物新品种保护制度分析 (1).pdf**\n\n·262· 2015年5月 市场论坛 中文科技期刊数据库 (文摘版 )经济管理 \n美国植物新品种保护制度分析 \n徐大明 \n北京大北农科技集团股份有限公司，北京 100080 \n摘 要 ：美国是最早对植物品种提供知识产权保护的国家，经过半个世纪的发展，建立了世界上独具特色的植物品种保护 \n制度。本文重点简述了美国植物品种保护制度发展历程，介绍了当时的立法背景及利益考量，分析美国植物品种保护制度的优 \n点与弊端，以期为完善我 国植物新品种保护制度提供借鉴。 \n关键词 ：植物新品种 ；保护制度 ；分析 \n中图分类号 ：D971．2 文献标识码 ：A 文章编号 ：1671。5616(2015)05．0262．01 \n美国是鼓励创新的国家，提倡对“创造力给予慷慨的激励”。 \n美国之所以成为种业强国，与其建立的植物品种保护制度密切 \n相关。该国植物品种保护制度具有悠久的历史和独特的发展历 \n程，从 1930年 《植物专利法》保护无性繁殖的植物 (块茎植 \n物除外)，到 1970《植物品种保护法》保护有性繁殖和块茎繁 \n殖的植物、1985年美国专利商标局对植物品种给予发明专利 \n保护，走了一条与其它国家不甚相同的保护之路。美国植物品 \n种保护制度，对鼓励其国内植物育种创新、提升其种子产业的 \n国际竞争力发挥了重要的作用。 \n1专利框架内的植物专利法 \n美国是世界上最早对植物品种提供知识产权保护的国家， \n他们的 《植物专利法》(简称’PPA)是世界上第一部专门保护 \n有生命发明的知识产权法律 [1】，该法规中的四个条款，后被并 \n入美国专利法第 l61—164条。 \n1．1立法背景 \n但长期以来，植物品种一直排斥在专利保护之外。美国专 \n利商标局拒绝为植物授予专利权。主要原因是植物品种被认为 \n是 自然产物，自然产物不应当授予专利。而且植物品种也无法 \n满足美国专利法 ll2条规定的书面描述要求。根据该法书面描 \n述要求，发明说明书应对发明做全面、清楚的说明，使得相关 \n领域中的技术人员能够实施该发明。而植物品种说明书即便公 \n开品种系谱以及选育过程，其他人也无法遵循其选育过程而选 \n育出相同的品种即无法实施该发明。 \n1．2认识突破 \n随着育种技术的发展，美国社会逐步认识到人工培育的植 \n物品种并非是自然产物，而是人与 自然共同作用的产物。育种 \n者和育种技术的介入成为主导、决定因素。人工培育的植物品 \n种不是自然产物，而是人类智力成果 也应当得到与工业发明 \n相似的待遇和激励。 \n1930年国会制定 《植物专利法》。《植物专利法》对植物 \n品种的书面描述要求做了特殊的规定，“如果对发明的说明是 \n尽可能的完整，则不能因为不符合本法 l12规定而宣布任何植 \n物专利无效”(35U．S．C．162)。 \n1．3利益考量 \n由于大部分有性繁殖和块茎繁殖的植物属于粮食作物，考 \n虑到给予有性繁殖和块茎繁殖的植物专利权，可 能会提高农业 \n种植成本而遭受有关组织和农民群体的强烈反对，故 《植物专 \n利法》并未将有性繁殖和块茎繁殖的植物纳入植物专利的客体 \n范围。 \n《植物专利法》仅适用于无性繁殖的植物 (块茎植物除 \n外)，是各方利益权衡和博弈的结果。“议会的最后方案即考虑 \n了以无性繁殖方式为主的园艺业和果树行业的利益，又考