INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (76, 0, '系统访客', NULL, NULL, 2, '植物新品种保护名录是由国务院农业、林业行政部门分批公布的受保护植物属和种的名单。只有列入名录的植物种类，才可以申请植物新品种权。\n\n(来源: 常见问题库)', '植物新品种保护名录是由国务院农业、林业行政部门分批公布的受保护植物属和种的名单。只有列入名录的植物种类，才可以申请植物新品种权。\n\n(来源: 常见问题库)', '2025-12-18 17:58:47', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-18 17:58:47', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
