INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (82, 0, '系统访客', NULL, NULL, 2, '⚠️ **DeepSeek账户余额不足**\n\n您的DeepSeek API账户余额已用完，无法继续使用AI服务。\n\n**解决方案：**\n1. 登录DeepSeek平台（https://platform.deepseek.com）\n2. 为账户充值\n3. 充值后即可恢复正常使用\n\n如有疑问，请联系系统管理员。', '⚠️ **DeepSeek账户余额不足**\n\n您的DeepSeek API账户余额已用完，无法继续使用AI服务。\n\n**解决方案：**\n1. 登录DeepSeek平台（https://platform.deepseek.com）\n2. 为账户充值\n3. 充值后即可恢复正常使用\n\n如有疑问，请联系系统管理员。', '2025-12-24 18:12:08', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 18:12:08', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (83, 0, '系统访客', NULL, NULL, 1, '申请基本条件是什么？', NULL, '2025-12-24 18:14:54', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 18:14:54', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (84, 0, '系统访客', NULL, NULL, 2, '申请植物新品种权需要满足以下基本条件：\n\n1. **新颖性**：申请品种在申请日前该品种繁殖材料未被销售，或者经育种者许可，在中国境内销售该品种繁殖材料未超过1年。\n\n2. **特异性**：申请品种应当明显区别于在递交申请以前已知的品种。\n\n3. **一致性**：申请品种经过繁殖，除可以预见的变异外，其相关的特征或者特性一致。\n\n4. **稳定性**：申请品种经过反复繁殖后或者在特定繁殖周期结束时，其相关的特征或者特性保持不变。\n\n5. **适当命名**：申请品种应当具备适当的名称，并与相同或者相近的植物属或者种中已知品种的名称相区别。\n\n(来源: 常见问题库)', '申请植物新品种权需要满足以下基本条件：\n\n1. **新颖性**：申请品种在申请日前该品种繁殖材料未被销售，或者经育种者许可，在中国境内销售该品种繁殖材料未超过1年。\n\n2. **特异性**：申请品种应当明显区别于在递交申请以前已知的品种。\n\n3. **一致性**：申请品种经过繁殖，除可以预见的变异外，其相关的特征或者特性一致。\n\n4. **稳定性**：申请品种经过反复繁殖后或者在特定繁殖周期结束时，其相关的特征或者特性保持不变。\n\n5. **适当命名**：申请品种应当具备适当的名称，并与相同或者相近的植物属或者种中已知品种的名称相区别。\n\n(来源: 常见问题库)', '2025-12-24 18:14:54', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 18:14:54', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (85, 0, '系统访客', NULL, NULL, 1, '预审服务有什么优势？', NULL, '2025-12-24 18:14:55', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 18:14:55', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (86, 0, '系统访客', NULL, NULL, 2, '我们的预审服务具有以下优势：\n\n1. **专业评估**：由资深专家对申请材料进行全面审查，提前发现潜在问题。\n\n2. **提高成功率**：通过预审可以大幅提高正式申请的通过率，避免因材料问题导致的驳回。\n\n3. **节省时间**：提前发现并解决问题，避免反复修改，缩短整体申请周期。\n\n4. **降低风险**：减少因申请失败造成的经济损失和时间成本。\n\n5. **专业指导**：获得针对性的改进建议和优化方案。\n\n6. **优先处理**：预审客户享有优先服务通道。\n\n(来源: 常见问题库)', '我们的预审服务具有以下优势：\n\n1. **专业评估**：由资深专家对申请材料进行全面审查，提前发现潜在问题。\n\n2. **提高成功率**：通过预审可以大幅提高正式申请的通过率，避免因材料问题导致的驳回。\n\n3. **节省时间**：提前发现并解决问题，避免反复修改，缩短整体申请周期。\n\n4. **降低风险**：减少因申请失败造成的经济损失和时间成本。\n\n5. **专业指导**：获得针对性的改进建议和优化方案。\n\n6. **优先处理**：预审客户享有优先服务通道。\n\n(来源: 常见问题库)', '2025-12-24 18:14:55', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 18:14:55', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (87, 0, '系统访客', NULL, NULL, 1, '申请时间周期是多久？', NULL, '2025-12-24 18:14:56', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 18:14:56', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (88, 0, '系统访客', NULL, NULL, 2, '植物新品种权申请的时间周期如下：\n\n**正常流程**：\n- 材料准备：1-2个月\n- 初步审查：3-6个月\n- 实质审查：12-18个月\n- 授权公告：1-2个月\n- **总计**：约18-28个月\n\n**加急通道**（符合条件）：\n- 可缩短至12-15个月\n\n**影响因素**：\n1. 材料完整性和规范性\n2. 品种测试周期\n3. 审查机关工作量\n4. 补正材料的及时性\n\n**建议**：选择我们的预审服务可以有效缩短整体周期。\n\n(来源: 常见问题库)', '植物新品种权申请的时间周期如下：\n\n**正常流程**：\n- 材料准备：1-2个月\n- 初步审查：3-6个月\n- 实质审查：12-18个月\n- 授权公告：1-2个月\n- **总计**：约18-28个月\n\n**加急通道**（符合条件）：\n- 可缩短至12-15个月\n\n**影响因素**：\n1. 材料完整性和规范性\n2. 品种测试周期\n3. 审查机关工作量\n4. 补正材料的及时性\n\n**建议**：选择我们的预审服务可以有效缩短整体周期。\n\n(来源: 常见问题库)', '2025-12-24 18:14:56', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 18:14:56', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (89, 0, '系统访客', NULL, NULL, 1, '材料准备指南', NULL, '2025-12-24 18:14:58', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 18:14:58', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (90, 0, '系统访客', NULL, NULL, 2, '申请植物新品种权需要准备以下材料：\n\n**必备材料**：\n1. 植物新品种权请求书\n2. 说明书及照片\n3. 品种暂定名称\n\n**说明书内容**：\n- 品种来源及育种过程\n- 特征特性描述\n- 栽培技术要点\n- 品种对比说明\n\n**照片要求**：\n- 能够说明品种特征的彩色照片\n- 不同生长期的对比照片\n- 与近似品种的对比照片\n\n**其他材料**：\n- 测试报告（如有）\n- 审定证书（如有）\n- 委托书（委托代理时）\n\n**注意事项**：\n- 所有材料需加盖公章\n- 照片需清晰、规范\n- 描述需准确、详细\n\n(来源: 常见问题库)', '申请植物新品种权需要准备以下材料：\n\n**必备材料**：\n1. 植物新品种权请求书\n2. 说明书及照片\n3. 品种暂定名称\n\n**说明书内容**：\n- 品种来源及育种过程\n- 特征特性描述\n- 栽培技术要点\n- 品种对比说明\n\n**照片要求**：\n- 能够说明品种特征的彩色照片\n- 不同生长期的对比照片\n- 与近似品种的对比照片\n\n**其他材料**：\n- 测试报告（如有）\n- 审定证书（如有）\n- 委托书（委托代理时）\n\n**注意事项**：\n- 所有材料需加盖公章\n- 照片需清晰、规范\n- 描述需准确、详细\n\n(来源: 常见问题库)', '2025-12-24 18:14:58', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 18:14:58', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (91, 0, '系统访客', NULL, NULL, 1, '费用计算标准是什么？', NULL, '2025-12-24 18:14:59', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 18:14:59', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (92, 0, '系统访客', NULL, NULL, 2, '植物新品种权申请费用包括：\n\n**官方费用**：\n1. 申请费：1000元\n2. 审查费：2500元\n3. 年费：第1-6年每年300元，第7-15年每年450元，第16-20年每年900元\n\n**服务费用**（我方）：\n1. 基础代理费：5000-8000元\n2. 预审服务费：3000-5000元\n3. 材料撰写费：2000-4000元\n4. 加急服务费：另议\n\n**优惠政策**：\n- 批量申请享受折扣\n- 长期合作客户优惠\n- 特定品种补贴政策\n\n**付款方式**：\n- 分期付款\n- 一次性付款优惠\n\n**注**：具体费用根据品种类型和服务内容确定，详情请咨询客服。\n\n(来源: 常见问题库)', '植物新品种权申请费用包括：\n\n**官方费用**：\n1. 申请费：1000元\n2. 审查费：2500元\n3. 年费：第1-6年每年300元，第7-15年每年450元，第16-20年每年900元\n\n**服务费用**（我方）：\n1. 基础代理费：5000-8000元\n2. 预审服务费：3000-5000元\n3. 材料撰写费：2000-4000元\n4. 加急服务费：另议\n\n**优惠政策**：\n- 批量申请享受折扣\n- 长期合作客户优惠\n- 特定品种补贴政策\n\n**付款方式**：\n- 分期付款\n- 一次性付款优惠\n\n**注**：具体费用根据品种类型和服务内容确定，详情请咨询客服。\n\n(来源: 常见问题库)', '2025-12-24 18:14:59', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 18:14:59', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (93, 0, '系统访客', NULL, NULL, 1, '植物新品种保护名录', NULL, '2025-12-24 18:15:01', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 18:15:01', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (94, 0, '系统访客', NULL, NULL, 2, '植物新品种保护名录是由国务院农业、林业行政部门分批公布的受保护植物属和种的名单。只有列入名录的植物种类，才可以申请植物新品种权。\n\n(来源: 常见问题库)', '植物新品种保护名录是由国务院农业、林业行政部门分批公布的受保护植物属和种的名单。只有列入名录的植物种类，才可以申请植物新品种权。\n\n(来源: 常见问题库)', '2025-12-24 18:15:01', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 18:15:01', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
