INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (100, 0, '系统访客', NULL, NULL, 2, '不太理解你说的“萨法发的”是什么意思呢。如果你是还想继续了解植物新品种相关内容，比如保护名录里有哪些具体植物等，都可以详细跟我说一说。 ', '不太理解你说的“萨法发的”是什么意思呢。如果你是还想继续了解植物新品种相关内容，比如保护名录里有哪些具体植物等，都可以详细跟我说一说。 ', '2025-12-24 19:33:03', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 19:33:03', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (101, 0, '系统访客', NULL, NULL, 1, '什么是品系', NULL, '2025-12-24 19:33:22', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 19:33:22', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (102, 0, '系统访客', NULL, NULL, 2, '品系指在品种选育过程中，表现良好但尚未命名为品种的变异类型（如优良单株或株系）。它通常是品种选育的中间阶段，不得大面积推广。\n\n(来源: 常见问题库)', '品系指在品种选育过程中，表现良好但尚未命名为品种的变异类型（如优良单株或株系）。它通常是品种选育的中间阶段，不得大面积推广。\n\n(来源: 常见问题库)', '2025-12-24 19:33:22', 'test-session-doubao-final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 19:33:22', '2025-12-25 08:50:18', '系统访客', '系统访客', 1, 1);
