INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (114, 0, '系统访客', NULL, NULL, 2, '目前有3个上传文档，最近的文档列表如下：\n- 保护名录问题说明.docx (类型: docx)\n- 美国植物新品种保护制度分析 (1).pdf (类型: pdf)\n- 知识库测试文档 (类型: txt)', '目前有3个上传文档，最近的文档列表如下：\n- 保护名录问题说明.docx (类型: docx)\n- 美国植物新品种保护制度分析 (1).pdf (类型: pdf)\n- 知识库测试文档 (类型: txt)', '2025-12-24 21:19:30', 'session_1766582366742_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 21:19:30', '2025-12-25 08:50:23', '系统访客', '系统访客', 1, 1);
