INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (116, 0, '系统访客', NULL, NULL, 2, '根据《植物新品种保护条例》，以下植物属或种列入保护名录：\n\n**粮食作物**：\n- 水稻、小麦、玉米、大豆、棉花等\n\n**蔬菜作物**：\n- 番茄、黄瓜、辣椒、白菜、萝卜等\n\n**果树**：\n- 苹果、梨、桃、葡萄、柑橘等\n\n**花卉**：\n- 月季、菊花、百合、郁金香等\n\n**林木**：\n- 杨树、松树、杉树等\n\n**其他**：\n- 牧草、药用植物、观赏植物等\n\n**查询方式**：\n1. 访问农业农村部官网\n2. 查看最新保护名录公告\n3. 咨询我们的专业顾问\n\n**注**：名录会定期更新，建议申请前确认最新版本。\n\n(来源: 常见问题库)', '根据《植物新品种保护条例》，以下植物属或种列入保护名录：\n\n**粮食作物**：\n- 水稻、小麦、玉米、大豆、棉花等\n\n**蔬菜作物**：\n- 番茄、黄瓜、辣椒、白菜、萝卜等\n\n**果树**：\n- 苹果、梨、桃、葡萄、柑橘等\n\n**花卉**：\n- 月季、菊花、百合、郁金香等\n\n**林木**：\n- 杨树、松树、杉树等\n\n**其他**：\n- 牧草、药用植物、观赏植物等\n\n**查询方式**：\n1. 访问农业农村部官网\n2. 查看最新保护名录公告\n3. 咨询我们的专业顾问\n\n**注**：名录会定期更新，建议申请前确认最新版本。\n\n(来源: 常见问题库)', '2025-12-24 21:19:45', 'session_1766582366742_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 21:19:45', '2025-12-25 08:50:23', '系统访客', '系统访客', 1, 1);
