INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (119, 0, '系统访客', NULL, NULL, 1, '什么是品种保护', NULL, '2025-12-24 23:23:53', 'session_1766589532685_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 23:23:53', '2025-12-25 08:50:31', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (120, 0, '系统访客', NULL, NULL, 2, '未查询到与品种保护定义相关的内容，为你按照通用解释作答。品种保护通常指植物新品种保护，是一种知识产权保护制度，旨在保护植物新品种培育者的权益。它依据相关法律，对人工培育或对发现的野生植物加以开发，具备新颖性、特异性、一致性和稳定性并有适当命名的植物品种，授予培育者在一定期限内的独占权。\n\n在我国，植物新品种权申请的物种需在农业、林业保护目录内，两份目录有重叠部分，但分开管理。目前林业共正式发布10批、农业发布11批（第12批待发布），目录中包含能够申请植物新品种权的植物中文属名或种名，以及对应的拉丁文名。获得品种权后，他人未经许可，不得生产、繁殖、销售、进口或出口该授权品种的繁殖材料等。 ', '未查询到与品种保护定义相关的内容，为你按照通用解释作答。品种保护通常指植物新品种保护，是一种知识产权保护制度，旨在保护植物新品种培育者的权益。它依据相关法律，对人工培育或对发现的野生植物加以开发，具备新颖性、特异性、一致性和稳定性并有适当命名的植物品种，授予培育者在一定期限内的独占权。\n\n在我国，植物新品种权申请的物种需在农业、林业保护目录内，两份目录有重叠部分，但分开管理。目前林业共正式发布10批、农业发布11批（第12批待发布），目录中包含能够申请植物新品种权的植物中文属名或种名，以及对应的拉丁文名。获得品种权后，他人未经许可，不得生产、繁殖、销售、进口或出口该授权品种的繁殖材料等。 ', '2025-12-24 23:23:53', 'session_1766589532685_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 23:23:53', '2025-12-25 08:50:31', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (121, 0, '系统访客', NULL, NULL, 1, '什么是品系', NULL, '2025-12-24 23:24:11', 'session_1766589532685_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 23:24:11', '2025-12-25 08:50:31', '系统访客', '系统访客', 1, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (122, 0, '系统访客', NULL, NULL, 2, '品系指在品种选育过程中，表现良好但尚未命名为品种的变异类型（如优良单株或株系）。它通常是品种选育的中间阶段，不得大面积推广。\n\n(来源: 常见问题库)', '品系指在品种选育过程中，表现良好但尚未命名为品种的变异类型（如优良单株或株系）。它通常是品种选育的中间阶段，不得大面积推广。\n\n(来源: 常见问题库)', '2025-12-24 23:24:11', 'session_1766589532685_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-24 23:24:11', '2025-12-25 08:50:31', '系统访客', '系统访客', 1, 1);
