INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (156, 0, '系统访客', NULL, NULL, 2, '未查询到知识库中存在PDF文档。当前知识库中的4个文档分别为：\n1. 《林业局植物新品种保护名录（第1 - 10批）.docx》 \n2. 《保护名录问题说明.docx》\n3. 《MBA高校篮球自由积分赛.docx》\n4. 《系统权威文档库元数据》 ', '未查询到知识库中存在PDF文档。当前知识库中的4个文档分别为：\n1. 《林业局植物新品种保护名录（第1 - 10批）.docx》 \n2. 《保护名录问题说明.docx》\n3. 《MBA高校篮球自由积分赛.docx》\n4. 《系统权威文档库元数据》 ', '2025-12-25 03:57:06', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 03:57:06', '2025-12-25 03:57:06', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (157, 0, '系统访客', NULL, NULL, 1, '积分赛是什么文档，里边什么内容', NULL, '2025-12-25 03:57:25', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 03:57:25', '2025-12-25 03:57:25', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (158, 0, '系统访客', NULL, NULL, 2, '积分赛相关文档是《MBA高校篮球自由积分赛.docx》，该文档介绍了一项完全自由的MBA篮球积分赛，核心内容如下：\n1. **比赛概况**：不设固定赛程、不用赛前报备、不限定比赛时间、打就有积分，每3个月统一排名，半年进行一次颁奖。\n2. **参赛人员**：本校在读学生或已毕业校友自由组队，每队5 - 12人，赛季内一队固定，不可重复报名。\n3. **比赛进行**：各队自行约战，以5v5为主，场地、时间双方自行协商，不设统一裁判，双方认可结果即可有效。\n4. **成绩提交**：比赛结束后，提交双方队名、最终比分、现场合影，审核通过后自动加分，未提交成绩则该场不计分。\n5. **积分规则**：赢一场得+3分，输一场得+1分，无效成绩得0分。\n6. **防刷分规则**：每队每天最多记1场，同一对手一周最多记1场。\n7. **赛季与排名**：一个赛季3个月，按总积分从高到低排名，积分相同看胜场，再看参赛场次。半年积分前三名 + 挑战者队伍一名，四队进行冠亚军季军争夺。\n8. **奖项设置**：每赛季设冠军、亚军、季军、最活跃球队（比赛场次最多）。\n9. **违规说明**：造假比分本场0分 + 警告，打架斗殴直接取消本赛季资格。 ', '积分赛相关文档是《MBA高校篮球自由积分赛.docx》，该文档介绍了一项完全自由的MBA篮球积分赛，核心内容如下：\n1. **比赛概况**：不设固定赛程、不用赛前报备、不限定比赛时间、打就有积分，每3个月统一排名，半年进行一次颁奖。\n2. **参赛人员**：本校在读学生或已毕业校友自由组队，每队5 - 12人，赛季内一队固定，不可重复报名。\n3. **比赛进行**：各队自行约战，以5v5为主，场地、时间双方自行协商，不设统一裁判，双方认可结果即可有效。\n4. **成绩提交**：比赛结束后，提交双方队名、最终比分、现场合影，审核通过后自动加分，未提交成绩则该场不计分。\n5. **积分规则**：赢一场得+3分，输一场得+1分，无效成绩得0分。\n6. **防刷分规则**：每队每天最多记1场，同一对手一周最多记1场。\n7. **赛季与排名**：一个赛季3个月，按总积分从高到低排名，积分相同看胜场，再看参赛场次。半年积分前三名 + 挑战者队伍一名，四队进行冠亚军季军争夺。\n8. **奖项设置**：每赛季设冠军、亚军、季军、最活跃球队（比赛场次最多）。\n9. **违规说明**：造假比分本场0分 + 警告，打架斗殴直接取消本赛季资格。 ', '2025-12-25 03:57:25', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 03:57:25', '2025-12-25 03:57:25', '系统访客', '系统访客', 0, 1);
