INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (160, 0, '系统访客', NULL, NULL, 2, '提供的3篇资讯文档均聚焦于植物品种相关内容，未提及动物相关信息。因此，无法依据现有文档判断狮子能否申请品种保护。 ', '提供的3篇资讯文档均聚焦于植物品种相关内容，未提及动物相关信息。因此，无法依据现有文档判断狮子能否申请品种保护。 ', '2025-12-25 03:57:56', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 03:57:56', '2025-12-25 03:57:56', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (161, 0, '系统访客', NULL, NULL, 1, '你判断申请不能申请标准是什么', NULL, '2025-12-25 03:58:18', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 03:58:18', '2025-12-25 03:58:18', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (162, 0, '系统访客', NULL, NULL, 2, '依据提供的资料，判断植物能否申请新品种权的标准是该植物需在农业、林业保护目录内。这两份目录分开管理且存在重叠部分，目前林业共正式发布10批、农业发布11批（第12批待发布），目录中列举了能够申请植物新品种权的植物中文属名或种名以及对应的拉丁文名。\n\n判断时，若植物名称在目录中直接为原文名称，可直接判定其能申请；若不是原文名称，需判断该植物所属的属是否在目录中，若所属的属在目录中，那么该植物也可以申请。例如凤仙花属被纳入林业植物新品种保护目录第七批，凤仙花作为凤仙花属植物可以申请；槭属被纳入林业植物新品种保护目录第三批，深灰槭作为槭属植物也可以申请。不过现有资料仅围绕植物新品种权申请，对于动物如狮子能否申请品种保护无法据此判断。 ', '依据提供的资料，判断植物能否申请新品种权的标准是该植物需在农业、林业保护目录内。这两份目录分开管理且存在重叠部分，目前林业共正式发布10批、农业发布11批（第12批待发布），目录中列举了能够申请植物新品种权的植物中文属名或种名以及对应的拉丁文名。\n\n判断时，若植物名称在目录中直接为原文名称，可直接判定其能申请；若不是原文名称，需判断该植物所属的属是否在目录中，若所属的属在目录中，那么该植物也可以申请。例如凤仙花属被纳入林业植物新品种保护目录第七批，凤仙花作为凤仙花属植物可以申请；槭属被纳入林业植物新品种保护目录第三批，深灰槭作为槭属植物也可以申请。不过现有资料仅围绕植物新品种权申请，对于动物如狮子能否申请品种保护无法据此判断。 ', '2025-12-25 03:58:18', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 03:58:18', '2025-12-25 03:58:18', '系统访客', '系统访客', 0, 1);
