INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (177, 0, '系统访客', NULL, NULL, 1, '材料准备指南', NULL, '2025-12-25 04:07:06', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 04:07:06', '2025-12-25 04:07:06', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (178, 0, '系统访客', NULL, NULL, 2, '申请植物新品种权需要准备以下材料：\n\n**必备材料**：\n1. 植物新品种权请求书\n2. 说明书及照片\n3. 品种暂定名称\n\n**说明书内容**：\n- 品种来源及育种过程\n- 特征特性描述\n- 栽培技术要点\n- 品种对比说明\n\n**照片要求**：\n- 能够说明品种特征的彩色照片\n- 不同生长期的对比照片\n- 与近似品种的对比照片\n\n**其他材料**：\n- 测试报告（如有）\n- 审定证书（如有）\n- 委托书（委托代理时）\n\n**注意事项**：\n- 所有材料需加盖公章\n- 照片需清晰、规范\n- 描述需准确、详细\n\n(来源: 业务常见问答库)', '申请植物新品种权需要准备以下材料：\n\n**必备材料**：\n1. 植物新品种权请求书\n2. 说明书及照片\n3. 品种暂定名称\n\n**说明书内容**：\n- 品种来源及育种过程\n- 特征特性描述\n- 栽培技术要点\n- 品种对比说明\n\n**照片要求**：\n- 能够说明品种特征的彩色照片\n- 不同生长期的对比照片\n- 与近似品种的对比照片\n\n**其他材料**：\n- 测试报告（如有）\n- 审定证书（如有）\n- 委托书（委托代理时）\n\n**注意事项**：\n- 所有材料需加盖公章\n- 照片需清晰、规范\n- 描述需准确、详细\n\n(来源: 业务常见问答库)', '2025-12-25 04:07:06', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 04:07:06', '2025-12-25 04:07:06', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (179, 0, '系统访客', NULL, NULL, 1, '你们的服务优势', NULL, '2025-12-25 04:07:22', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 04:07:22', '2025-12-25 04:07:22', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (180, 0, '系统访客', NULL, NULL, 2, '所给的参考资料中未提及“AISeedFlow 植物新品种权管理系统”的服务优势相关内容，无法准确为你提供对应的信息。你可以问我一些和植物新品种权申请、名录查询及相关法规有关的问题，我会尽力解答。 ', '所给的参考资料中未提及“AISeedFlow 植物新品种权管理系统”的服务优势相关内容，无法准确为你提供对应的信息。你可以问我一些和植物新品种权申请、名录查询及相关法规有关的问题，我会尽力解答。 ', '2025-12-25 04:07:22', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 04:07:22', '2025-12-25 04:07:22', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (181, 0, '系统访客', NULL, NULL, 1, '预审服务有什么优势？', NULL, '2025-12-25 04:07:45', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 04:07:45', '2025-12-25 04:07:45', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (182, 0, '系统访客', NULL, NULL, 2, '我们的预审服务具有以下优势：\n\n1. **专业评估**：由资深专家对申请材料进行全面审查，提前发现潜在问题。\n\n2. **提高成功率**：通过预审可以大幅提高正式申请的通过率，避免因材料问题导致的驳回。\n\n3. **节省时间**：提前发现并解决问题，避免反复修改，缩短整体申请周期。\n\n4. **降低风险**：减少因申请失败造成的经济损失和时间成本。\n\n5. **专业指导**：获得针对性的改进建议和优化方案。\n\n6. **优先处理**：预审客户享有优先服务通道。\n\n(来源: 业务常见问答库)', '我们的预审服务具有以下优势：\n\n1. **专业评估**：由资深专家对申请材料进行全面审查，提前发现潜在问题。\n\n2. **提高成功率**：通过预审可以大幅提高正式申请的通过率，避免因材料问题导致的驳回。\n\n3. **节省时间**：提前发现并解决问题，避免反复修改，缩短整体申请周期。\n\n4. **降低风险**：减少因申请失败造成的经济损失和时间成本。\n\n5. **专业指导**：获得针对性的改进建议和优化方案。\n\n6. **优先处理**：预审客户享有优先服务通道。\n\n(来源: 业务常见问答库)', '2025-12-25 04:07:45', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 04:07:45', '2025-12-25 04:07:45', '系统访客', '系统访客', 0, 1);
