INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (194, 0, '系统访客', NULL, NULL, 2, '你的问题与植物新品种权领域不相关，我专注于处理该领域的问题，如植物新品种权申请、相关名录查询、法规咨询等。若你有这方面的疑惑，随时可以问我。 ', '你的问题与植物新品种权领域不相关，我专注于处理该领域的问题，如植物新品种权申请、相关名录查询、法规咨询等。若你有这方面的疑惑，随时可以问我。 ', '2025-12-25 04:28:53', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 04:28:53', '2025-12-25 04:28:53', '系统访客', '系统访客', 0, 1);
