INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (196, 0, '系统访客', NULL, NULL, 2, '不太理解你说的“哗啦啦”是什么意思。如果你有关于植物新品种权相关的问题，比如某个品种能否申请新品种权、申请流程、所需材料等，都可以详细跟我说，我会为你专业解答。 ', '不太理解你说的“哗啦啦”是什么意思。如果你有关于植物新品种权相关的问题，比如某个品种能否申请新品种权、申请流程、所需材料等，都可以详细跟我说，我会为你专业解答。 ', '2025-12-25 04:29:05', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 04:29:05', '2025-12-25 04:29:05', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (197, 0, '系统访客', NULL, NULL, 1, '怎么收费的', NULL, '2025-12-25 04:29:23', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 04:29:23', '2025-12-25 04:29:23', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (198, 0, '系统访客', NULL, NULL, 2, '我是 AISeedFlow 助手，关于收费问题请咨询专家。 ', '我是 AISeedFlow 助手，关于收费问题请咨询专家。 ', '2025-12-25 04:29:23', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 04:29:23', '2025-12-25 04:29:23', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (199, 0, '系统访客', NULL, NULL, 1, '基本条件', NULL, '2025-12-25 04:29:47', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 04:29:47', '2025-12-25 04:29:47', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (200, 0, '系统访客', NULL, NULL, 2, '申请植物新品种权需要满足以下基本条件：\n\n1. **新颖性**：申请品种在申请日前该品种繁殖材料未被销售，或者经育种者许可，在中国境内销售该品种繁殖材料未超过1年。\n\n2. **特异性**：申请品种应当明显区别于在递交申请以前已知的品种。\n\n3. **一致性**：申请品种经过繁殖，除可以预见的变异外，其相关的特征或者特性一致。\n\n4. **稳定性**：申请品种经过反复繁殖后或者在特定繁殖周期结束时，其相关的特征或者特性保持不变。\n\n5. **适当命名**：申请品种应当具备适当的名称，并与相同或者相近的植物属或者种中已知品种的名称相区别。\n\n(来源: 业务规范常见问答库)', '申请植物新品种权需要满足以下基本条件：\n\n1. **新颖性**：申请品种在申请日前该品种繁殖材料未被销售，或者经育种者许可，在中国境内销售该品种繁殖材料未超过1年。\n\n2. **特异性**：申请品种应当明显区别于在递交申请以前已知的品种。\n\n3. **一致性**：申请品种经过繁殖，除可以预见的变异外，其相关的特征或者特性一致。\n\n4. **稳定性**：申请品种经过反复繁殖后或者在特定繁殖周期结束时，其相关的特征或者特性保持不变。\n\n5. **适当命名**：申请品种应当具备适当的名称，并与相同或者相近的植物属或者种中已知品种的名称相区别。\n\n(来源: 业务规范常见问答库)', '2025-12-25 04:29:47', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 04:29:47', '2025-12-25 04:29:47', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (201, 0, '系统访客', NULL, NULL, 1, '预审服务有什么优势？', NULL, '2025-12-25 04:29:51', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 04:29:51', '2025-12-25 04:29:51', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (202, 0, '系统访客', NULL, NULL, 2, '我们的预审服务具有以下优势：\n\n1. **专业评估**：由资深专家对申请材料进行全面审查，提前发现潜在问题。\n\n2. **提高成功率**：通过预审可以大幅提高正式申请的通过率，避免因材料问题导致的驳回。\n\n3. **节省时间**：提前发现并解决问题，避免反复修改，缩短整体申请周期。\n\n4. **降低风险**：减少因申请失败造成的经济损失和时间成本。\n\n5. **专业指导**：获得针对性的改进建议和优化方案。\n\n6. **优先处理**：预审客户享有优先服务通道。\n\n(来源: 业务规范常见问答库)', '我们的预审服务具有以下优势：\n\n1. **专业评估**：由资深专家对申请材料进行全面审查，提前发现潜在问题。\n\n2. **提高成功率**：通过预审可以大幅提高正式申请的通过率，避免因材料问题导致的驳回。\n\n3. **节省时间**：提前发现并解决问题，避免反复修改，缩短整体申请周期。\n\n4. **降低风险**：减少因申请失败造成的经济损失和时间成本。\n\n5. **专业指导**：获得针对性的改进建议和优化方案。\n\n6. **优先处理**：预审客户享有优先服务通道。\n\n(来源: 业务规范常见问答库)', '2025-12-25 04:29:51', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 04:29:51', '2025-12-25 04:29:51', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (203, 0, '系统访客', NULL, NULL, 1, '葵花能申请品种权吗', NULL, '2025-12-25 04:30:08', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 04:30:08', '2025-12-25 04:30:08', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (204, 0, '系统访客', NULL, NULL, 2, '葵花为向日葵属植物，目前现有资料未表明向日葵属被纳入农业或林业植物新品种保护目录，所以仅依据现有信息，无法确定葵花能申请品种权。后续可关注农业发布的第 12 批以及林业可能发布的新一批保护目录，以获取最新的可申请品种信息。 ', '葵花为向日葵属植物，目前现有资料未表明向日葵属被纳入农业或林业植物新品种保护目录，所以仅依据现有信息，无法确定葵花能申请品种权。后续可关注农业发布的第 12 批以及林业可能发布的新一批保护目录，以获取最新的可申请品种信息。 ', '2025-12-25 04:30:08', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 04:30:08', '2025-12-25 04:30:08', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (205, 0, '系统访客', NULL, NULL, 1, '24 年做过品种登记的现在可以报品种权吗', NULL, '2025-12-25 04:35:37', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 04:35:37', '2025-12-25 04:35:37', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (206, 0, '系统访客', NULL, NULL, 2, '做过品种登记后能否申报品种权关键在于是否满足品种权申请的各项条件。从申请条件来看，要考量新颖性、特异性、一致性和稳定性等方面。\n\n若该品种在完成登记之后，符合植物新品种权对于新颖性的要求，即在申请日之前，其繁殖材料未以商业目的进行销售，或者销售行为在规定的时间范围与条件之内；同时，品种具备明显区别于已知品种的特征（特异性），经过繁殖后相关特征一致（一致性），且这些特征在反复繁殖后保持稳定（稳定性），那么就可以申报品种权。 \n\n不过，需要特别注意一些品种登记和品种权申请在要求上可能存在不同的执行细则和相关规定。所以，就算满足上述基本条件，在具体申报时，仍需详细按照农业或林业的品种权申请流程与要求准备材料，经过严格审查和审批。要确保申请流程合法合规，才能成功获得品种权。 ', '做过品种登记后能否申报品种权关键在于是否满足品种权申请的各项条件。从申请条件来看，要考量新颖性、特异性、一致性和稳定性等方面。\n\n若该品种在完成登记之后，符合植物新品种权对于新颖性的要求，即在申请日之前，其繁殖材料未以商业目的进行销售，或者销售行为在规定的时间范围与条件之内；同时，品种具备明显区别于已知品种的特征（特异性），经过繁殖后相关特征一致（一致性），且这些特征在反复繁殖后保持稳定（稳定性），那么就可以申报品种权。 \n\n不过，需要特别注意一些品种登记和品种权申请在要求上可能存在不同的执行细则和相关规定。所以，就算满足上述基本条件，在具体申报时，仍需详细按照农业或林业的品种权申请流程与要求准备材料，经过严格审查和审批。要确保申请流程合法合规，才能成功获得品种权。 ', '2025-12-25 04:35:37', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-25 04:35:37', '2025-12-25 04:35:37', '系统访客', '系统访客', 0, 1);
