INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (212, 0, '系统访客', NULL, NULL, 2, '系统中的文件有：《林业局植物新品种保护名录（第1 - 10批）》《林业局植物新品种保护名录第一批》《植物育种基础概念》《MBA高校篮球自由积分赛》《保护名录问题说明》《植物新品种权申请完整流程指南》《美国植物新品种保护制度分析 (1).pdf》。 ', '系统中的文件有：《林业局植物新品种保护名录（第1 - 10批）》《林业局植物新品种保护名录第一批》《植物育种基础概念》《MBA高校篮球自由积分赛》《保护名录问题说明》《植物新品种权申请完整流程指南》《美国植物新品种保护制度分析 (1).pdf》。 ', '2025-12-26 22:58:28', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-26 22:58:28', '2025-12-26 22:58:28', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (213, 0, '系统访客', NULL, NULL, 1, 'MBA高校篮球自由积分赛 内容是啥', NULL, '2025-12-26 22:58:49', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-26 22:58:49', '2025-12-26 22:58:49', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (214, 0, '系统访客', NULL, NULL, 2, 'MBA高校篮球自由积分赛是一个完全自由的赛事，以下为你详细介绍：\n1. **参赛人员与组队**：本校在读学生或已毕业校友可自由组队参赛，每队人数在5 - 12人，且赛季内队伍人员固定，不可重复报名。\n2. **比赛形式**\n    - **约战方式**：各队自行约战，不设固定赛程，不用赛前报备，也不限定比赛时间。\n    - **比赛形式**：以5v5为主，场地和时间由双方自行协商确定，不设统一裁判，双方认可比赛结果即可。\n3. **成绩提交**：这是比赛唯一必须做的事。比赛结束后，提交双方队名、最终比分、现场合影这3项内容，审核通过后自动加分；若未提交成绩，则该场比赛不计分。\n4. **积分规则**\n    - **获胜**：赢一场获得3分。\n    - **失败**：输一场获得1分。\n    - **无效成绩**：得0分。\n5. **防刷分规则**：每队每天最多记1场比赛成绩，同一对手一周最多记1场比赛成绩，其余时间比赛安排完全自由。\n6. **赛季与排名**\n    - **赛季时长**：一个赛季为3个月，按总积分从高到低排名。\n    - **排名细则**：若积分相同，先看胜场数，再看参赛场次。半年积分前三名的队伍和挑战者队伍一名，共四队进行冠亚军季军争夺。\n7. **奖项设置**：每赛季设置冠军、亚军、季军，以及最活跃球队（比赛场次最多）奖项。\n8. **违规说明**\n    - **造假比分**：本场比赛记0分，并给予警告。\n    - **打架斗殴**：直接取消本赛季参赛资格。 ', 'MBA高校篮球自由积分赛是一个完全自由的赛事，以下为你详细介绍：\n1. **参赛人员与组队**：本校在读学生或已毕业校友可自由组队参赛，每队人数在5 - 12人，且赛季内队伍人员固定，不可重复报名。\n2. **比赛形式**\n    - **约战方式**：各队自行约战，不设固定赛程，不用赛前报备，也不限定比赛时间。\n    - **比赛形式**：以5v5为主，场地和时间由双方自行协商确定，不设统一裁判，双方认可比赛结果即可。\n3. **成绩提交**：这是比赛唯一必须做的事。比赛结束后，提交双方队名、最终比分、现场合影这3项内容，审核通过后自动加分；若未提交成绩，则该场比赛不计分。\n4. **积分规则**\n    - **获胜**：赢一场获得3分。\n    - **失败**：输一场获得1分。\n    - **无效成绩**：得0分。\n5. **防刷分规则**：每队每天最多记1场比赛成绩，同一对手一周最多记1场比赛成绩，其余时间比赛安排完全自由。\n6. **赛季与排名**\n    - **赛季时长**：一个赛季为3个月，按总积分从高到低排名。\n    - **排名细则**：若积分相同，先看胜场数，再看参赛场次。半年积分前三名的队伍和挑战者队伍一名，共四队进行冠亚军季军争夺。\n7. **奖项设置**：每赛季设置冠军、亚军、季军，以及最活跃球队（比赛场次最多）奖项。\n8. **违规说明**\n    - **造假比分**：本场比赛记0分，并给予警告。\n    - **打架斗殴**：直接取消本赛季参赛资格。 ', '2025-12-26 22:58:49', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-26 22:58:49', '2025-12-26 22:58:49', '系统访客', '系统访客', 0, 1);
