INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (217, 0, '系统访客', NULL, NULL, 1, '申请基本条件是什么？', NULL, '2025-12-26 23:01:55', 'session_1766761312311_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-26 23:01:55', '2025-12-26 23:01:55', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (218, 0, '系统访客', NULL, NULL, 2, '申请植物新品种权需要满足以下基本条件：\n\n1. **新颖性**：申请品种在申请日前该品种繁殖材料未被销售，或者经育种者许可，在中国境内销售该品种繁殖材料未超过1年。\n\n2. **特异性**：申请品种应当明显区别于在递交申请以前已知的品种。\n\n3. **一致性**：申请品种经过繁殖，除可以预见的变异外，其相关的特征或者特性一致。\n\n4. **稳定性**：申请品种经过反复繁殖后或者在特定繁殖周期结束时，其相关的特征或者特性保持不变。\n\n5. **适当命名**：申请品种应当具备适当的名称，并与相同或者相近的植物属或者种中已知品种的名称相区别。\n\n(来源: 业务规范常见问答库)', '申请植物新品种权需要满足以下基本条件：\n\n1. **新颖性**：申请品种在申请日前该品种繁殖材料未被销售，或者经育种者许可，在中国境内销售该品种繁殖材料未超过1年。\n\n2. **特异性**：申请品种应当明显区别于在递交申请以前已知的品种。\n\n3. **一致性**：申请品种经过繁殖，除可以预见的变异外，其相关的特征或者特性一致。\n\n4. **稳定性**：申请品种经过反复繁殖后或者在特定繁殖周期结束时，其相关的特征或者特性保持不变。\n\n5. **适当命名**：申请品种应当具备适当的名称，并与相同或者相近的植物属或者种中已知品种的名称相区别。\n\n(来源: 业务规范常见问答库)', '2025-12-26 23:01:55', 'session_1766761312311_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-26 23:01:55', '2025-12-26 23:01:55', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (219, 0, '系统访客', NULL, NULL, 1, '预审服务有什么优势？', NULL, '2025-12-26 23:01:56', 'session_1766761312311_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-26 23:01:56', '2025-12-26 23:01:56', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (220, 0, '系统访客', NULL, NULL, 2, '我们的预审服务具有以下优势：\n\n1. **专业评估**：由资深专家对申请材料进行全面审查，提前发现潜在问题。\n\n2. **提高成功率**：通过预审可以大幅提高正式申请的通过率，避免因材料问题导致的驳回。\n\n3. **节省时间**：提前发现并解决问题，避免反复修改，缩短整体申请周期。\n\n4. **降低风险**：减少因申请失败造成的经济损失和时间成本。\n\n5. **专业指导**：获得针对性的改进建议和优化方案。\n\n6. **优先处理**：预审客户享有优先服务通道。\n\n(来源: 业务规范常见问答库)', '我们的预审服务具有以下优势：\n\n1. **专业评估**：由资深专家对申请材料进行全面审查，提前发现潜在问题。\n\n2. **提高成功率**：通过预审可以大幅提高正式申请的通过率，避免因材料问题导致的驳回。\n\n3. **节省时间**：提前发现并解决问题，避免反复修改，缩短整体申请周期。\n\n4. **降低风险**：减少因申请失败造成的经济损失和时间成本。\n\n5. **专业指导**：获得针对性的改进建议和优化方案。\n\n6. **优先处理**：预审客户享有优先服务通道。\n\n(来源: 业务规范常见问答库)', '2025-12-26 23:01:56', 'session_1766761312311_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-26 23:01:56', '2025-12-26 23:01:56', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (221, 0, '系统访客', NULL, NULL, 1, '申请时间周期是多久？', NULL, '2025-12-26 23:01:57', 'session_1766761312311_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-26 23:01:57', '2025-12-26 23:01:57', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (222, 0, '系统访客', NULL, NULL, 2, '植物新品种权申请的时间周期如下：\n\n**正常流程**：\n- 材料准备：1-2个月\n- 初步审查：3-6个月\n- 实质审查：12-18个月\n- 授权公告：1-2个月\n- **总计**：约18-28个月\n\n**加急通道**（符合条件）：\n- 可缩短至12-15个月\n\n**影响因素**：\n1. 材料完整性和规范性\n2. 品种测试周期\n3. 审查机关工作量\n4. 补正材料的及时性\n\n**建议**：选择我们的预审服务可以有效缩短整体周期。\n\n(来源: 业务规范常见问答库)', '植物新品种权申请的时间周期如下：\n\n**正常流程**：\n- 材料准备：1-2个月\n- 初步审查：3-6个月\n- 实质审查：12-18个月\n- 授权公告：1-2个月\n- **总计**：约18-28个月\n\n**加急通道**（符合条件）：\n- 可缩短至12-15个月\n\n**影响因素**：\n1. 材料完整性和规范性\n2. 品种测试周期\n3. 审查机关工作量\n4. 补正材料的及时性\n\n**建议**：选择我们的预审服务可以有效缩短整体周期。\n\n(来源: 业务规范常见问答库)', '2025-12-26 23:01:57', 'session_1766761312311_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-26 23:01:57', '2025-12-26 23:01:57', '系统访客', '系统访客', 0, 1);
