INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (226, 0, '系统访客', NULL, NULL, 1, '材料准备指南', NULL, '2025-12-26 23:01:59', 'session_1766761312311_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-26 23:01:59', '2025-12-26 23:01:59', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (227, 0, '系统访客', NULL, NULL, 2, '申请植物新品种权需要准备以下材料：\n\n**必备材料**：\n1. 植物新品种权请求书\n2. 说明书及照片\n3. 品种暂定名称\n\n**说明书内容**：\n- 品种来源及育种过程\n- 特征特性描述\n- 栽培技术要点\n- 品种对比说明\n\n**照片要求**：\n- 能够说明品种特征的彩色照片\n- 不同生长期的对比照片\n- 与近似品种的对比照片\n\n**其他材料**：\n- 测试报告（如有）\n- 审定证书（如有）\n- 委托书（委托代理时）\n\n**注意事项**：\n- 所有材料需加盖公章\n- 照片需清晰、规范\n- 描述需准确、详细\n\n(来源: 业务规范常见问答库)', '申请植物新品种权需要准备以下材料：\n\n**必备材料**：\n1. 植物新品种权请求书\n2. 说明书及照片\n3. 品种暂定名称\n\n**说明书内容**：\n- 品种来源及育种过程\n- 特征特性描述\n- 栽培技术要点\n- 品种对比说明\n\n**照片要求**：\n- 能够说明品种特征的彩色照片\n- 不同生长期的对比照片\n- 与近似品种的对比照片\n\n**其他材料**：\n- 测试报告（如有）\n- 审定证书（如有）\n- 委托书（委托代理时）\n\n**注意事项**：\n- 所有材料需加盖公章\n- 照片需清晰、规范\n- 描述需准确、详细\n\n(来源: 业务规范常见问答库)', '2025-12-26 23:01:59', 'session_1766761312311_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-26 23:01:59', '2025-12-26 23:01:59', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (228, 0, '系统访客', NULL, NULL, 2, '植物新品种权申请的费用计算标准如下：\n- **初审费**：1000元。\n- **实质审查费**：2500元。\n- **年费**：第1 - 6年每年600元，第7 - 15年每年900元，第16 - 20年每年1200元。 ', '植物新品种权申请的费用计算标准如下：\n- **初审费**：1000元。\n- **实质审查费**：2500元。\n- **年费**：第1 - 6年每年600元，第7 - 15年每年900元，第16 - 20年每年1200元。 ', '2025-12-26 23:01:59', 'session_1766761312311_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-26 23:01:59', '2025-12-26 23:01:59', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (229, 0, '系统访客', NULL, NULL, 2, '植物新品种权申请的费用计算标准如下：\n- **初审费**：1000 元。\n- **实质审查费**：2500 元。\n- **年费**：第 1 - 6 年每年 600 元，第 7 - 15 年每年 900 元，第 16 - 20 年每年 1200 元。 \n\n需注意，品种权有效期里，林木、果树、观赏树木为 25 年，需按时缴纳相应年费。 ', '植物新品种权申请的费用计算标准如下：\n- **初审费**：1000 元。\n- **实质审查费**：2500 元。\n- **年费**：第 1 - 6 年每年 600 元，第 7 - 15 年每年 900 元，第 16 - 20 年每年 1200 元。 \n\n需注意，品种权有效期里，林木、果树、观赏树木为 25 年，需按时缴纳相应年费。 ', '2025-12-26 23:01:58', 'session_1766761312311_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-26 23:01:58', '2025-12-26 23:01:58', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (230, 0, '系统访客', NULL, NULL, 2, '目前林业共正式发布 10 批、农业发布 11 批（第 12 批待发布）植物新品种保护名录，以下是部分名录信息：\n\n### 林业植物新品种保护名录第一批\n1. **杨树属（Populus）**\n    - **白杨组**：毛白杨（Populus tomentosa）、银白杨（Populus alba）、响叶杨（Populus adenopoda）、山杨（Populus davidiana）\n    - **黑杨组**：美洲黑杨（Populus deltoides）、欧洲黑杨（Populus nigra）、小叶杨（Populus simonii）\n2. **松树属（Pinus）**\n    - **硬松类**：马尾松（Pinus massoniana）、油松（Pinus tabuliformis）、黑松（Pinus thunbergii）、赤松（Pinus densiflora）\n    - **软松类**：红松（Pinus koraiensis）、华山松（Pinus armandii）、白皮松（Pinus bungeana）\n3. **杉木属（Cunninghamia）**：杉木（Cunninghamia lanceolata）、台湾杉（Cunninghamia konishii）\n4. **柳树属（Salix）**：垂柳（Salix babylonica）、旱柳（Salix matsudana）、白柳（Salix alba）、紫柳（Salix purpurea）\n5. **桉树属（Eucalyptus）**：蓝桉（Eucalyptus globulus）、赤桉（Eucalyptus camaldulensis）、柠檬桉（Eucalyptus citriodora）、巨桉（Eucalyptus grandis）\n\n### 林业植物新品种保护名录其他部分属名 \n当归属（Angelica L.）、天门冬属（蔬菜除外）（Asparagus L.）、锁阳属（Cynomorium L.）、疆前胡属（Peucedanum L.）、水飞蓟属（Silybum Vaill. ex Adans.）、大吴风草属（Farfugium Lindl.）、雪铁芋属（Zamioculcas Schott）。\n\n农业植物新品种保护名录暂未详细列出属种信息，但受保护的植物类别包括粮食作物（水稻、小麦、玉米、大豆等）、经济作物（棉花、油菜、甘蔗等）、蔬菜作物（番茄、黄瓜、辣椒等）、果树（苹果、梨、桃、葡萄等）、林木（杨树、松树、杉树等）。 ', '目前林业共正式发布 10 批、农业发布 11 批（第 12 批待发布）植物新品种保护名录，以下是部分名录信息：\n\n### 林业植物新品种保护名录第一批\n1. **杨树属（Populus）**\n    - **白杨组**：毛白杨（Populus tomentosa）、银白杨（Populus alba）、响叶杨（Populus adenopoda）、山杨（Populus davidiana）\n    - **黑杨组**：美洲黑杨（Populus deltoides）、欧洲黑杨（Populus nigra）、小叶杨（Populus simonii）\n2. **松树属（Pinus）**\n    - **硬松类**：马尾松（Pinus massoniana）、油松（Pinus tabuliformis）、黑松（Pinus thunbergii）、赤松（Pinus densiflora）\n    - **软松类**：红松（Pinus koraiensis）、华山松（Pinus armandii）、白皮松（Pinus bungeana）\n3. **杉木属（Cunninghamia）**：杉木（Cunninghamia lanceolata）、台湾杉（Cunninghamia konishii）\n4. **柳树属（Salix）**：垂柳（Salix babylonica）、旱柳（Salix matsudana）、白柳（Salix alba）、紫柳（Salix purpurea）\n5. **桉树属（Eucalyptus）**：蓝桉（Eucalyptus globulus）、赤桉（Eucalyptus camaldulensis）、柠檬桉（Eucalyptus citriodora）、巨桉（Eucalyptus grandis）\n\n### 林业植物新品种保护名录其他部分属名 \n当归属（Angelica L.）、天门冬属（蔬菜除外）（Asparagus L.）、锁阳属（Cynomorium L.）、疆前胡属（Peucedanum L.）、水飞蓟属（Silybum Vaill. ex Adans.）、大吴风草属（Farfugium Lindl.）、雪铁芋属（Zamioculcas Schott）。\n\n农业植物新品种保护名录暂未详细列出属种信息，但受保护的植物类别包括粮食作物（水稻、小麦、玉米、大豆等）、经济作物（棉花、油菜、甘蔗等）、蔬菜作物（番茄、黄瓜、辣椒等）、果树（苹果、梨、桃、葡萄等）、林木（杨树、松树、杉树等）。 ', '2025-12-26 23:01:58', 'session_1766761312311_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-26 23:01:58', '2025-12-26 23:01:58', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (231, 0, '系统访客', NULL, NULL, 1, '申请基本条件是什么？', NULL, '2025-12-26 23:02:44', 'session_1766761312311_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-26 23:02:44', '2025-12-26 23:02:44', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (232, 0, '系统访客', NULL, NULL, 2, '申请植物新品种权需要满足以下基本条件：\n\n1. **新颖性**：申请品种在申请日前该品种繁殖材料未被销售，或者经育种者许可，在中国境内销售该品种繁殖材料未超过1年。\n\n2. **特异性**：申请品种应当明显区别于在递交申请以前已知的品种。\n\n3. **一致性**：申请品种经过繁殖，除可以预见的变异外，其相关的特征或者特性一致。\n\n4. **稳定性**：申请品种经过反复繁殖后或者在特定繁殖周期结束时，其相关的特征或者特性保持不变。\n\n5. **适当命名**：申请品种应当具备适当的名称，并与相同或者相近的植物属或者种中已知品种的名称相区别。\n\n(来源: 业务规范常见问答库)', '申请植物新品种权需要满足以下基本条件：\n\n1. **新颖性**：申请品种在申请日前该品种繁殖材料未被销售，或者经育种者许可，在中国境内销售该品种繁殖材料未超过1年。\n\n2. **特异性**：申请品种应当明显区别于在递交申请以前已知的品种。\n\n3. **一致性**：申请品种经过繁殖，除可以预见的变异外，其相关的特征或者特性一致。\n\n4. **稳定性**：申请品种经过反复繁殖后或者在特定繁殖周期结束时，其相关的特征或者特性保持不变。\n\n5. **适当命名**：申请品种应当具备适当的名称，并与相同或者相近的植物属或者种中已知品种的名称相区别。\n\n(来源: 业务规范常见问答库)', '2025-12-26 23:02:44', 'session_1766761312311_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-26 23:02:44', '2025-12-26 23:02:44', '系统访客', '系统访客', 0, 1);
