INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (238, 0, '系统访客', NULL, NULL, 2, '知识库中的文件分别是：\n1. 《林业局植物新品种保护名录（第1 - 10批）》\n2. 《植物育种基础概念》\n3. 《林业局植物新品种保护名录第一批》\n4. 《保护名录问题说明》\n5. 《MBA高校篮球自由积分赛》\n6. 《植物新品种权申请完整流程指南》 ', '知识库中的文件分别是：\n1. 《林业局植物新品种保护名录（第1 - 10批）》\n2. 《植物育种基础概念》\n3. 《林业局植物新品种保护名录第一批》\n4. 《保护名录问题说明》\n5. 《MBA高校篮球自由积分赛》\n6. 《植物新品种权申请完整流程指南》 ', '2025-12-28 23:02:07', 'session_1766934110414_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-28 23:02:07', '2025-12-28 23:02:07', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (239, 0, '系统访客', NULL, NULL, 1, 'MBA高校篮球自由积分赛 内容是什么', NULL, '2025-12-28 23:02:26', 'session_1766934110414_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-28 23:02:26', '2025-12-28 23:02:26', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (240, 0, '系统访客', NULL, NULL, 2, 'MBA高校篮球自由积分赛是完全自由的赛事，具体内容如下：\n### 参赛人员\n本校在读学生或已毕业校友自由组队，每队5 - 12人，赛季内一队固定，不可重复报名。\n\n### 比赛形式\n- **约战方式**：各队自行约战，不设固定赛程、不用赛前报备、不限定比赛时间。\n- **比赛形式**：以5v5为主，场地、时间双方自行协商，不设统一裁判，双方认可结果即可有效。\n\n### 计分要求\n比赛结束后，提交双方队名、最终比分、现场合影，审核通过后自动加分；未提交成绩则该场不计分。\n\n### 积分规则\n- 赢：+3分\n- 输：+1分\n- 无效成绩：0分 \n\n### 防刷分规则\n每队每天最多记1场，同一对手一周最多记1场。\n\n### 赛季与排名\n- 一个赛季为3个月，按总积分从高到低排名。若积分相同，先看胜场，再看参赛场次。\n- 半年积分前三名与挑战者队伍一名，四队进行冠亚军季军争夺。\n\n### 奖项设置\n每赛季设置冠军、亚军、季军，以及比赛场次最多的最活跃球队。\n\n### 违规说明\n- 造假比分：本场0分 + 警告\n- 打架斗殴：直接取消本赛季资格 ', 'MBA高校篮球自由积分赛是完全自由的赛事，具体内容如下：\n### 参赛人员\n本校在读学生或已毕业校友自由组队，每队5 - 12人，赛季内一队固定，不可重复报名。\n\n### 比赛形式\n- **约战方式**：各队自行约战，不设固定赛程、不用赛前报备、不限定比赛时间。\n- **比赛形式**：以5v5为主，场地、时间双方自行协商，不设统一裁判，双方认可结果即可有效。\n\n### 计分要求\n比赛结束后，提交双方队名、最终比分、现场合影，审核通过后自动加分；未提交成绩则该场不计分。\n\n### 积分规则\n- 赢：+3分\n- 输：+1分\n- 无效成绩：0分 \n\n### 防刷分规则\n每队每天最多记1场，同一对手一周最多记1场。\n\n### 赛季与排名\n- 一个赛季为3个月，按总积分从高到低排名。若积分相同，先看胜场，再看参赛场次。\n- 半年积分前三名与挑战者队伍一名，四队进行冠亚军季军争夺。\n\n### 奖项设置\n每赛季设置冠军、亚军、季军，以及比赛场次最多的最活跃球队。\n\n### 违规说明\n- 造假比分：本场0分 + 警告\n- 打架斗殴：直接取消本赛季资格 ', '2025-12-28 23:02:26', 'session_1766934110414_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-28 23:02:26', '2025-12-28 23:02:26', '系统访客', '系统访客', 0, 1);
