INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (242, 0, '系统访客', NULL, NULL, 2, '品系指在品种选育过程中，表现良好但尚未命名为品种的变异类型（如优良单株或株系）。它通常是品种选育的中间阶段，不得大面积推广。\n\n(来源: 业务规范常见问答库)', '品系指在品种选育过程中，表现良好但尚未命名为品种的变异类型（如优良单株或株系）。它通常是品种选育的中间阶段，不得大面积推广。\n\n(来源: 业务规范常见问答库)', '2025-12-28 23:02:55', 'session_1766934110414_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-28 23:02:55', '2025-12-28 23:02:55', '系统访客', '系统访客', 0, 1);
