INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (248, 0, '系统访客', NULL, NULL, 2, '不太明确你所说“总结下什么问题”具体指什么。你之前咨询了以下几方面内容：\n1. 知识库文件数量及名称。\n2. MBA高校篮球自由积分赛的具体内容。\n3. 品系的定义。\n4. 关于“百度”的询问。\n\n若你有其他需求，比如对植物新品种权相关问题进行总结、对之前咨询内容进一步总结等，请详细说明。 ', '不太明确你所说“总结下什么问题”具体指什么。你之前咨询了以下几方面内容：\n1. 知识库文件数量及名称。\n2. MBA高校篮球自由积分赛的具体内容。\n3. 品系的定义。\n4. 关于“百度”的询问。\n\n若你有其他需求，比如对植物新品种权相关问题进行总结、对之前咨询内容进一步总结等，请详细说明。 ', '2025-12-28 23:04:30', 'session_1766934110414_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-28 23:04:30', '2025-12-28 23:04:30', '系统访客', '系统访客', 0, 1);
