INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (250, 0, '系统访客', NULL, NULL, 2, '植物新品种权申请的费用如下：\n- 初审费：1000元。\n- 实质审查费：2500元。\n- 年费：第1 - 6年每年600元，第7 - 15年每年900元，第16 - 20年每年1200元。 ', '植物新品种权申请的费用如下：\n- 初审费：1000元。\n- 实质审查费：2500元。\n- 年费：第1 - 6年每年600元，第7 - 15年每年900元，第16 - 20年每年1200元。 ', '2025-12-28 23:05:27', 'session_1766934110414_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-28 23:05:27', '2025-12-28 23:05:27', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (251, 0, '系统访客', NULL, NULL, 1, '申请基本条件是什么？', NULL, '2025-12-28 23:07:57', 'session_1766934110414_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-28 23:07:57', '2025-12-28 23:07:57', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (252, 0, '系统访客', NULL, NULL, 2, '申请植物新品种权需要满足以下基本条件：\n\n1. **新颖性**：申请品种在申请日前该品种繁殖材料未被销售，或者经育种者许可，在中国境内销售该品种繁殖材料未超过1年。\n\n2. **特异性**：申请品种应当明显区别于在递交申请以前已知的品种。\n\n3. **一致性**：申请品种经过繁殖，除可以预见的变异外，其相关的特征或者特性一致。\n\n4. **稳定性**：申请品种经过反复繁殖后或者在特定繁殖周期结束时，其相关的特征或者特性保持不变。\n\n5. **适当命名**：申请品种应当具备适当的名称，并与相同或者相近的植物属或者种中已知品种的名称相区别。\n\n(来源: 业务规范常见问答库)', '申请植物新品种权需要满足以下基本条件：\n\n1. **新颖性**：申请品种在申请日前该品种繁殖材料未被销售，或者经育种者许可，在中国境内销售该品种繁殖材料未超过1年。\n\n2. **特异性**：申请品种应当明显区别于在递交申请以前已知的品种。\n\n3. **一致性**：申请品种经过繁殖，除可以预见的变异外，其相关的特征或者特性一致。\n\n4. **稳定性**：申请品种经过反复繁殖后或者在特定繁殖周期结束时，其相关的特征或者特性保持不变。\n\n5. **适当命名**：申请品种应当具备适当的名称，并与相同或者相近的植物属或者种中已知品种的名称相区别。\n\n(来源: 业务规范常见问答库)', '2025-12-28 23:07:57', 'session_1766934110414_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-28 23:07:57', '2025-12-28 23:07:57', '系统访客', '系统访客', 0, 1);
