INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (257, 0, '系统访客', NULL, NULL, 1, '新手如何申请支持产权', NULL, '2025-12-29 21:21:49', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-29 21:21:49', '2025-12-29 21:21:49', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (258, 0, '系统访客', NULL, NULL, 2, '植物新品种权申请流程：\n\n**第一步：准备阶段**\n1. 品种选育完成\n2. 收集整理材料\n3. 选择代理机构（可选）\n\n**第二步：申请提交**\n1. 填写申请表\n2. 准备说明书和照片\n3. 提交申请材料\n4. 缴纳申请费\n\n**第三步：初步审查**\n1. 形式审查（1-3个月）\n2. 补正材料（如需要）\n3. 公开申请信息\n\n**第四步：实质审查**\n1. DUS测试（12-18个月）\n2. 审查意见答复\n3. 补充材料提交\n\n**第五步：授权公告**\n1. 审查通过\n2. 缴纳授权费和年费\n3. 颁发品种权证书\n4. 公告授权信息\n\n**第六步：权利维护**\n1. 按时缴纳年费\n2. 维权保护\n3. 许可转让（可选）\n\n(来源: 业务规范常见问答库)', '植物新品种权申请流程：\n\n**第一步：准备阶段**\n1. 品种选育完成\n2. 收集整理材料\n3. 选择代理机构（可选）\n\n**第二步：申请提交**\n1. 填写申请表\n2. 准备说明书和照片\n3. 提交申请材料\n4. 缴纳申请费\n\n**第三步：初步审查**\n1. 形式审查（1-3个月）\n2. 补正材料（如需要）\n3. 公开申请信息\n\n**第四步：实质审查**\n1. DUS测试（12-18个月）\n2. 审查意见答复\n3. 补充材料提交\n\n**第五步：授权公告**\n1. 审查通过\n2. 缴纳授权费和年费\n3. 颁发品种权证书\n4. 公告授权信息\n\n**第六步：权利维护**\n1. 按时缴纳年费\n2. 维权保护\n3. 许可转让（可选）\n\n(来源: 业务规范常见问答库)', '2025-12-29 21:21:49', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-29 21:21:49', '2025-12-29 21:21:49', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (259, 0, '系统访客', NULL, NULL, 1, '费用呢', NULL, '2025-12-29 21:22:01', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-29 21:22:01', '2025-12-29 21:22:01', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (260, 0, '系统访客', NULL, NULL, 2, '申请植物新品种权的费用情况如下：\n- 初审费：1000 元。\n- 实质审查费：2500 元。\n- 年费：第 1 - 6 年每年 600 元，第 7 - 15 年每年 900 元，第 16 - 20 年每年 1200 元；品种权有效期方面，林木、果树、观赏树木为 25 年，其余一般为 20 年。\n\n(来源：《植物新品种权申请完整流程指南》) ', '申请植物新品种权的费用情况如下：\n- 初审费：1000 元。\n- 实质审查费：2500 元。\n- 年费：第 1 - 6 年每年 600 元，第 7 - 15 年每年 900 元，第 16 - 20 年每年 1200 元；品种权有效期方面，林木、果树、观赏树木为 25 年，其余一般为 20 年。\n\n(来源：《植物新品种权申请完整流程指南》) ', '2025-12-29 21:22:01', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-29 21:22:01', '2025-12-29 21:22:01', '系统访客', '系统访客', 0, 1);
