INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (262, 0, '系统访客', NULL, NULL, 2, '能否申请植物新品种权，关键看该植物是否在农业、林业保护目录内。目前资料中未显示葵花所属的向日葵属被列入农业已发布的11批、林业已发布的10批植物新品种保护目录，也不确定待发布的农业第12批目录情况。所以仅依据现有信息，无法确定葵花能申请植物新品种权，建议持续关注相关保护目录的更新。 ', '能否申请植物新品种权，关键看该植物是否在农业、林业保护目录内。目前资料中未显示葵花所属的向日葵属被列入农业已发布的11批、林业已发布的10批植物新品种保护目录，也不确定待发布的农业第12批目录情况。所以仅依据现有信息，无法确定葵花能申请植物新品种权，建议持续关注相关保护目录的更新。 ', '2025-12-29 21:22:19', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-29 21:22:19', '2025-12-29 21:22:19', '系统访客', '系统访客', 0, 1);
