INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (264, 0, '系统访客', NULL, NULL, 2, '仅依据目前掌握的信息，无法确定葵花能否申请植物新品种权。植物新品种权申请要求物种在农业、林业保护目录内，目前林业共正式发布10批、农业发布11批（第12批待发布）保护目录，但现有资料未显示葵花所属的向日葵属被列入这些已发布的目录中，你可关注后续农业第12批目录的发布情况。 ', '仅依据目前掌握的信息，无法确定葵花能否申请植物新品种权。植物新品种权申请要求物种在农业、林业保护目录内，目前林业共正式发布10批、农业发布11批（第12批待发布）保护目录，但现有资料未显示葵花所属的向日葵属被列入这些已发布的目录中，你可关注后续农业第12批目录的发布情况。 ', '2025-12-29 21:31:33', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-29 21:31:33', '2025-12-29 21:31:33', '系统访客', '系统访客', 0, 1);
