INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (268, 0, '系统访客', NULL, NULL, 2, '系统中的七个文件分别是《保护名录问题说明.docx》《林业局植物新品种保护名录（第1 - 10批）.docx》《林业局植物新品种保护名录第一批》《MBA高校篮球自由积分赛.docx》《植物育种基础概念》《植物新品种权申请完整流程指南》以及《美国植物新品种保护制度分析 (1).pdf》。 ', '系统中的七个文件分别是《保护名录问题说明.docx》《林业局植物新品种保护名录（第1 - 10批）.docx》《林业局植物新品种保护名录第一批》《MBA高校篮球自由积分赛.docx》《植物育种基础概念》《植物新品种权申请完整流程指南》以及《美国植物新品种保护制度分析 (1).pdf》。 ', '2025-12-30 21:44:49', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-30 21:44:49', '2025-12-30 21:44:49', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (269, 0, '系统访客', NULL, NULL, 1, 'MBA高校篮球自由积分赛 是什么内容', NULL, '2025-12-30 21:45:08', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-30 21:45:08', '2025-12-30 21:45:08', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (270, 0, '系统访客', NULL, NULL, 2, 'MBA高校篮球自由积分赛是完全自由的MBA篮球积分赛，具体内容如下：\n1. **参赛人员与组队规则**：本校在读学生或已毕业校友可自由组队参赛，每队人数5 - 12 人，赛季内队伍固定，不可重复报名。\n2. **比赛形式**\n    - **约战方式**：各队自行约战，不设固定赛程，不用赛前报备，不限定比赛时间。\n    - **赛制**：以 5v5 为主，比赛场地和时间由双方自行协商，不设统一裁判，双方认可比赛结果即有效。\n3. **成绩提交**：赛后需提交双方队名、最终比分、现场合影，审核通过后可计分；未提交成绩则该场不计分。\n4. **积分规则**\n    - **获胜**：赢一场得 3 分。\n    - **失败**：输一场得 1 分。\n    - **无效成绩**：得 0 分。\n5. **防刷分规则**：每队每天最多记 1 场比赛成绩，同一对手一周最多记 1 场比赛成绩。\n6. **赛季与排名**\n    - **赛季时长**：一个赛季为 3 个月，按总积分从高到低排名。\n    - **排名细则**：若积分相同，先比较胜场数，再比较参赛场次。半年积分排名前三的队伍和一支挑战者队伍，将进行冠亚季军争夺赛。\n7. **奖项设置（每赛季一次）**：设有冠军、亚军、季军以及最活跃球队（比赛场次最多）等奖项。\n8. **违规处理**\n    - **造假比分**：本场比赛计 0 分且给予警告。\n    - **打架斗殴**：直接取消本赛季参赛资格。 ', 'MBA高校篮球自由积分赛是完全自由的MBA篮球积分赛，具体内容如下：\n1. **参赛人员与组队规则**：本校在读学生或已毕业校友可自由组队参赛，每队人数5 - 12 人，赛季内队伍固定，不可重复报名。\n2. **比赛形式**\n    - **约战方式**：各队自行约战，不设固定赛程，不用赛前报备，不限定比赛时间。\n    - **赛制**：以 5v5 为主，比赛场地和时间由双方自行协商，不设统一裁判，双方认可比赛结果即有效。\n3. **成绩提交**：赛后需提交双方队名、最终比分、现场合影，审核通过后可计分；未提交成绩则该场不计分。\n4. **积分规则**\n    - **获胜**：赢一场得 3 分。\n    - **失败**：输一场得 1 分。\n    - **无效成绩**：得 0 分。\n5. **防刷分规则**：每队每天最多记 1 场比赛成绩，同一对手一周最多记 1 场比赛成绩。\n6. **赛季与排名**\n    - **赛季时长**：一个赛季为 3 个月，按总积分从高到低排名。\n    - **排名细则**：若积分相同，先比较胜场数，再比较参赛场次。半年积分排名前三的队伍和一支挑战者队伍，将进行冠亚季军争夺赛。\n7. **奖项设置（每赛季一次）**：设有冠军、亚军、季军以及最活跃球队（比赛场次最多）等奖项。\n8. **违规处理**\n    - **造假比分**：本场比赛计 0 分且给予警告。\n    - **打架斗殴**：直接取消本赛季参赛资格。 ', '2025-12-30 21:45:08', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-30 21:45:08', '2025-12-30 21:45:08', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (271, 0, '系统访客', NULL, NULL, 1, 'MBA高校篮球自由积分赛  违规处理\n 是什么', NULL, '2025-12-30 21:48:38', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-30 21:48:38', '2025-12-30 21:48:38', '系统访客', '系统访客', 0, 1);
INSERT INTO `z_ai_chat` (`id`, `user_id`, `user_name`, `customer_id`, `customer_name`, `message_type`, `content`, `reply_content`, `reply_time`, `session_id`, `context`, `intent`, `confidence`, `sentiment`, `keywords`, `is_satisfied`, `satisfaction_score`, `feedback`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (272, 0, '系统访客', NULL, NULL, 2, 'MBA高校篮球自由积分赛的违规处理规则如下：\n- **造假比分**：本场比赛记0分，并给予警告。\n- **打架斗殴**：直接取消涉事队伍本赛季的参赛资格。 ', 'MBA高校篮球自由积分赛的违规处理规则如下：\n- **造假比分**：本场比赛记0分，并给予警告。\n- **打架斗殴**：直接取消涉事队伍本赛季的参赛资格。 ', '2025-12-30 21:48:38', 'session_1766605655524_0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-30 21:48:38', '2025-12-30 21:48:38', '系统访客', '系统访客', 0, 1);
COMMIT;

