-- ----------------------------
-- Table structure for z_customer
-- ----------------------------
DROP TABLE IF EXISTS `z_customer`;
CREATE TABLE `z_customer` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `customer_name` varchar(100) NOT NULL COMMENT '客户名称(公司名称)',
  `contact_person` varchar(100) DEFAULT NULL COMMENT '联系人',
  `phone` varchar(50) DEFAULT NULL COMMENT '电话',
  `email` varchar(100) DEFAULT NULL COMMENT '邮箱',
  `customer_type` varchar(50) DEFAULT '企业' COMMENT '客户类型(企业, 个人, 事业单位等)',
  `customer_level` varchar(50) DEFAULT '普通' COMMENT '客户等级(普通, 重要, 核心)',
  `business_type` varchar(50) DEFAULT '品种权业务' COMMENT '业务类型',
  `status` tinyint DEFAULT '1' COMMENT '状态(1:启用 0:禁用)',
  `remarks` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `create_by` varchar(50) DEFAULT NULL,
  `update_by` varchar(50) DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_customer_name` (`customer_name`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='客户信息表';

