-- ----------------------------
-- Table structure for z_faq_qa
-- ----------------------------
DROP TABLE IF EXISTS `z_faq_qa`;
CREATE TABLE `z_faq_qa` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `question` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题',
  `answer` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '答案',
  `keywords` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关键词',
  `category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类',
  `priority` int DEFAULT '0' COMMENT '优先级',
  `hit_count` int DEFAULT '0' COMMENT '命中次数',
  `status` tinyint DEFAULT '1' COMMENT '状态(1:启用 0:禁用)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  FULLTEXT KEY `idx_question` (`question`)
) ENGINE=InnoDB AUTO_INCREMENT=151 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='FAQ问答表';

-- ----------------------------
-- Records of z_faq_qa
-- ----------------------------
BEGIN;
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (1, '植物新品种有多少种', '15', '植物，新品种，多少种', 'product', 10, 5, 1, '2025-12-04 23:43:58', '2025-12-04 23:43:58', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (2, '测试问题', '测试答案', NULL, '名词解释', 1, 0, 1, '2025-12-05 00:22:05', '2025-12-05 00:22:05', '测试', '测试', 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (3, '什么是植物新品种？', '植物新品种指经过人工培育或对发现的野生植物加以开发，具备新颖性、特异性、一致性、稳定性，并有适当命名的植物品种。\n\n来源：《中华人民共和国植物新品种保护条例》', '植物新品种,新品种,培育,新颖性,特异性,一致性,稳定性', '名词解释', 100, 7, 1, '2025-12-05 00:27:52', '2025-12-05 21:37:23', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (4, '什么是植物新品种权？', '植物新品种权（Plant Variety Rights）简称品种权，也称植物育种者权利（Plant Breeder Rights，PBR），是指完成育种的单位和个人对其获得授权的品种，享有排他的独占权，未经许可，任何人不得以商业目的生产、销售或重复使用该授权品种的繁殖材料。', '植物新品种权,品种权,育种者权利,PBR', '名词解释', 95, 3, 1, '2025-12-05 00:27:52', '2025-12-05 15:10:48', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (5, '什么是DUS测试？', 'DUS测试是授予植物新品种权的实质性条件，指对申请品种的特异性(Distinctness)、一致性(Uniformity)、稳定性(Stability)进行的栽培鉴定试验或室内分析。', 'DUS测试,特异性,一致性,稳定性', '名词解释', 90, 0, 1, '2025-12-05 00:27:52', '2025-12-05 00:27:52', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (6, '什么是新颖性？', '新颖性，是指申请品种权的植物新品种在申请日前该品种繁殖材料、收获材料未被销售、推广，或者经申请权人自行或者同意销售、推广该品种繁殖材料、收获材料，在中国境内未超过1年；在境外，木本、藤本植物品种未超过6年，其他植物品种未超过4年。\n\n来源：《植物新品种保护条例》', '新颖性,品种权,申请,销售,推广', '名词解释', 85, 0, 1, '2025-12-05 00:27:52', '2025-12-24 11:39:30', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (7, '什么是特异性？', '特异性指申请品种权的植物新品种应当明显区别于在递交申请以前已知的植物品种。', '特异性,品种权,区别,已知品种', '名词解释', 85, 0, 1, '2025-12-05 00:27:52', '2025-12-05 00:27:52', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (8, '什么是一致性？', '一致性指申请品种权的植物新品种经过繁殖，除可以预见的变异外，其相关的特征或者特性一致。', '一致性,品种权,繁殖,特征,特性', '名词解释', 85, 2, 1, '2025-12-05 00:27:52', '2025-12-05 00:27:52', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (9, '什么是稳定性？', '稳定性指申请品种权的植物新品种经过反复繁殖后，或者在特定繁殖周期结束时，其相关的特征或者特性保持不变。', '稳定性,品种权,繁殖,特征,特性', '名词解释', 85, 0, 1, '2025-12-05 00:27:52', '2025-12-05 00:27:52', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (10, '什么是繁殖材料？', '繁殖材料指可繁殖植物的种植材料或植物体的其他部分，包括籽粒、果实、根、茎、苗、芽、叶等，是植物新品种权的保护范围。', '繁殖材料,种植材料,籽粒,果实,根茎,保护范围', '名词解释', 80, 2, 1, '2025-12-05 00:27:52', '2025-12-05 00:27:52', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (11, '什么是植物新品种保护名录？', '植物新品种保护名录是由国务院农业、林业行政部门分批公布的受保护植物属和种的名单。只有列入名录的植物种类，才可以申请植物新品种权。', '植物新品种保护名录,保护名录,申请,植物种类', '名词解释', 80, 4, 1, '2025-12-05 00:27:52', '2025-12-05 22:14:39', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (12, '什么是品种？', '品种指经过人工选育或者发现并经过改良，形态特征和生物学特性一致，遗传性状相对稳定的植物群体。它是一个栽培学概念。', '品种,人工选育,形态特征,生物学特性,遗传性状', '名词解释', 75, 0, 1, '2025-12-05 00:27:53', '2025-12-05 00:27:53', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (13, '什么是品系？', '品系指在品种选育过程中，表现良好但尚未命名为品种的变异类型（如优良单株或株系）。它通常是品种选育的中间阶段，不得大面积推广。', '品系,品种选育,变异类型,优良单株', '名词解释', 75, 6, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (14, '什么是实质性派生品种（EDV）？', '以下情况下，一个品种应被视为原始品种的实质性派生品种：（Ⅰ）主要来源于原始品种，或来源于本身主要来源于原始品种的品种，同时保留了由原始品种的基因型或基因型组合产生的基本特征的表达；（Ⅱ）与最初的品种有明显的区别；并且（Ⅲ）除因派生引起的性状差异外，在表达由原始品种的基因型或基因型组合产生的基本性状方面与原始品种一致。', '实质性派生品种,EDV,原始品种,基因型,UPOV', '名词解释', 70, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (15, '什么是技术问卷？', '技术问卷是申请新品种权时需提交的关键文件之一。它是一份标准化的表格，要求申请人根据其品种的真实情况，填写一系列关于品种性状的描述，是DUS测试的重要参考和比对基础。', '技术问卷,新品种权,申请文件,品种性状,DUS测试', '名词解释', 70, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (16, '什么是强制许可？', '在符合法律规定的情况下（如国家利益或公共利益需要），审批机关可以不经品种权人同意，依法授权他人实施该品种权，但需向品种权人支付合理使用费。', '强制许可,品种权,国家利益,公共利益,使用费', '名词解释', 65, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (17, '什么是研究豁免？', '研究豁免是品种权的一种例外限制。允许将授权品种用于培育其他新品种或以科研为目的的活动，无需经过品种权人许可。', '研究豁免,品种权,例外限制,培育,科研', '名词解释', 65, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (18, '什么是测试指南？', '测试指南是由UPOV或各国审批机关制定的，针对特定植物属或种的DUS测试技术文件。它规定了测试方法、标准品种、性状表及判定标准，是进行DUS测试的权威依据。', '测试指南,UPOV,DUS测试,测试方法,标准品种', '名词解释', 65, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (19, '什么是优先权？', '优先权源自UPOV公约。在一个UPOV成员国首次提出申请后，在一定期限内（通常为12个月）就同一品种向其他成员国提出申请时，可以享有首次申请的日期作为在该国的申请日。', '优先权,UPOV公约,成员国,申请日,12个月', '名词解释', 60, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (20, '什么是形式审查？', '形式审查是审批机关对申请文件进行的初步审查，主要检查文件的齐全性、格式和明显缺陷。通过形式审查，申请才会进入实质审查阶段。', '形式审查,申请文件,初步审查,文件齐全性', '名词解释', 60, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (21, '什么是实质审查？', '实质审查是形式审查通过后，审批机关对品种是否具备新颖性、特异性、一致性、稳定性（DUS）等授权条件进行的实质性技术审查，是决定是否授权的关键环节。', '实质审查,DUS,新颖性,特异性,一致性,稳定性,授权', '名词解释', 60, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (22, '什么是授权公告？', '授权公告是审批机关对符合授权条件的品种发布的官方公告。公告标志着品种权正式生效，社会公众可以知晓并尊重此项权利。', '授权公告,品种权,官方公告,生效', '名词解释', 55, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (23, '新品种保护期限是多久？', '品种权的保护期限，自授权公告之日起，木本、藤本植物为25年，其他植物为20年。', '新品种保护期限,品种权,保护期限,25年,20年,木本植物,藤本植物', '名词解释', 55, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (24, '什么是近似品种？', '近似品种是在DUS测试中，被选定与申请品种进行最相似比对的已知品种。通过与其在各个性状上的详细比较，来最终判定申请品种是否具备特异性。', '近似品种,DUS测试,比对,已知品种,特异性', '名词解释', 50, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (25, '什么是标准品种？', '标准品种是在DUS测试中，为某些难以客观描述的性状（如抗病性强度）提供具体比对尺度的已知品种。例如，用品种A代表高抗，品种B代表中抗作为标尺。', '标准品种,DUS测试,比对尺度,抗病性', '名词解释', 50, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (26, '什么是分组性状？', '分组性状是用于快速筛选和缩小比对范围的性状，通常是非常明显、稳定的特征（如花色、株型）。审查员先用分组性状在已知品种库中筛选出近似品种候选组。', '分组性状,筛选,比对范围,花色,株型', '名词解释', 50, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (27, '什么是分子标记检测？', '分子标记检测是利用DNA技术分析品种遗传差异的现代方法。目前主要作为一致性和真实性判定的辅助工具，未来在实质性派生品种（EDV）判定中潜力巨大。', '分子标记检测,DNA技术,遗传差异,一致性,EDV', '名词解释', 45, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (28, '什么是权利用尽？', '权利用尽又称首次销售原则。指经品种权人许可售出的繁殖材料，他人后续的再销售、使用等行为不构成侵权。但未经许可的再生产行为不适用权利用尽。', '权利用尽,首次销售原则,繁殖材料,侵权', '名词解释', 45, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (29, '什么是品种侵权？', '品种侵权是指任何单位或个人未经品种权人许可，为商业目的对授权品种行使生产、销售、使用等排他性权利，且不属于农民特权或研究豁免范围的行为。', '品种侵权,品种权,商业目的,生产销售,农民特权,研究豁免', '名词解释', 45, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (30, '什么是品种权质押？', '品种权质押是指品种权人将其品种权作为债务履行的担保，向银行或金融机构融资的一种方式。质押合同需要在审批机关办理登记才能生效。', '品种权质押,质押,担保,融资,登记', '名词解释', 40, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (31, '什么是品种权转让？', '品种权转让是指品种权人将其所有权完全转移给受让方的法律行为。需要订立书面合同，并经审批机关登记和公告，转让行为自公告之日起生效。', '品种权转让,转让,所有权,书面合同,登记公告', '名词解释', 40, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (32, '什么是侵权赔偿？', '侵权赔偿是指法院在认定侵权成立后，判令侵权人向品种权人支付的经济损失。计算方式可以是权利人的实际损失、侵权人的违法所得，或参照品种权许可使用费的倍数。', '侵权赔偿,经济损失,实际损失,违法所得,许可使用费', '名词解释', 40, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (33, '什么是非主要农作物？', '非主要农作物是指稻、小麦、玉米、棉花、大豆这五种主要农作物之外的其他农作物。', '非主要农作物,主要农作物,稻,小麦,玉米,棉花,大豆', '名词解释', 35, 1, 1, '2025-12-05 00:29:18', '2025-12-05 15:07:51', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (34, '什么是品种登记？', '品种登记是指对列入登记目录的非主要农作物品种，在推广前需要依法向农业主管部门提出的登记申请。这是品种合法推广销售的前提。', '品种登记,非主要农作物,登记申请,推广销售', '名词解释', 35, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (35, '什么是属地管理？', '属地管理是品种登记申请的管理原则，一个品种只需在申请者住所所在地的一个省份申请登记。', '属地管理,品种登记,管理原则,省份', '名词解释', 30, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (36, '什么是品种登记优先受理？', '品种登记优先受理是指当两个以上申请者就同一品种申请登记时，优先受理最先提出的申请；同时申请的，优先受理该品种育种者的申请。', '品种登记优先受理,优先受理,育种者,申请', '名词解释', 30, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (37, '什么是DNA指纹？', 'DNA指纹指具有完全个体特异的DNA多态性，其个体识别能力足以与手指指纹相媲美。', 'DNA指纹,DNA多态性,个体识别,指纹', '名词解释', 30, 0, 1, '2025-12-05 00:29:18', '2025-12-05 00:29:18', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (38, '什么是品系？', '品系指在品种选育过程中，表现良好但尚未命名为品种的变异类型（如优良单株或株系）。它通常是品种选育的中间阶段，不得大面积推广。', '品系,品种选育,变异类型,优良单株', '名词解释', 75, 1, 1, '2025-12-05 08:17:47', '2025-12-05 08:17:47', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (39, '什么是实质性派生品种（EDV）？', '以下情况下，一个品种应被视为原始品种的实质性派生品种：（Ⅰ）主要来源于原始品种，或来源于本身主要来源于原始品种的品种，同时保留了由原始品种的基因型或基因型组合产生的基本特征的表达；（Ⅱ）与最初的品种有明显的区别；并且（Ⅲ）除因派生引起的性状差异外，在表达由原始品种的基因型或基因型组合产生的基本性状方面与原始品种一致。', '实质性派生品种,EDV,原始品种,基因型,UPOV', '名词解释', 70, 0, 1, '2025-12-05 08:17:47', '2025-12-05 08:17:47', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (40, '什么是技术问卷？', '技术问卷是申请新品种权时需提交的关键文件之一。它是一份标准化的表格，要求申请人根据其品种的真实情况，填写一系列关于品种性状的描述，是DUS测试的重要参考和比对基础。', '技术问卷,新品种权,申请文件,品种性状,DUS测试', '名词解释', 70, 0, 1, '2025-12-05 08:17:47', '2025-12-05 08:17:47', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (41, '什么是强制许可？', '在符合法律规定的情况下（如国家利益或公共利益需要），审批机关可以不经品种权人同意，依法授权他人实施该品种权，但需向品种权人支付合理使用费。', '强制许可,品种权,国家利益,公共利益,使用费', '名词解释', 65, 0, 1, '2025-12-05 08:17:47', '2025-12-05 08:17:47', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (42, '什么是研究豁免？', '研究豁免是品种权的一种例外限制。允许将授权品种用于培育其他新品种或以科研为目的的活动，无需经过品种权人许可。', '研究豁免,品种权,例外限制,培育,科研', '名词解释', 65, 0, 1, '2025-12-05 08:17:47', '2025-12-05 08:17:47', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (43, '什么是测试指南？', '测试指南是由UPOV或各国审批机关制定的，针对特定植物属或种的DUS测试技术文件。它规定了测试方法、标准品种、性状表及判定标准，是进行DUS测试的权威依据。', '测试指南,UPOV,DUS测试,测试方法,标准品种', '名词解释', 65, 0, 1, '2025-12-05 08:17:47', '2025-12-05 08:17:47', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (44, '什么是优先权？', '优先权源自UPOV公约。在一个UPOV成员国首次提出申请后，在一定期限内（通常为12个月）就同一品种向其他成员国提出申请时，可以享有首次申请的日期作为在该国的申请日。', '优先权,UPOV公约,成员国,申请日,12个月', '名词解释', 60, 0, 1, '2025-12-05 08:17:47', '2025-12-05 08:17:47', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (45, '什么是形式审查？', '形式审查是审批机关对申请文件进行的初步审查，主要检查文件的齐全性、格式和明显缺陷。通过形式审查，申请才会进入实质审查阶段。', '形式审查,申请文件,初步审查,文件齐全性', '名词解释', 60, 0, 1, '2025-12-05 08:17:47', '2025-12-05 08:17:47', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (46, '什么是实质审查？', '实质审查是形式审查通过后，审批机关对品种是否具备新颖性、特异性、一致性、稳定性（DUS）等授权条件进行的实质性技术审查，是决定是否授权的关键环节。', '实质审查,DUS,新颖性,特异性,一致性,稳定性,授权', '名词解释', 60, 0, 1, '2025-12-05 08:17:47', '2025-12-05 08:17:47', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (47, '什么是授权公告？', '授权公告是审批机关对符合授权条件的品种发布的官方公告。公告标志着品种权正式生效，社会公众可以知晓并尊重此项权利。', '授权公告,品种权,官方公告,生效', '名词解释', 55, 0, 1, '2025-12-05 08:17:47', '2025-12-05 08:17:47', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (48, '新品种保护期限是多久？', '品种权的保护期限，自授权公告之日起，木本、藤本植物为25年，其他植物为20年。', '新品种保护期限,品种权,保护期限,25年,20年,木本植物,藤本植物', '名词解释', 55, 0, 1, '2025-12-05 08:17:48', '2025-12-05 08:17:48', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (49, '什么是近似品种？', '近似品种是在DUS测试中，被选定与申请品种进行最相似比对的已知品种。通过与其在各个性状上的详细比较，来最终判定申请品种是否具备特异性。', '近似品种,DUS测试,比对,已知品种,特异性', '名词解释', 50, 0, 1, '2025-12-05 08:17:48', '2025-12-05 08:17:48', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (50, '什么是标准品种？', '标准品种是在DUS测试中，为某些难以客观描述的性状（如抗病性强度）提供具体比对尺度的已知品种。例如，用品种A代表高抗，品种B代表中抗作为标尺。', '标准品种,DUS测试,比对尺度,抗病性', '名词解释', 50, 0, 1, '2025-12-05 08:17:48', '2025-12-05 08:17:48', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (51, '什么是分组性状？', '分组性状是用于快速筛选和缩小比对范围的性状，通常是非常明显、稳定的特征（如花色、株型）。审查员先用分组性状在已知品种库中筛选出近似品种候选组。', '分组性状,筛选,比对范围,花色,株型', '名词解释', 50, 0, 1, '2025-12-05 08:17:48', '2025-12-05 08:17:48', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (52, '什么是分子标记检测？', '分子标记检测是利用DNA技术分析品种遗传差异的现代方法。目前主要作为一致性和真实性判定的辅助工具，未来在实质性派生品种（EDV）判定中潜力巨大。', '分子标记检测,DNA技术,遗传差异,一致性,EDV', '名词解释', 45, 0, 1, '2025-12-05 08:17:48', '2025-12-05 08:17:48', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (53, '什么是权利用尽？', '权利用尽又称首次销售原则。指经品种权人许可售出的繁殖材料，他人后续的再销售、使用等行为不构成侵权。但未经许可的再生产行为不适用权利用尽。', '权利用尽,首次销售原则,繁殖材料,侵权', '名词解释', 45, 0, 1, '2025-12-05 08:17:48', '2025-12-05 08:17:48', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (54, '什么是品种侵权？', '品种侵权是指任何单位或个人未经品种权人许可，为商业目的对授权品种行使生产、销售、使用等排他性权利，且不属于农民特权或研究豁免范围的行为。', '品种侵权,品种权,商业目的,生产销售,农民特权,研究豁免', '名词解释', 45, 0, 1, '2025-12-05 08:17:48', '2025-12-05 08:17:48', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (55, '什么是品种权质押？', '品种权质押是指品种权人将其品种权作为债务履行的担保，向银行或金融机构融资的一种方式。质押合同需要在审批机关办理登记才能生效。', '品种权质押,质押,担保,融资,登记', '名词解释', 40, 0, 1, '2025-12-05 08:17:48', '2025-12-05 08:17:48', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (56, '什么是品种权转让？', '品种权转让是指品种权人将其所有权完全转移给受让方的法律行为。需要订立书面合同，并经审批机关登记和公告，转让行为自公告之日起生效。', '品种权转让,转让,所有权,书面合同,登记公告', '名词解释', 40, 0, 1, '2025-12-05 08:17:48', '2025-12-05 08:17:48', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (57, '什么是侵权赔偿？', '侵权赔偿是指法院在认定侵权成立后，判令侵权人向品种权人支付的经济损失。计算方式可以是权利人的实际损失、侵权人的违法所得，或参照品种权许可使用费的倍数。', '侵权赔偿,经济损失,实际损失,违法所得,许可使用费', '名词解释', 40, 0, 1, '2025-12-05 08:17:48', '2025-12-05 08:17:48', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (58, '什么是非主要农作物？', '非主要农作物是指稻、小麦、玉米、棉花、大豆这五种主要农作物之外的其他农作物。', '非主要农作物,主要农作物,稻,小麦,玉米,棉花,大豆', '名词解释', 35, 0, 1, '2025-12-05 08:17:48', '2025-12-05 08:17:48', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (59, '什么是品种登记？', '品种登记是指对列入登记目录的非主要农作物品种，在推广前需要依法向农业主管部门提出的登记申请。这是品种合法推广销售的前提。', '品种登记,非主要农作物,登记申请,推广销售', '名词解释', 35, 0, 1, '2025-12-05 08:17:48', '2025-12-05 08:17:48', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (60, '什么是属地管理？', '属地管理是品种登记申请的管理原则，一个品种只需在申请者住所所在地的一个省份申请登记。', '属地管理,品种登记,管理原则,省份', '名词解释', 30, 0, 1, '2025-12-05 08:17:48', '2025-12-05 08:17:48', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (61, '什么是品种登记优先受理？', '品种登记优先受理是指当两个以上申请者就同一品种申请登记时，优先受理最先提出的申请；同时申请的，优先受理该品种育种者的申请。', '品种登记优先受理,优先受理,育种者,申请', '名词解释', 30, 0, 1, '2025-12-05 08:17:48', '2025-12-05 08:17:48', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (62, '什么是DNA指纹？', 'DNA指纹指具有完全个体特异的DNA多态性，其个体识别能力足以与手指指纹相媲美。', 'DNA指纹,DNA多态性,个体识别,指纹', '名词解释', 30, 0, 1, '2025-12-05 08:17:48', '2025-12-05 08:17:48', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (63, '申请基本条件是什么？', '申请植物新品种权需要满足以下基本条件：\n\n1. **新颖性**：申请品种在申请日前该品种繁殖材料未被销售，或者经育种者许可，在中国境内销售该品种繁殖材料未超过1年。\n\n2. **特异性**：申请品种应当明显区别于在递交申请以前已知的品种。\n\n3. **一致性**：申请品种经过繁殖，除可以预见的变异外，其相关的特征或者特性一致。\n\n4. **稳定性**：申请品种经过反复繁殖后或者在特定繁殖周期结束时，其相关的特征或者特性保持不变。\n\n5. **适当命名**：申请品种应当具备适当的名称，并与相同或者相近的植物属或者种中已知品种的名称相区别。', '申请条件,基本条件,新颖性,特异性,一致性,稳定性', '申请指南', 100, 6, 1, '2025-12-13 20:25:38', '2025-12-23 19:00:16', '系统管理员', '系统管理员', 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (64, '预审服务有什么优势？', '我们的预审服务具有以下优势：\n\n1. **专业评估**：由资深专家对申请材料进行全面审查，提前发现潜在问题。\n\n2. **提高成功率**：通过预审可以大幅提高正式申请的通过率，避免因材料问题导致的驳回。\n\n3. **节省时间**：提前发现并解决问题，避免反复修改，缩短整体申请周期。\n\n4. **降低风险**：减少因申请失败造成的经济损失和时间成本。\n\n5. **专业指导**：获得针对性的改进建议和优化方案。\n\n6. **优先处理**：预审客户享有优先服务通道。', '预审,优势,服务,专业评估', '服务介绍', 90, 4, 1, '2025-12-13 20:25:38', '2025-12-23 19:00:16', '系统管理员', '系统管理员', 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (65, '申请时间周期是多久？', '植物新品种权申请的时间周期如下：\n\n**正常流程**：\n- 材料准备：1-2个月\n- 初步审查：3-6个月\n- 实质审查：12-18个月\n- 授权公告：1-2个月\n- **总计**：约18-28个月\n\n**加急通道**（符合条件）：\n- 可缩短至12-15个月\n\n**影响因素**：\n1. 材料完整性和规范性\n2. 品种测试周期\n3. 审查机关工作量\n4. 补正材料的及时性\n\n**建议**：选择我们的预审服务可以有效缩短整体周期。', '时间,周期,多久,申请时间', '申请指南', 95, 3, 1, '2025-12-13 20:25:38', '2025-12-23 19:00:16', '系统管理员', '系统管理员', 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (66, '材料准备指南', '申请植物新品种权需要准备以下材料：\n\n**必备材料**：\n1. 植物新品种权请求书\n2. 说明书及照片\n3. 品种暂定名称\n\n**说明书内容**：\n- 品种来源及育种过程\n- 特征特性描述\n- 栽培技术要点\n- 品种对比说明\n\n**照片要求**：\n- 能够说明品种特征的彩色照片\n- 不同生长期的对比照片\n- 与近似品种的对比照片\n\n**其他材料**：\n- 测试报告（如有）\n- 审定证书（如有）\n- 委托书（委托代理时）\n\n**注意事项**：\n- 所有材料需加盖公章\n- 照片需清晰、规范\n- 描述需准确、详细', '材料,准备,指南,申请材料', '申请指南', 90, 3, 1, '2025-12-13 20:25:38', '2025-12-24 10:41:01', '系统管理员', '系统管理员', 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (67, '费用计算标准是什么？', '植物新品种权申请费用包括：\n\n**官方费用**：\n1. 申请费：1000元\n2. 审查费：2500元\n3. 年费：第1-6年每年300元，第7-15年每年450元，第16-20年每年900元\n\n**服务费用**（我方）：\n1. 基础代理费：5000-8000元\n2. 预审服务费：3000-5000元\n3. 材料撰写费：2000-4000元\n4. 加急服务费：另议\n\n**优惠政策**：\n- 批量申请享受折扣\n- 长期合作客户优惠\n- 特定品种补贴政策\n\n**付款方式**：\n- 分期付款\n- 一次性付款优惠\n\n**注**：具体费用根据品种类型和服务内容确定，详情请咨询客服。', '费用,价格,收费,标准', '费用说明', 85, 2, 1, '2025-12-13 20:25:38', '2025-12-24 10:41:01', '系统管理员', '系统管理员', 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (68, '植物新品种保护名录', '根据《植物新品种保护条例》，以下植物属或种列入保护名录：\n\n**粮食作物**：\n- 水稻、小麦、玉米、大豆、棉花等\n\n**蔬菜作物**：\n- 番茄、黄瓜、辣椒、白菜、萝卜等\n\n**果树**：\n- 苹果、梨、桃、葡萄、柑橘等\n\n**花卉**：\n- 月季、菊花、百合、郁金香等\n\n**林木**：\n- 杨树、松树、杉树等\n\n**其他**：\n- 牧草、药用植物、观赏植物等\n\n**查询方式**：\n1. 访问农业农村部官网\n2. 查看最新保护名录公告\n3. 咨询我们的专业顾问\n\n**注**：名录会定期更新，建议申请前确认最新版本。', '保护名录,植物名录,品种名录', '政策法规', 80, 0, 1, '2025-12-13 20:25:38', '2025-12-24 10:41:01', '系统管理员', '系统管理员', 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (69, '相关法律法规有哪些？', '植物新品种保护相关法律法规：\n\n**主要法律法规**：\n1. 《中华人民共和国植物新品种保护条例》\n2. 《植物新品种保护条例实施细则（农业部分）》\n3. 《植物新品种保护条例实施细则（林业部分）》\n4. 《中华人民共和国种子法》\n\n**国际公约**：\n- 《国际植物新品种保护公约》（UPOV公约）\n\n**部门规章**：\n- 《农业植物新品种权申请指南》\n- 《植物新品种测试指南》\n- 各类植物的特异性、一致性、稳定性测试指南\n\n**获取途径**：\n1. 农业农村部官网\n2. 国家林业和草原局官网\n3. 我们提供的法规汇编资料\n\n**建议**：申请前详细了解相关法规，确保合规申请。', '法律,法规,政策,条例', '政策法规', 85, 0, 1, '2025-12-13 20:25:38', '2025-12-24 10:45:34', '系统管理员', '系统管理员', 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (70, '申请流程是怎样的？', '植物新品种权申请流程：\n\n**第一步：准备阶段**\n1. 品种选育完成\n2. 收集整理材料\n3. 选择代理机构（可选）\n\n**第二步：申请提交**\n1. 填写申请表\n2. 准备说明书和照片\n3. 提交申请材料\n4. 缴纳申请费\n\n**第三步：初步审查**\n1. 形式审查（1-3个月）\n2. 补正材料（如需要）\n3. 公开申请信息\n\n**第四步：实质审查**\n1. DUS测试（12-18个月）\n2. 审查意见答复\n3. 补充材料提交\n\n**第五步：授权公告**\n1. 审查通过\n2. 缴纳授权费和年费\n3. 颁发品种权证书\n4. 公告授权信息\n\n**第六步：权利维护**\n1. 按时缴纳年费\n2. 维权保护\n3. 许可转让（可选）', '流程,步骤,申请流程,如何申请', '申请指南', 100, 0, 1, '2025-12-13 20:25:38', '2025-12-24 10:45:34', '系统管理员', '系统管理员', 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (71, '申请案例', '成功申请案例分享：\n\n**案例一：杂交水稻新品种**\n- 品种名称：丰优XX号\n- 申请时间：2022年3月\n- 授权时间：2023年9月\n- 特点：高产、抗病、优质\n- 成功要素：完整的育种记录、详细的特性描述、规范的测试报告\n\n**案例二：蔬菜新品种**\n- 品种名称：绿宝XX号黄瓜\n- 申请时间：2021年6月\n- 授权时间：2022年12月\n- 特点：耐储运、口感好、产量高\n- 成功要素：清晰的品种对比、专业的照片资料\n\n**案例三：花卉新品种**\n- 品种名称：彩虹XX月季\n- 申请时间：2020年9月\n- 授权时间：2022年3月\n- 特点：花色独特、花期长、抗性强\n- 成功要素：突出的特异性、完善的栽培技术\n\n**经验总结**：\n1. 材料准备要充分\n2. 特征描述要准确\n3. 照片质量要高\n4. 及时响应审查意见\n5. 选择专业代理机构', '案例,成功案例,申请案例,示例', '案例分享', 75, 0, 1, '2025-12-13 20:25:38', '2025-12-24 10:45:34', '系统管理员', '系统管理员', 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (72, '申请基本条件是什么？', '申请植物新品种权需要满足以下基本条件：\n\n1. **新颖性**：申请品种在申请日前该品种繁殖材料未被销售，或者经育种者许可，在中国境内销售该品种繁殖材料未超过1年。\n\n2. **特异性**：申请品种应当明显区别于在递交申请以前已知的品种。\n\n3. **一致性**：申请品种经过繁殖，除可以预见的变异外，其相关的特征或者特性一致。\n\n4. **稳定性**：申请品种经过反复繁殖后或者在特定繁殖周期结束时，其相关的特征或者特性保持不变。\n\n5. **适当命名**：申请品种应当具备适当的名称，并与相同或者相近的植物属或者种中已知品种的名称相区别。', '申请条件,基本条件,新颖性,特异性,一致性,稳定性', '申请指南', 100, 0, 1, '2025-12-16 13:45:19', '2025-12-24 10:47:53', '系统管理员', '系统管理员', 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (73, '预审服务有什么优势？', '我们的预审服务具有以下优势：\n\n1. **专业评估**：由资深专家对申请材料进行全面审查，提前发现潜在问题。\n\n2. **提高成功率**：通过预审可以大幅提高正式申请的通过率，避免因材料问题导致的驳回。\n\n3. **节省时间**：提前发现并解决问题，避免反复修改，缩短整体申请周期。\n\n4. **降低风险**：减少因申请失败造成的经济损失和时间成本。\n\n5. **专业指导**：获得针对性的改进建议和优化方案。\n\n6. **优先处理**：预审客户享有优先服务通道。', '预审,优势,服务,专业评估', '服务介绍', 90, 0, 1, '2025-12-16 13:45:19', '2025-12-24 10:47:53', '系统管理员', '系统管理员', 0);
