INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (77, '植物新品种保护名录', '根据《植物新品种保护条例》，以下植物属或种列入保护名录：\n\n**粮食作物**：\n- 水稻、小麦、玉米、大豆、棉花等\n\n**蔬菜作物**：\n- 番茄、黄瓜、辣椒、白菜、萝卜等\n\n**果树**：\n- 苹果、梨、桃、葡萄、柑橘等\n\n**花卉**：\n- 月季、菊花、百合、郁金香等\n\n**林木**：\n- 杨树、松树、杉树等\n\n**其他**：\n- 牧草、药用植物、观赏植物等\n\n**查询方式**：\n1. 访问农业农村部官网\n2. 查看最新保护名录公告\n3. 咨询我们的专业顾问\n\n**注**：名录会定期更新，建议申请前确认最新版本。', '保护名录,植物名录,品种名录', '政策法规', 80, 6, 1, '2025-12-16 13:45:19', '2025-12-24 10:48:20', '系统管理员', '系统管理员', 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (78, '相关法律法规有哪些？', '植物新品种保护相关法律法规：\n\n**主要法律法规**：\n1. 《中华人民共和国植物新品种保护条例》\n2. 《植物新品种保护条例实施细则（农业部分）》\n3. 《植物新品种保护条例实施细则（林业部分）》\n4. 《中华人民共和国种子法》\n\n**国际公约**：\n- 《国际植物新品种保护公约》（UPOV公约）\n\n**部门规章**：\n- 《农业植物新品种权申请指南》\n- 《植物新品种测试指南》\n- 各类植物的特异性、一致性、稳定性测试指南\n\n**获取途径**：\n1. 农业农村部官网\n2. 国家林业和草原局官网\n3. 我们提供的法规汇编资料\n\n**建议**：申请前详细了解相关法规，确保合规申请。', '法律,法规,政策,条例', '政策法规', 85, 0, 1, '2025-12-16 13:45:19', '2025-12-24 11:01:48', '系统管理员', '系统管理员', 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (79, '申请流程是怎样的？', '植物新品种权申请流程：\n\n**第一步：准备阶段**\n1. 品种选育完成\n2. 收集整理材料\n3. 选择代理机构（可选）\n\n**第二步：申请提交**\n1. 填写申请表\n2. 准备说明书和照片\n3. 提交申请材料\n4. 缴纳申请费\n\n**第三步：初步审查**\n1. 形式审查（1-3个月）\n2. 补正材料（如需要）\n3. 公开申请信息\n\n**第四步：实质审查**\n1. DUS测试（12-18个月）\n2. 审查意见答复\n3. 补充材料提交\n\n**第五步：授权公告**\n1. 审查通过\n2. 缴纳授权费和年费\n3. 颁发品种权证书\n4. 公告授权信息\n\n**第六步：权利维护**\n1. 按时缴纳年费\n2. 维权保护\n3. 许可转让（可选）', '流程,步骤,申请流程,如何申请', '申请指南', 100, 1, 1, '2025-12-16 13:45:19', '2025-12-24 11:01:48', '系统管理员', '系统管理员', 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (80, '申请案例', '成功申请案例分享：\n\n**案例一：杂交水稻新品种**\n- 品种名称：丰优XX号\n- 申请时间：2022年3月\n- 授权时间：2023年9月\n- 特点：高产、抗病、优质\n- 成功要素：完整的育种记录、详细的特性描述、规范的测试报告\n\n**案例二：蔬菜新品种**\n- 品种名称：绿宝XX号黄瓜\n- 申请时间：2021年6月\n- 授权时间：2022年12月\n- 特点：耐储运、口感好、产量高\n- 成功要素：清晰的品种对比、专业的照片资料\n\n**案例三：花卉新品种**\n- 品种名称：彩虹XX月季\n- 申请时间：2020年9月\n- 授权时间：2022年3月\n- 特点：花色独特、花期长、抗性强\n- 成功要素：突出的特异性、完善的栽培技术\n\n**经验总结**：\n1. 材料准备要充分\n2. 特征描述要准确\n3. 照片质量要高\n4. 及时响应审查意见\n5. 选择专业代理机构', '案例,成功案例,申请案例,示例', '案例分享', 75, 0, 1, '2025-12-16 13:45:19', '2025-12-24 11:01:48', '系统管理员', '系统管理员', 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (81, '什么是植物新品种？', '植物新品种指经过人工培育或对发现的野生植物加以开发，具备新颖性、特异性、一致性、稳定性，并有适当命名的植物品种。', '植物新品种,新品种', '名词解释', 0, 0, 1, '2025-12-24 11:18:28', '2025-12-24 11:18:28', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (82, '什么是DUS测试？', 'DUS测试是授予植物新品种权的实质性条件，指对申请品种的特异性(D)、一致性(U)、稳定性(S)进行的栽培鉴定试验。', 'DUS测试,特异性', '名词解释', 0, 0, 1, '2025-12-24 11:18:28', '2025-12-24 11:18:28', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (83, '保护期限是多久？', '品种权的保护期限，自授权公告之日起，木本、藤本植物为25年，其他植物为20年。', '保护期限,25年,20年', '名词解释', 0, 0, 1, '2025-12-24 11:18:28', '2025-12-24 11:18:28', NULL, NULL, 0);
