INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (147, '什么是植物新品种？', '植物新品种指经过人工培育或对发现的野生植物加以开发，具备新颖性、特异性、一致性、稳定性，并有适当命名的植物品种。', '植物新品种,新品种', '名词解释', 0, 0, 1, '2025-12-29 00:02:32', '2025-12-29 00:02:32', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (148, '什么是DUS测试？', 'DUS测试是授予植物新品种权的实质性条件，指对申请品种的特异性(D)、一致性(U)、稳定性(S)进行的栽培鉴定试验。', 'DUS测试,特异性', '名词解释', 0, 0, 1, '2025-12-29 00:02:32', '2025-12-29 00:02:32', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (149, '保护期限是多久？', '品种权的保护期限，自授权公告之日起，木本、藤本植物为25年，其他植物为20年。', '保护期限,25年,20年', '名词解释', 0, 0, 1, '2025-12-29 00:02:32', '2025-12-29 00:02:32', NULL, NULL, 0);
INSERT INTO `z_faq_qa` (`id`, `question`, `answer`, `keywords`, `category`, `priority`, `hit_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (150, '葵花能申请植物新品种权吗？', '向日葵（葵花）属于农业部发布的第1批植物新品种保护名录（1999年发布）。因此，向日葵品种完全符合申请条件，可以向农业农村部提交植物新品种权申请。', '葵花,向日葵,名录,品种权', '业务咨询', 0, 0, 1, '2025-12-30 11:16:25', '2025-12-30 11:16:25', NULL, NULL, 0);
COMMIT;

-- ----------------------------
-- Table structure for z_file_management
-- ----------------------------
DROP TABLE IF EXISTS `z_file_management`;
CREATE TABLE `z_file_management` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `file_name` varchar(255) NOT NULL COMMENT '文件名称',
  `file_path` varchar(500) NOT NULL COMMENT '文件存储路径',
  `file_type` varchar(50) DEFAULT NULL COMMENT '文件类型(后缀或MIME)',
  `file_size` bigint DEFAULT '0' COMMENT '文件大小(字节)',
  `category` varchar(50) DEFAULT NULL COMMENT '文件分类(file1, file2, etc.)',
  `classification` varchar(50) DEFAULT NULL COMMENT '所属系统(agriculture, forestry)',
  `remarks` varchar(500) DEFAULT NULL COMMENT '模板描述/备注',
  `seal_status` varchar(20) DEFAULT 'no-need' COMMENT '盖章状态(need:需盖章, sealed:已盖章, no-need:无需盖章)',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建者',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新者',
  `deleted` tinyint(1) DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=501 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='文件管理表';

