-- ----------------------------
-- Table structure for z_file_package
-- ----------------------------
DROP TABLE IF EXISTS `z_file_package`;
CREATE TABLE `z_file_package` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `package_no` varchar(64) NOT NULL COMMENT '打包编号',
  `package_name` varchar(255) DEFAULT NULL COMMENT '压缩包名称',
  `package_path` varchar(500) DEFAULT NULL COMMENT '压缩包路径',
  `package_type` varchar(20) DEFAULT 'all' COMMENT '打包类型(all, sealed, unsealed, custom)',
  `file_count` int DEFAULT '0' COMMENT '包含文件数量',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建者',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新者',
  `deleted` tinyint(1) DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='文件打包记录表';

