-- ----------------------------
-- Table structure for z_intention_registration
-- ----------------------------
DROP TABLE IF EXISTS `z_intention_registration`;
CREATE TABLE `z_intention_registration` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `customer_id` bigint DEFAULT NULL COMMENT '关联客户ID',
  `contract_id` varchar(50) DEFAULT NULL COMMENT '合同ID',
  `application_no` varchar(50) DEFAULT NULL COMMENT '申请号',
  `customer_name` varchar(100) DEFAULT NULL,
  `customer_phone` varchar(20) DEFAULT NULL,
  `customer_email` varchar(100) DEFAULT NULL,
  `intention_type` varchar(50) DEFAULT NULL COMMENT '意向类型 (INTENTION-洽谈意向, PROXY-委托申请)',
  `department` varchar(50) DEFAULT NULL COMMENT '所属部门(agriculture-农业, forestry-林业)',
  `contract_type` varchar(50) DEFAULT NULL COMMENT '合同类型',
  `agency_fee` decimal(10,2) DEFAULT NULL COMMENT '代理费',
  `application_fee` decimal(10,2) DEFAULT NULL COMMENT '申请费',
  `service_fee` decimal(10,2) DEFAULT NULL COMMENT '服务费',
  `total_fee` decimal(10,2) DEFAULT NULL COMMENT '总费',
  `intention_description` text COMMENT '意向描述',
  `variety_name` varchar(100) DEFAULT NULL COMMENT '品种名称',
  `crop_type` varchar(50) DEFAULT NULL COMMENT '作物种类',
  `status` varchar(20) DEFAULT 'PENDING' COMMENT '状态 (PENDING-待跟进, PROCESSED-已跟进, SIGNED-已签约, CANCELLED-已取消)',
  `submit_time` datetime DEFAULT NULL COMMENT '提交时间',
  `handler_name` varchar(50) DEFAULT NULL COMMENT '跟进人姓名',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remarks` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1010 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='洽谈意向与委托登记表';

