-- ----------------------------
-- Table structure for z_knowledge_base
-- ----------------------------
DROP TABLE IF EXISTS `z_knowledge_base`;
CREATE TABLE `z_knowledge_base` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `question_type` varchar(50) NOT NULL COMMENT '问题类型',
  `question` text NOT NULL COMMENT '问题内容',
  `answer` text NOT NULL COMMENT '答案内容',
  `keywords` text COMMENT '关键词',
  `category` varchar(50) DEFAULT NULL COMMENT '分类',
  `priority` int DEFAULT '0' COMMENT '优先级',
  `usage_count` int DEFAULT '0' COMMENT '使用次数',
  `success_rate` decimal(5,2) DEFAULT '0.00' COMMENT '成功率',
  `is_active` tinyint(1) DEFAULT '1' COMMENT '是否启用',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_knowledge_question_type` (`question_type`),
  KEY `idx_knowledge_category` (`category`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='知识库表';

-- ----------------------------
-- Records of z_knowledge_base
-- ----------------------------
BEGIN;
INSERT INTO `z_knowledge_base` (`id`, `question_type`, `question`, `answer`, `keywords`, `category`, `priority`, `usage_count`, `success_rate`, `is_active`, `created_at`, `updated_at`) VALUES (1, 'patent_application', '植物新品种权申请需要什么条件？', '植物新品种权申请需要满足新颖性、特异性、一致性和稳定性四个条件', '植物新品种,申请条件,新颖性,特异性', 'patent', 100, 0, 0.00, 1, '2025-12-08 12:32:22', '2025-12-08 12:32:22');
INSERT INTO `z_knowledge_base` (`id`, `question_type`, `question`, `answer`, `keywords`, `category`, `priority`, `usage_count`, `success_rate`, `is_active`, `created_at`, `updated_at`) VALUES (2, 'technical_disclosure', '技术交底书应该包含哪些内容？', '技术交底书应包含技术背景、技术问题、技术方案、有益效果等内容', '技术交底书,内容,技术方案', 'document', 90, 0, 0.00, 1, '2025-12-08 12:32:22', '2025-12-08 12:32:22');
INSERT INTO `z_knowledge_base` (`id`, `question_type`, `question`, `answer`, `keywords`, `category`, `priority`, `usage_count`, `success_rate`, `is_active`, `created_at`, `updated_at`) VALUES (3, 'proxy_service', '代理服务费用如何计算？', '代理服务费用根据申请类型、复杂程度、服务内容等因素综合计算', '代理服务,费用,计算', 'service', 80, 0, 0.00, 1, '2025-12-08 12:32:22', '2025-12-08 12:32:22');
COMMIT;

-- ----------------------------
-- Table structure for z_knowledge_document
-- ----------------------------
DROP TABLE IF EXISTS `z_knowledge_document`;
CREATE TABLE `z_knowledge_document` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文档标题',
  `content` longtext COLLATE utf8mb4_unicode_ci COMMENT '文档内容',
  `file_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件名',
  `file_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件类型(pdf/word/excel/txt)',
  `file_size` bigint DEFAULT NULL COMMENT '文件大小(字节)',
  `file_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件路径',
  `document_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文档类型',
  `tags` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标签(逗号分隔)',
  `category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类',
  `summary` text COLLATE utf8mb4_unicode_ci COMMENT '摘要',
  `keywords` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关键词',
  `view_count` int DEFAULT '0' COMMENT '查看次数',
  `download_count` int DEFAULT '0' COMMENT '下载次数',
  `status` tinyint DEFAULT '1' COMMENT '状态(1:启用 0:禁用)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `version` int NOT NULL DEFAULT '1' COMMENT '版本号',
  PRIMARY KEY (`id`),
  KEY `idx_title` (`title`),
  KEY `idx_category` (`category`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='知识库文档表';

-- ----------------------------
-- Records of z_knowledge_document
-- ----------------------------
