INSERT INTO `z_knowledge_document` (`id`, `title`, `content`, `file_name`, `file_type`, `file_size`, `file_path`, `document_type`, `tags`, `category`, `summary`, `keywords`, `view_count`, `download_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (1, '知识库测试文档', '这是一个测试知识库文档。\n\n本文档用于测试知识库管理功能。\n\n主要内容包括:\n1. 文档上传功能\n2. 文档列表展示\n3. 文档搜索功能\n4. 文档下载功能\n\n测试时间: Fri Dec 12 10:02:24 CST 2025\n', 'test_knowledge_doc.txt', 'txt', 237, 'uploads/knowledge/32f73a2e-07e4-4f88-8653-1fdff7a21368.txt', 'other', '测试,知识库', 'technical', '这是一个测试知识库文档。\n\n本文档用于测试知识库管理功能。\n\n主要内容包括:\n1. 文档上传功能\n2. 文档列表展示\n3. 文档搜索功能\n4. 文档下载功能\n\n测试时间: Fri Dec 12 10:02:24 CST 2025\n', NULL, 0, 0, 1, '2025-12-12 10:03:01', '2025-12-12 10:03:01', NULL, NULL, 0, 1);
INSERT INTO `z_knowledge_document` (`id`, `title`, `content`, `file_name`, `file_type`, `file_size`, `file_path`, `document_type`, `tags`, `category`, `summary`, `keywords`, `view_count`, `download_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (2, '美国植物新品种保护制度分析 (1).pdf', '·262· 2015年5月 市场论坛 中文科技期刊数据库 (文摘版 )经济管理 \n美国植物新品种保护制度分析 \n徐大明 \n北京大北农科技集团股份有限公司，北京 100080 \n摘 要 ：美国是最早对植物品种提供知识产权保护的国家，经过半个世纪的发展，建立了世界上独具特色的植物品种保护 \n制度。本文重点简述了美国植物品种保护制度发展历程，介绍了当时的立法背景及利益考量，分析美国植物品种保护制度的优 \n点与弊端，以期为完善我 国植物新品种保护制度提供借鉴。 \n关键词 ：植物新品种 ；保护制度 ；分析 \n中图分类号 ：D971．2 文献标识码 ：A 文章编号 ：1671。5616(2015)05．0262．01 \n美国是鼓励创新的国家，提倡对“创造力给予慷慨的激励”。 \n美国之所以成为种业强国，与其建立的植物品种保护制度密切 \n相关。该国植物品种保护制度具有悠久的历史和独特的发展历 \n程，从 1930年 《植物专利法》保护无性繁殖的植物 (块茎植 \n物除外)，到 1970《植物品种保护法》保护有性繁殖和块茎繁 \n殖的植物、1985年美国专利商标局对植物品种给予发明专利 \n保护，走了一条与其它国家不甚相同的保护之路。美国植物品 \n种保护制度，对鼓励其国内植物育种创新、提升其种子产业的 \n国际竞争力发挥了重要的作用。 \n1专利框架内的植物专利法 \n美国是世界上最早对植物品种提供知识产权保护的国家， \n他们的 《植物专利法》(简称’PPA)是世界上第一部专门保护 \n有生命发明的知识产权法律 [1】，该法规中的四个条款，后被并 \n入美国专利法第 l61—164条。 \n1．1立法背景 \n但长期以来，植物品种一直排斥在专利保护之外。美国专 \n利商标局拒绝为植物授予专利权。主要原因是植物品种被认为 \n是 自然产物，自然产物不应当授予专利。而且植物品种也无法 \n满足美国专利法 ll2条规定的书面描述要求。根据该法书面描 \n述要求，发明说明书应对发明做全面、清楚的说明，使得相关 \n领域中的技术人员能够实施该发明。而植物品种说明书即便公 \n开品种系谱以及选育过程，其他人也无法遵循其选育过程而选 \n育出相同的品种即无法实施该发明。 \n1．2认识突破 \n随着育种技术的发展，美国社会逐步认识到人工培育的植 \n物品种并非是自然产物，而是人与 自然共同作用的产物。育种 \n者和育种技术的介入成为主导、决定因素。人工培育的植物品 \n种不是自然产物，而是人类智力成果 也应当得到与工业发明 \n相似的待遇和激励。 \n1930年国会制定 《植物专利法》。《植物专利法》对植物 \n品种的书面描述要求做了特殊的规定，“如果对发明的说明是 \n尽可能的完整，则不能因为不符合本法 l12规定而宣布任何植 \n物专利无效”(35U．S．C．162)。 \n1．3利益考量 \n由于大部分有性繁殖和块茎繁殖的植物属于粮食作物，考 \n虑到给予有性繁殖和块茎繁殖的植物专利权，可 能会提高农业 \n种植成本而遭受有关组织和农民群体的强烈反对，故 《植物专 \n利法》并未将有性繁殖和块茎繁殖的植物纳入植物专利的客体 \n范围。 \n《植物专利法》仅适用于无性繁殖的植物 (块茎植物除 \n外)，是各方利益权衡和博弈的结果。“议会的最后方案即考虑 \n了以无性繁殖方式为主的园艺业和果树行业的利益，又考虑了 \n以有性繁殖方式为主的从事农作物种植和生产的农民群体的利 \n益”【”。 \n1．4重要意义 \n尽管 《植物专利法》保护范围有限，但已是巨大的突破。 \n植物品种首次登堂入室，成为可专利的客体，开启植物品种知 \n识产权保护的历史。该法对美国和其他国家植物品种保护制度 \n的未来发展产生了深远的影响。 \n2专门 (特别)法一 《植物品种保护法》 \n1970年美国国会通过 《植物品种保护法》(简称 PVPA)。 \n该法赋予植物品种育种者不同于专利的特别权利，并受到起源 \n于欧洲的 《国际植物新品种保护联盟公约》(UPOV公约)的 \n影响。 \n2．1立法背景 \n美国种子行业组织 ．种子贸易协会 (ASTA)曾经尝试推 \n动将有性繁殖植物纳入 《植物专利法》的保护范围，但此举没 \n有获得美国农业部、农民等团体的支持。之后转而借鉴欧洲专 \n门的植物品种保护法律制度，提出 “植物品种保护法案”。 \n2．2利益考量 \n以植物专利方式保护有性繁殖植物的方案之所以遭到反 \n对，主要是担心对有性繁殖植物提供专利保护会阻碍种质资源 \n的自由交流、会阻碍育种创新以及种子价格的上涨。为此，《植 \n物品种保护法》特别规定 “研究豁免”、“农民特权”等品种权 \n的限制于例外，最终该法案得以通过。 \n2．3 《植物品种法》具有特色的几项内容 \n2．3．1保护范围 \n仅适用有性繁殖和块茎繁殖的植物。 \n2．3．2新颖性 \n“品种生产的杂交种的销售和处理，视为该品种收获材料 \n的销售和处理。”(7U．S．C．2401)也就是，杂交种 的销售或处 \n理会破坏亲本 (自交系)的新颖性。 \n2．3．3申请阶段的保密 \n授权前品种申请书及其内容处于保密状态，但可以公开品 \n种名称、种类、申请人姓名信息。 \n2．3．4权利用尽 \n“在美国受保护的植物品种，经所有者同意售出后，行使 \n任何关于繁殖材料或收获材料包括整个植物和部分植物的行 \n为，不视为对品种所有者权利的侵犯，除非相关行为涉及该品 \n种的进一步繁殖，或者涉及该品种材料的出口，使得相关品种 \n的繁殖材料进入一个对该品种所属于的属或种不予保护的国 \n家，除非该出口材料最终用于消费目的。”(7U．S．C．2541) \n2．3．5在先权利 \n“本法不得减损任何人或专利权人的利益继承者生产或出 \n售品种的权利，若此人开发或生产该品种，先于一方当事人申 \n请植物品种保护证书的有效申请日一年以上。”(7U．S．C．2542) \n中文科技期刊数据库 (文摘版 )经济管理 市场论坛 2015年5月 ·263· \n2．3．6保存种子的权利和种植豁免 (农民特权) \n农民可以保存经品种所有人授权用于播种目的的种子所生 \n产的种子，可以使用保存种子在自己的农场进行生产。 \n2．3．7赔偿数额 \n“一旦发现侵权行为，法院应判给足以弥补侵权的损害赔 \n偿，但无论如何不得低于侵权人使用该品种应当支付的合理特 \n许使用费，以及法院规定的利息和诉讼费。陪审团没有确定损 \n害赔偿金时，法院应当确定赔偿金。在这两种情况下，法院都 \n可以将赔偿金增加到原定金额的三倍。”(7U．S．C．2564) \n3发明专利保护一 《美国专利法》 \n《植物专利法》为无性繁殖的植物提供植物专利的保护，《植 \n物品种保护法》为有性繁殖和块茎繁殖的植物提供品种权保护， \n“但对种子产业来说仍 ‘存有敞开的漏洞’(a gaping hole stil \nremained)⋯⋯。由于 PPA所规定的植物专利权和和 PVPA所 \n规定的特别权利的保护对象，从生物学的角度看，都只是作为 \n植物品种存在的植物，也就是为某些基因的组合提供保护。但 \n这些基因本身不受保护。育种者可以利用这些受保护的植物品 \n种基因培育新的基因组合或者新的植物品种。因此，种子产业 \n认为需要一种保护形式⋯⋯阻止独立育种者或者其他种子公司 \n轻易利用相关育种者／创新者的研究与培育成果。”[1 \n美国种子产业一直追求以发明专利 (非植物专利)保护其 \n植物发明。随着基因工程技术的发展，植物品种可以以基因构 \n成描述，这一使得相关的植物发明可以满足 《专利法》第 112 \n条所规定的书面披露要求。 \n1985年，美国专利局在 Ex parte Hibberd一案中支持植物 \n品种获得发明专利保护。此案开启了发明专利保护植物品种之 \n先河。至此，“美国在专利法的框架内对植物品种采用植物专 \n利和普通专利两种保护制度。”【2 \n4美国植物品种保护制度的利与弊 \n4．1赋予育种者更多的权利选择。给予植物品种充分的知识产 \n权保护 \n美国联邦最高法院 ：“这三部法律提供了重叠保护互不排 \n斥，植物新品种的发明者可以根据每一法律申请保护，同时从 \n每一种保护中受益。”植物品种育种者即可以申请发明专利保 \n护，也可申请植物专利或植物品种证书保护。由于发明专利有 \n较强的保护力度，其效力不受 “研究豁免”、“农民特权”的限 \n制，美国种子企业大多采取 “强发明专利弱品种权”的保护策 \n略。植物品种 以申请发明专利为主，以申请品种权保护证书为 \n辅。对于重要的品种 (种子作物)同时申请发明专利和品种权。 \n对于杂交品种 (F，)，一般仅申请发明专利保护。 \n4．2存在过度保护问题，不利于种质资源的合理利用 \n美国植物品种保护制度发展的前期，种质 (育种)资源的 \n自由交流、农民利益的保护一直是植物品种保护制度设计所追 \n求的价值 目标。但发展后期逐渐背离前期的目标和价值取向， \n过于侧重育种者的保护，而忽视种质资源的公共价值和对农民 \n利益的保护。 \n对于发明专利保护的植物品种，他人不得利用其进行育种 \n等科研活动，农民也不得保存该品种种子并在 自己的农场种植。 \n发明专利虽使育种者权利获得最充分的保障，但同时也限制种 \n质资源的合理利用，限制了植物育种创新，限制农民的权利， \n并且容易形成对品种资源事实上的垄断，对整个产业的发展不 \n利。植物品种不同工业发明 (狭义)有其特殊性。对于工业发 \n明而言，只要公开其说明书，其技术思想就为全社会所共享， \n人们会从中获得技术的启迪、进发智慧的火花，促进技术的进 \n一 步创新。对于植物品种，若不能研究豁免，即便公开其品种 \n系谱、选育过程甚至基因图谱，人们不能或很少获得有益的技 \n术启迪。从这个意义上讲，植物品种发明的公开，并未为该行 \n业的技术进步作出应有贡献却不当获得独占的权利，这显然不 \n符合专利制度 “公开换取保护”的精神。 \n植物品种是人类智力成果，同时也是大自然的产物。任何 \n人不能贪天之功为己有。我们在保障育种者权益的同时，也应 \n当允许种质资源的合理使用，以促进育种创新，增进公共利益。 \n参考文献 \n[1】李菊丹．国际植物新品种保护制度研究[M]．浙江：浙江大 \n学出版社，2011． \n[2】李春华，王敏 ．中美植物新品种保护制度之比较 [J】-前沿， \n2004 (4)：l52．154． \n(上接第195页)台的建设，形成乡镇，以及街道在进行就业 \n服务方面的全面性对接过程，同时可以形成各项就业业务方面 \n的全面延伸过程，形成就业服务工作的具体化、流程化和规范 \n化。 \n3．3积极建构和优化内部服务 \n在内部服务形成全面性优化的过程中进行软硬件建设是其 \n中的一个重要环节之一，在中心建设的过程中从服务台，综合 \n服务区，信息发布交流，职业指导，创业指导，就业援助，失 \n业保险，职业培训等方面进行宣传，形成服务设施和服务流程 \n的全面性优化管理情况。在网络服务方面需要构建失业登记服 \n务，就业资金审核，培训系统，招聘系统，创业系统，档案管 \n理系统和公关决策系统等。在劳动就业服务中心人员塑造方面， \n一\n个要素是形成内部工作人员在理论方面的丰富，另外一个要 \n素是进行 “双指导师”的建构，也就是在就业创业理论方面进 \n行指导，以及在创业实践等方面形成实践指导 】。在便捷性服 \n务方面形成县乡村的网络覆盖，让群众可以就近办事，加强与 \n银行合作，在村和社区的基础上建立EPOS银行存取款平台， \n让群众 “实现缴费不出村，领取在家门”的目标。 \n总之，就业服务中心作为劳动保障部门的下属机构，在进 \n行服务经济建设的过程中需要发挥自身的特长和优势。在就业 \n服务中心工作提升过程中服务工作质量、水平和效率提高的过 \n程中，要充分实现就业的总体目标，形成就业信息化建设，推 \n动就业建设，实现在便民、利民和惠民方面的优化，提升服务 \n能力和水平 [5】。在创业塑造和支持，就业服务平台建构，以及 \n进行全面性服务方面形成优化，推动形成高质量和优化性的全 \n面服务过程。 \n参考文献 \n[1】孟令超 ．浅谈新时期再就业服务中心工作思路的有效转变 \n[J]．工会博览 ：理论研究，2011(12)：12． \n[2】孟令超 ．如何提高再就业服务中心工作人员的工作效率 [J]． \n大观周刊，2011(41)：3． \n[3】张仰．完善社会保障制度的财政思考 [J】．河南社会科学， \n2o0l(4)：59． \n【4】朱田庆，史云波．对再就业服务中心管理工作的思考 [J】．经 \n济与管理，2002(7)：52． \n【5】刘玫．政府人才服务机构提升大学生就业服务水平的研 \n究一一以成阳市人才交流中心为例 ．【D]．西安理工大学，2014． \n', '美国植物新品种保护制度分析 (1).pdf', 'pdf', 214909, 'uploads/knowledge/2514d24c-092a-40fb-92c5-8a0540580c6e.pdf', 'other', '美国植物保护制度分析', 'technical', '·262· 2015年5月 市场论坛 中文科技期刊数据库 (文摘版 )经济管理 \n美国植物新品种保护制度分析 \n徐大明 \n北京大北农科技集团股份有限公司，北京 100080 \n摘 要 ：美国是最早对植物品种提供知识产权保护的国家，经过半个世纪的发展，建立了世界上独具特色的植物品种保护 \n制度。本文重点简述了美国植物品种保护制度发展历程，介绍了当时的立法背景及利益考量，分析美国植物品种保护制度的优 ...', NULL, 0, 0, 1, '2025-12-13 21:00:28', '2025-12-13 21:00:28', NULL, NULL, 0, 1);
INSERT INTO `z_knowledge_document` (`id`, `title`, `content`, `file_name`, `file_type`, `file_size`, `file_path`, `document_type`, `tags`, `category`, `summary`, `keywords`, `view_count`, `download_count`, `status`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`, `version`) VALUES (3, '保护名录问题说明.docx', '文件说明：植物新品种权申请的物种需在农业、林业保护目录内，两份目录有重叠部分，但分开管理；目前林业共正式发布10批、农业发布11批（第12批待发布），其中包括能够申请植物新品种权的植物中文属名或种名，以及对应的拉丁文名。\n\n简单例子\n①凤仙花能否申请？\n凤仙花（Impatiens balsamina L.）为凤仙花属（Impatiens）植物，凤仙花属被纳入林业植物新品种保护目录第七批，因此可以申请。\n\n复杂例子\n①深灰槭（Acer caesium）能否申请？（深灰槭并不为目录中的原文名称，能否实现检索？）\n深灰槭（Acer caesium）为槭属（Acer Linn.）植物，槭属被纳入林业植物新品种保护目录第三批，因此可以申请。\n②槭能否申请？\n槭并不直接存在目录中，但用户可能是想咨询某种槭属植物，槭属被纳入林业植物新品种保护目录第三批，因此可以申请。\n\n\n', '保护名录问题说明.docx', 'docx', 11221, 'uploads/knowledge/366ef629-5bd1-423b-91ed-10565b38c830.docx', 'other', '', 'other', '文件说明：植物新品种权申请的物种需在农业、林业保护目录内，两份目录有重叠部分，但分开管理；目前林业共正式发布10批、农业发布11批（第12批待发布），其中包括能够申请植物新品种权的植物中文属名或种名，以及对应的拉丁文名。\n\n简单例子\n①凤仙花能否申请？\n凤仙花（Impatiens balsamina L.）为凤仙花属（Impatiens）植物，凤仙花属被纳入林业植物新品种保护目录第七批，因此可以申...', NULL, 0, 0, 1, '2025-12-24 19:35:52', '2025-12-24 19:35:52', NULL, NULL, 0, 1);
