-- ----------------------------
-- Table structure for z_plant_variety
-- ----------------------------
DROP TABLE IF EXISTS `z_plant_variety`;
CREATE TABLE `z_plant_variety` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '品种ID',
  `variety_name` varchar(200) NOT NULL COMMENT '品种名称',
  `scientific_name` varchar(200) DEFAULT NULL COMMENT '学名',
  `plant_family` varchar(100) DEFAULT NULL COMMENT '植物科',
  `plant_genus` varchar(100) DEFAULT NULL COMMENT '植物属',
  `breeder` varchar(200) DEFAULT NULL COMMENT '育种者',
  `breeding_method` varchar(100) DEFAULT NULL COMMENT '育种方法',
  `application_date` date DEFAULT NULL COMMENT '申请日期',
  `review_status` varchar(50) DEFAULT '待审核' COMMENT '审核状态',
  `data_quality_rating` varchar(10) DEFAULT 'A' COMMENT '数据质量评级',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `description` text COMMENT '品种描述',
  `characteristics` text COMMENT '特征特性',
  `cultivation_requirements` text COMMENT '栽培要求',
  `disease_resistance` text COMMENT '抗病性',
  `yield` varchar(200) DEFAULT NULL COMMENT '产量',
  `quality` varchar(200) DEFAULT NULL COMMENT '品质',
  `adaptability` varchar(200) DEFAULT NULL COMMENT '适应性',
  `market_value` varchar(200) DEFAULT NULL COMMENT '市场价值',
  `protection_status` varchar(50) DEFAULT NULL COMMENT '保护状态',
  `protection_number` varchar(100) DEFAULT NULL COMMENT '保护号',
  `protection_expiry_date` date DEFAULT NULL COMMENT '保护到期日期',
  `transgenic_info` text COMMENT '转基因信息',
  `genetic_background` text COMMENT '遗传背景',
  `breeding_history` text COMMENT '育种历史',
  `test_results` text COMMENT '测试结果',
  `certification_info` text COMMENT '认证信息',
  `commercialization_status` varchar(50) DEFAULT NULL COMMENT '商业化状态',
  `market_performance` text COMMENT '市场表现',
  `user_feedback` text COMMENT '用户反馈',
  `expert_evaluation` text COMMENT '专家评价',
  `risk_assessment` text COMMENT '风险评估',
  `recommendation_level` varchar(20) DEFAULT NULL COMMENT '推荐等级',
  `tags` varchar(500) DEFAULT NULL COMMENT '标签',
  `notes` text COMMENT '备注',
  `category` varchar(100) DEFAULT NULL COMMENT '分类',
  `status` varchar(20) NOT NULL DEFAULT '草稿' COMMENT '状态',
  PRIMARY KEY (`id`),
  KEY `idx_variety_name` (`variety_name`),
  KEY `idx_scientific_name` (`scientific_name`),
  KEY `idx_plant_family` (`plant_family`),
  KEY `idx_plant_genus` (`plant_genus`),
  KEY `idx_review_status` (`review_status`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='植物品种表';

