-- ----------------------------
-- Table structure for z_seeds
-- ----------------------------
DROP TABLE IF EXISTS `z_seeds`;
CREATE TABLE `z_seeds` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '种子ID',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '种子名称',
  `scientific_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学名',
  `category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类',
  `variety` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '品种',
  `origin` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产地',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '描述',
  `characteristics` text COLLATE utf8mb4_unicode_ci COMMENT '特征特性',
  `planting_method` text COLLATE utf8mb4_unicode_ci COMMENT '种植方法',
  `harvest_time` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收获时间',
  `storage_condition` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '储存条件',
  `quality` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '品质等级',
  `supplier` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商',
  `contact_info` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系方式',
  `price` decimal(10,2) DEFAULT NULL COMMENT '价格',
  `stock` int DEFAULT '0' COMMENT '库存数量',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '正常' COMMENT '状态',
  `image_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图片URL',
  `tags` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标签',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  KEY `idx_name` (`name`),
  KEY `idx_category` (`category`),
  KEY `idx_status` (`status`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_composite` (`category`,`status`,`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='种子信息表';

-- ----------------------------
-- Records of z_seeds
-- ----------------------------
BEGIN;
