-- ----------------------------
-- Table structure for z_service_recommendations
-- ----------------------------
DROP TABLE IF EXISTS `z_service_recommendations`;
CREATE TABLE `z_service_recommendations` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `intention_id` bigint DEFAULT NULL COMMENT '意向ID',
  `service_type` varchar(50) NOT NULL COMMENT '服务类型',
  `service_name` varchar(100) NOT NULL COMMENT '服务名称',
  `service_description` text COMMENT '服务描述',
  `estimated_cost` decimal(10,2) DEFAULT NULL COMMENT '预估费用',
  `estimated_duration` int DEFAULT NULL COMMENT '预估时长(天)',
  `confidence_score` decimal(5,2) DEFAULT NULL COMMENT '推荐置信度',
  `is_selected` tinyint(1) DEFAULT '0' COMMENT '是否被选中',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='服务推荐表';

-- ----------------------------
-- Records of z_service_recommendations
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for z_sys_user
-- ----------------------------
DROP TABLE IF EXISTS `z_sys_user`;
CREATE TABLE `z_sys_user` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '用户ID',
  `username` varchar(50) NOT NULL COMMENT '用户名',
  `password` varchar(255) NOT NULL COMMENT '密码',
  `real_name` varchar(100) NOT NULL COMMENT '真实姓名',
  `email` varchar(100) DEFAULT NULL COMMENT '邮箱',
  `phone` varchar(20) DEFAULT NULL COMMENT '手机号',
  `id_card` varchar(18) DEFAULT NULL COMMENT '身份证号',
  `address` text COMMENT '地址',
  `postcode` varchar(10) DEFAULT NULL COMMENT '邮编',
  `role` varchar(20) NOT NULL DEFAULT 'USER' COMMENT '角色：ADMIN-管理员，AGENT-代理员，USER-用户',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1-正常，0-禁用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  KEY `idx_username` (`username`),
  KEY `idx_role` (`role`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户表';

-- ----------------------------
-- Records of z_sys_user
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for z_variety_trait
-- ----------------------------
DROP TABLE IF EXISTS `z_variety_trait`;
CREATE TABLE `z_variety_trait` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '性状ID',
  `variety_id` bigint NOT NULL COMMENT '品种ID',
  `trait_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '性状代码',
  `trait_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '性状名称',
  `trait_category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '性状类别',
  `trait_value` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '性状值',
  `trait_unit` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '性状单位',
  `trait_description` text COLLATE utf8mb4_unicode_ci COMMENT '性状描述',
  `data_source` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据来源',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `test_method` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '测试方法',
  `test_location` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '测试地点',
  `test_year` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '测试年份',
  `test_season` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '测试季节',
  `reliability` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '可靠性',
  `notes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  KEY `idx_variety_id` (`variety_id`),
  KEY `idx_trait_code` (`trait_code`),
  KEY `idx_trait_category` (`trait_category`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='品种性状表';

